@login_required(login_url='/accounts/login/')
@staff_required
def bulk_transfer_api_orders(request):
    """
    Bulk-mark selected API orders as transferred into main workflow.
    POST: order_ids (list), sets is_transferred=True, transferred_at, transferred_by.
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    from django.utils import timezone
    order_ids = request.POST.getlist('order_ids[]')
    if not order_ids:
        return JsonResponse({'success': False, 'error': 'No orders selected'}, status=400)

    try:
        updated = orders_models.Order.objects.filter(
            id__in=order_ids,
            is_transferred=False
        ).update(
            is_transferred=True,
            transferred_at=timezone.now(),
            transferred_by=request.user,
            order_status='to_review',
        )
        return JsonResponse({'success': True, 'updated': updated})
    except Exception as e:
        logger.exception('bulk_transfer_api_orders error: %s', e)
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@login_required(login_url='/accounts/login/')
@staff_required
def preview_api_import(request):
    """
    POST: Return preview of mapped data for selected Google Sheet rows.
    Used in the import wizard before actual import.
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    import json as _json, re as _re
    business_id = request.POST.get('business_id', '').strip()
    platform_ids = request.POST.getlist('platform_ids[]')

    if not business_id or not platform_ids:
        return JsonResponse({'success': False, 'error': 'Missing business_id or platform_ids'}, status=400)

    try:
        business = business_models.Business.objects.get(business_id=business_id)
        api = business.business_settings_api.filter(is_verify_api=True).first()
        if not api:
            return JsonResponse({'success': False, 'error': 'No approved API config'}, status=400)
    except business_models.Business.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Business not found'}, status=404)

    if api.api_type == 'shopify':
        SHOPIFY_FIELDS = [
            {'name': 'row_number',          'label': '#',                'sheet_col': ''},
            {'name': 'client_order_code',   'label': 'Order ID',         'sheet_col': 'Shopify'},
            {'name': 'customer_name',       'label': 'Customer Name',    'sheet_col': 'Shopify'},
            {'name': 'customer_phone',      'label': 'Phone',            'sheet_col': 'Shopify'},
            {'name': 'customer_address',    'label': 'Address',          'sheet_col': 'Shopify'},
            {'name': 'cod_amount',          'label': 'Total Price (QAR)', 'sheet_col': 'Shopify'},
            {'name': 'financial_status',    'label': 'Payment Status',   'sheet_col': 'Shopify'},
            {'name': 'fulfillment_status',  'label': 'Fulfillment',      'sheet_col': 'Shopify'},
        ]
        preview_rows = []
        already_imported = []
        errors = []
        try:
            import shopify as _shopify
            shop_name = (api.site_api_url or '').replace('https://', '').replace('http://', '').replace('.myshopify.com', '').strip()
            session = _shopify.Session(shop_name, api.api_version or '2023-10', api.api_access_token)
            _shopify.ShopifyResource.activate_session(session)
            for i, pid in enumerate(platform_ids):
                try:
                    already = orders_models.Order.objects.filter(
                        business=business,
                        original_order_data__platform_id=str(pid),
                        original_order_data__source='shopify',
                    ).exists()
                    if already:
                        already_imported.append(str(pid))

                    o = _shopify.Order.find(pid)
                    shipping = getattr(o, 'shipping_address', None)
                    billing  = getattr(o, 'billing_address', None)
                    addr     = shipping or billing
                    addr_str = ' '.join(filter(None, [
                        getattr(addr, 'address1', '') or '',
                        getattr(addr, 'city',     '') or '',
                    ])) if addr else ''
                    phone    = getattr(addr, 'phone', '') or getattr(getattr(o, 'customer', None), 'phone', '') or ''
                    customer = getattr(o, 'customer', None)
                    cname    = f"{getattr(customer,'first_name','') or ''} {getattr(customer,'last_name','') or ''}".strip() or getattr(o, 'name', str(pid))
                    # Build product_matches from line items
                    li_items = getattr(o, 'line_items', []) or []
                    product_matches = []
                    for li in li_items:
                        li_title = getattr(li, 'title', '') or getattr(li, 'name', '') or ''
                        li_qty = int(getattr(li, 'quantity', 1) or 1)
                        if li_title:
                            matched, mtype = match_product(business, li_title)
                            product_matches.append({
                                'raw': li_title,
                                'qty': li_qty,
                                'matched_name': matched.item_name if matched else None,
                                'match_type': mtype,
                            })
                    # Build package description
                    pkg_parts = [f"{pm['raw']} x{pm['qty']}" for pm in product_matches]
                    preview_rows.append({
                        'row_number':         str(pid),
                        'client_order_code':  getattr(o, 'name', str(pid)),
                        'customer_name':      cname,
                        'customer_phone':     phone,
                        'customer_address':   addr_str,
                        'cod_amount':         str(getattr(o, 'total_price', '') or ''),
                        'financial_status':   getattr(o, 'financial_status', '') or '',
                        'fulfillment_status': getattr(o, 'fulfillment_status', '') or 'unfulfilled',
                        'package_desc':       ', '.join(pkg_parts)[:255] if pkg_parts else '',
                        'product_matches':    product_matches,
                    })
                except Exception as e:
                    errors.append(f"{pid}: {e}")
            _shopify.ShopifyResource.clear_session()
        except Exception as e:
            return JsonResponse({'success': False, 'error': f'Shopify connection failed: {e}'})
        return JsonResponse({
            'success': True,
            'preview': preview_rows,
            'fields': SHOPIFY_FIELDS,
            'total_rows': len(platform_ids),
            'already_imported': already_imported,
            'errors': errors,
        })

    elif api.api_type == 'woocommerce':
        WOO_FIELDS = [
            {'name': 'row_number',          'label': '#',                'sheet_col': ''},
            {'name': 'client_order_code',   'label': 'Order ID',         'sheet_col': 'WooCommerce'},
            {'name': 'customer_name',       'label': 'Customer Name',    'sheet_col': 'WooCommerce'},
            {'name': 'customer_phone',      'label': 'Phone',            'sheet_col': 'WooCommerce'},
            {'name': 'customer_address',    'label': 'Address',          'sheet_col': 'WooCommerce'},
            {'name': 'cod_amount',          'label': 'Total Price (QAR)', 'sheet_col': 'WooCommerce'},
            {'name': 'financial_status',    'label': 'Payment Status',   'sheet_col': 'WooCommerce'},
        ]
        preview_rows = []
        already_imported = []
        try:
            from woocommerce import API as _WooAPI
            wcapi = _WooAPI(
                url=api.site_api_url or '',
                consumer_key=api.api_key or '',
                consumer_secret=api.api_secret or '',
                version='wc/v3',
                timeout=15,
            )
            for pid in platform_ids:
                already = orders_models.Order.objects.filter(
                    business=business,
                    original_order_data__platform_id=str(pid),
                    original_order_data__source='woocommerce',
                ).exists()
                if already:
                    already_imported.append(str(pid))
                try:
                    r = wcapi.get(f'orders/{pid}')
                    if r.status_code != 200:
                        continue
                    o = r.json()
                    billing  = o.get('billing', {})
                    shipping = o.get('shipping', {})
                    addr     = shipping if any(shipping.values()) else billing
                    addr_str = ' '.join(filter(None, [
                        addr.get('address_1', ''),
                        addr.get('city', ''),
                    ]))
                    phone  = billing.get('phone', '') or ''
                    cname  = f"{billing.get('first_name','') or ''} {billing.get('last_name','') or ''}".strip() or str(pid)
                    preview_rows.append({
                        'row_number':        str(pid),
                        'client_order_code': str(o.get('number', pid)),
                        'customer_name':     cname,
                        'customer_phone':    phone,
                        'customer_address':  addr_str,
                        'cod_amount':        str(o.get('total', '')),
                        'financial_status':  o.get('status', ''),
                    })
                except Exception:
                    pass
        except Exception as e:
            return JsonResponse({'success': False, 'error': f'WooCommerce connection failed: {e}'})
        return JsonResponse({
            'success': True,
            'preview': preview_rows,
            'fields': WOO_FIELDS,
            'total_rows': len(platform_ids),
            'already_imported': already_imported,
        })

    elif api.api_type not in ('google_sheet',):
        return JsonResponse({'success': False, 'error': f'Preview not supported for source: {api.api_type}'})

    try:
        import gspread
        from google.oauth2.credentials import Credentials as _GCreds
        from google.auth.transport.requests import Request as _GReq
        from django.conf import settings as django_settings
        from pathlib import Path as _Path

        sheet_url = api.google_sheet_url or api.site_api_url or ''
        token_path = _Path(django_settings.BASE_DIR) / getattr(
            django_settings, 'GOOGLE_SHEETS_TOKEN_FILE', 'google_sheets_token.json'
        )
        if not token_path.exists():
            return JsonResponse({'success': False, 'error': 'Google Sheets not authorized.'}, status=400)

        _td = _json.loads(token_path.read_text())
        creds = _GCreds(
            token=_td.get('access_token'),
            refresh_token=_td.get('refresh_token'),
            token_uri=_td.get('token_uri', 'https://oauth2.googleapis.com/token'),
            client_id=_td.get('client_id'),
            client_secret=_td.get('client_secret'),
            scopes=_td.get('scope', '').split(),
        )
        if creds.expired and creds.refresh_token:
            creds.refresh(_GReq())
            _td['access_token'] = creds.token
            token_path.write_text(_json.dumps(_td, indent=2))

        gc = gspread.authorize(creds)
        match = _re.search(r'/spreadsheets/d/([^/]+)', sheet_url)
        if not match:
            return JsonResponse({'success': False, 'error': 'Invalid Google Sheet URL.'}, status=400)
        sheet_id = match.group(1)
        gid_match = _re.search(r'gid=(\d+)', sheet_url)
        gid = int(gid_match.group(1)) if gid_match else 0

        spreadsheet = gc.open_by_key(sheet_id)
        worksheet = None
        for ws in spreadsheet.worksheets():
            if ws.id == gid:
                worksheet = ws
                break
        if worksheet is None:
            worksheet = spreadsheet.sheet1

        all_values = worksheet.get_all_values()
        if len(all_values) <= 1:
            for ws in spreadsheet.worksheets():
                if ws.id == (worksheet.id if worksheet else -1):
                    continue
                candidate = ws.get_all_values()
                if len(candidate) > 1:
                    worksheet = ws
                    all_values = candidate
                    break

        headers = all_values[0] if all_values else []
        data_rows = all_values[1:] if all_values else []

        saved_mapping = api.column_mapping or {}

        def col_idx_by_header(header_name):
            for j, h in enumerate(headers):
                if h.strip() == header_name.strip():
                    return j
            return None

        def get_idx(field_name, *_ignored_auto_keys):
            # Mapping-config is authoritative — no auto-detection fallback.
            if field_name in saved_mapping:
                return col_idx_by_header(saved_mapping[field_name])
            return None

        idx_name = get_idx('customer_name', 'name', 'customer name', 'customer', 'client name')
        idx_phone = get_idx('customer_phone', 'phone', 'mobile', 'phone number', 'contact')
        idx_whatsapp = get_idx('customer_whatsapp', 'whatsapp', 'phone 2', 'alternate phone')
        idx_email = get_idx('customer_email', 'email', 'e-mail', 'customer email')
        idx_address = get_idx('customer_address', 'address', 'delivery address', 'location')
        idx_landmark = get_idx('dl_landmark', 'city', 'landmark', 'customer city', 'area')
        idx_building = get_idx('dl_building', 'building', 'villa', 'building no')
        idx_street = get_idx('dl_street', 'street', 'street no', 'street number')
        idx_zone = get_idx('dl_zone', 'zone', 'zone no', 'zone number')
        idx_cod = get_idx('cod_amount', 'cod', 'amount', 'cod amount', 'price', 'total')
        idx_dl_amount = get_idx('dl_amount', 'delivery fee', 'shipping fee', 'delivery amount')
        idx_order = get_idx('client_order_code', 'order', 'order number', 'order #', 'order id')
        idx_product = get_idx('package_desc', 'product', 'product name', 'item', 'items', 'package desc')
        idx_sku = get_idx('sku', 'sku', 'product sku', 'item sku', 'article')
        idx_qty = get_idx('package_qty', 'qty', 'quantity', 'count', 'package qty')
        idx_deadline = get_idx('deadline_date', 'deadline', 'delivery date', 'preferred', 'day')
        idx_notes = get_idx('seller_notes', 'notes', 'seller notes', 'note', 'remarks', 'comment')
        idx_internal = get_idx('internal_notes', 'internal notes', 'staff notes', 'notes by ezzy')

        def cell(row, idx):
            if idx is not None and idx < len(row):
                v = row[idx]
                return str(v).strip() if v is not None else ''
            return ''

        # Build all field indices with labels and mapped sheet column
        all_fields = [
            ('row_number', 'Row', None),
            ('client_order_code', 'Order ID', idx_order),
            ('customer_name', 'Customer Name', idx_name),
            ('customer_phone', 'Phone 1', idx_phone),
            ('customer_whatsapp', 'Phone 2 / WhatsApp', idx_whatsapp),
            ('customer_email', 'Email', idx_email),
            ('customer_address', 'Customer Address', idx_address),
            ('dl_landmark', 'City / Landmark', idx_landmark),
            ('dl_building', 'Villa / Building No', idx_building),
            ('dl_street', 'Street No', idx_street),
            ('dl_zone', 'Zone No', idx_zone),
            ('cod_amount', 'Price / COD Amount', idx_cod),
            ('dl_amount', 'Delivery Fee', idx_dl_amount),
            ('package_desc', 'Package Desc', idx_product),
            ('sku', 'SKU', idx_sku),
            ('package_qty', 'Package Qty', idx_qty),
            ('deadline_date', 'Day & Time', idx_deadline),
            ('seller_notes', 'Seller Notes', idx_notes),
            ('internal_notes', 'Internal Notes', idx_internal),
        ]

        # Only include fields that have a mapped column (non-None idx)
        active_fields = [('row_number', 'Row', '')]  # always show row
        for fname, flabel, fidx in all_fields:
            if fname == 'row_number':
                continue
            if fidx is not None:
                # Get the sheet column header name for display
                sheet_col = headers[fidx] if fidx < len(headers) else ''
                active_fields.append((fname, flabel, sheet_col))

        preview_rows = []
        already_imported = []
        for pid in platform_ids:
            parts = pid.split('_', 2)
            if len(parts) < 2:
                continue
            row_idx = int(parts[1])
            sheet_row = row_idx + 2

            # Check if already imported
            is_imported = orders_models.Order.objects.filter(
                business=business,
            ).filter(
                Q(original_order_data__platform_id=pid) |
                Q(original_order_data__row_number=sheet_row)
            ).exists()
            if is_imported:
                already_imported.append(pid)
                continue

            if row_idx >= len(data_rows):
                continue

            row = data_rows[row_idx]
            # Build row_data dynamically from active_fields
            row_data = {'platform_id': pid}
            field_idx_map = {
                'row_number': None,
                'client_order_code': idx_order,
                'customer_name': idx_name,
                'customer_phone': idx_phone,
                'customer_whatsapp': idx_whatsapp,
                'customer_email': idx_email,
                'customer_address': idx_address,
                'dl_landmark': idx_landmark,
                'dl_building': idx_building,
                'dl_street': idx_street,
                'dl_zone': idx_zone,
                'cod_amount': idx_cod,
                'dl_amount': idx_dl_amount,
                'package_desc': idx_product,
                'sku': idx_sku,
                'package_qty': idx_qty,
                'deadline_date': idx_deadline,
                'seller_notes': idx_notes,
                'internal_notes': idx_internal,
            }
            for fname, flabel, scol in active_fields:
                if fname == 'row_number':
                    row_data['row_number'] = sheet_row
                elif fname == 'customer_name':
                    row_data['customer_name'] = cell(row, field_idx_map.get(fname)) or f'Row {sheet_row}'
                elif fname == 'client_order_code':
                    row_data['client_order_code'] = cell(row, field_idx_map.get(fname)) or str(sheet_row)
                else:
                    row_data[fname] = cell(row, field_idx_map.get(fname))

            # Build product match preview for verify step
            idx_products_preview = {}
            for i in range(1, 11):
                idx_products_preview[f'product_{i}'] = get_idx(f'product_{i}', f'product {i}', f'product:{i}', f'item {i}')
                idx_products_preview[f'count_{i}'] = get_idx(f'count_{i}', f'count {i}', f'count:{i}', f'qty {i}')
            product_matches = []
            # Single package_desc column
            pn0 = cell(row, field_idx_map.get('package_desc'))
            if pn0:
                matched0, mtype0 = match_product(business, pn0)
                product_matches.append({
                    'raw': pn0,
                    'qty': 1,
                    'matched_name': matched0.item_name if matched0 else None,
                    'match_type': mtype0,
                })
            # product_1..10 columns
            for i in range(1, 11):
                pn = cell(row, idx_products_preview.get(f'product_{i}'))
                if pn:
                    pqty = int(cell(row, idx_products_preview.get(f'count_{i}')) or 1) if idx_products_preview.get(f'count_{i}') is not None else 1
                    matched, mtype = match_product(business, pn)
                    product_matches.append({
                        'raw': pn,
                        'qty': pqty,
                        'matched_name': matched.item_name if matched else None,
                        'match_type': mtype,
                    })
            row_data['product_matches'] = product_matches
            preview_rows.append(row_data)

        return JsonResponse({
            'success': True,
            'api_type': 'google_sheet',
            'preview': preview_rows,
            'fields': [{'name': f[0], 'label': f[1], 'sheet_col': f[2]} for f in active_fields],
            'already_imported': already_imported,
            'has_mapping': bool(saved_mapping),
            'mapping_fields': len(saved_mapping),
        })
    except Exception as e:
        logger.exception('preview_api_import error: %s', e)
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


def match_product(business, pname):
    """
    Cascading product name match for import.
    Returns (Product|None, match_type_str).
    match_type: 'exact' | 'sku' | 'barcode' | 'alias' | 'fuzzy' | 'unmatched'
    """
    name = pname.strip()
    if not name:
        return None, 'unmatched'
    # Parse coded format (e.g. '08__DAGGER OUD____BUK011' → name='DAGGER OUD', sku='BUK011')
    clean_name, coded_sku = _parse_coded_product_name(name)
    if coded_sku:
        # Try clean name first
        p = product_models.Product.objects.filter(business=business, item_name__iexact=clean_name).first()
        if p:
            return p, 'exact'
        # Try extracted SKU
        p = product_models.Product.objects.filter(business=business, item_sku__iexact=coded_sku).first()
        if p:
            return p, 'sku'
        # Use clean name for remaining cascading matches
        name = clean_name
    # 1. Exact item_name
    p = product_models.Product.objects.filter(business=business, item_name__iexact=name).first()
    if p:
        return p, 'exact'
    # 2. Exact SKU
    p = product_models.Product.objects.filter(business=business, item_sku__iexact=name).first()
    if p:
        return p, 'sku'
    # 3. Exact barcode
    p = product_models.Product.objects.filter(business=business, barcode__iexact=name).first()
    if p:
        return p, 'barcode'
    # 4. Client aliases (client_names comma-separated field)
    for prod in product_models.Product.objects.filter(business=business).exclude(client_names__isnull=True).exclude(client_names=''):
        for alias in prod.get_client_names_list():
            if alias.lower() == name.lower():
                return prod, 'alias'
    # 5. Substring: item_name contains pname
    p = product_models.Product.objects.filter(business=business, item_name__icontains=name).first()
    if p:
        return p, 'fuzzy'
    # 6. Word-overlap: ≥2 shared tokens, ≥50% score
    tokens = set(name.lower().split())
    if len(tokens) >= 2:
        best, best_score = None, 0
        for prod in product_models.Product.objects.filter(business=business):
            prod_tokens = set(prod.item_name.lower().split())
            overlap = len(tokens & prod_tokens)
            if overlap < 2:
                continue
            score = overlap / max(len(tokens), len(prod_tokens))
            if score >= 0.5 and score > best_score:
                best, best_score = prod, score
        if best:
            return best, 'fuzzy'
    return None, 'unmatched'


@login_required(login_url='/accounts/login/')
@staff_required
def import_api_orders(request):
    """
    POST: Fetch selected platform orders by platform_id from Shopify/WooCommerce
    and create Order records in the DB (is_transferred=False, ready for review).
    POST params: business_id, platform_ids[] (list of platform order IDs), source
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    import json
    from django.utils import timezone as dj_tz

    business_id = request.POST.get('business_id', '').strip()
    platform_ids = request.POST.getlist('platform_ids[]')
    source = request.POST.get('source', '').strip()

    # Parse row overrides (editable verify rows)
    row_overrides_raw = request.POST.get('row_overrides', '').strip()
    row_overrides = {}
    if row_overrides_raw:
        try:
            row_overrides = json.loads(row_overrides_raw)
        except (json.JSONDecodeError, TypeError):
            row_overrides = {}

    if not business_id or not platform_ids:
        return JsonResponse({'success': False, 'error': 'Missing business_id or platform_ids'}, status=400)

    try:
        business = business_models.Business.objects.get(business_id=business_id)
        api = business.business_settings_api.filter(is_verify_api=True).first()
        if not api:
            return JsonResponse({'success': False, 'error': 'No approved API config for this business'}, status=400)
    except business_models.Business.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Business not found'}, status=404)

    created = 0
    skipped = 0
    errors = []
    created_orders = []

    # Determine ImportLog source type
    log_source_map = {'shopify': 'shopify', 'woocommerce': 'woocommerce', 'google_sheet': 'google_sheet'}
    import_log = orders_models.ImportLog.objects.create(
        business=business,
        source=log_source_map.get(api.api_type, api.api_type),
        status='processing',
        initiated_by=request.user,
        total_rows=len(platform_ids),
        source_meta={
            'api_type': api.api_type,
            'api_settings_id': api.id,
            'platform_ids': platform_ids,
            'site_url': api.site_api_url or '',
        },
    )

    try:
        if api.api_type == 'shopify':
            import shopify
            shop_name = (api.site_api_url or '').replace('https://', '').replace('http://', '').replace('.myshopify.com', '').strip()
            session = shopify.Session(shop_name, api.api_version or '2023-10', api.api_access_token)
            shopify.ShopifyResource.activate_session(session)

            for pid in platform_ids:
                try:
                    # Skip if already imported
                    if orders_models.Order.objects.filter(
                        business=business,
                        original_order_data__platform_id=pid,
                        original_order_data__source='shopify'
                    ).exists():
                        skipped += 1
                        continue

                    o = shopify.Order.find(pid)
                    shipping = getattr(o, 'shipping_address', None)
                    billing = getattr(o, 'billing_address', None)
                    addr = shipping or billing
                    addr_str = ' '.join(filter(None, [
                        getattr(addr, 'address1', '') or '',
                        getattr(addr, 'city', '') or '',
                    ])) if addr else ''
                    phone = getattr(addr, 'phone', '') or ''
                    customer = getattr(o, 'customer', None)
                    customer_name = f"{getattr(customer, 'first_name', '')} {getattr(customer, 'last_name', '')}".strip() if customer else ''
                    # Extract line items for storage
                    line_items_raw = getattr(o, 'line_items', []) or []
                    line_items_data = []
                    for li in line_items_raw:
                        line_items_data.append({
                            'title': getattr(li, 'title', '') or '',
                            'name': getattr(li, 'name', '') or '',
                            'quantity': int(getattr(li, 'quantity', 1) or 1),
                            'price': str(getattr(li, 'price', 0) or 0),
                            'sku': getattr(li, 'sku', '') or '',
                        })
                    original_data = {
                        'source': 'shopify',
                        'platform_id': str(o.id),
                        'name': o.name,
                        'financial_status': o.financial_status,
                        'fulfillment_status': o.fulfillment_status,
                        'total_price': str(o.total_price),
                        'currency': o.currency,
                        'created_at': str(o.created_at),
                        'line_items': line_items_data,
                    }

                    _cod = 0
                    try:
                        _cod = int(float(str(o.total_price).replace(',', '').strip()))
                    except (ValueError, TypeError):
                        pass

                    # Apply row overrides from editable verify UI
                    import re as _re_shopify
                    ovr = row_overrides.get(str(pid), row_overrides.get(pid, {}))
                    if ovr:
                        if 'customer_name' in ovr:
                            customer_name = ovr['customer_name']
                        if 'customer_phone' in ovr:
                            phone = ovr['customer_phone']
                        if 'customer_address' in ovr:
                            addr_str = ovr['customer_address']
                        if 'cod_amount' in ovr:
                            try:
                                _cod = int(float(_re_shopify.sub(r'[^\d.]', '', ovr['cod_amount']))) if ovr['cod_amount'] else 0
                            except (ValueError, TypeError):
                                pass
                        if 'package_desc' in ovr:
                            pass  # Will be used below

                    # Build package description from line items
                    line_items = getattr(o, 'line_items', []) or []
                    pkg_parts = []
                    total_qty = 0
                    for li in line_items:
                        title = getattr(li, 'title', '') or getattr(li, 'name', '') or ''
                        qty = int(getattr(li, 'quantity', 1) or 1)
                        if title:
                            pkg_parts.append(f"{title} x{qty}")
                            total_qty += qty

                    _pkg_desc = ovr.get('package_desc', ', '.join(pkg_parts))[:255] if ovr else ', '.join(pkg_parts)[:255]
                    _client_order_code = ovr.get('client_order_code', '') if ovr else ''

                    order = orders_models.Order.objects.create(
                        business=business,
                        client_order_code=_client_order_code or getattr(o, 'name', str(pid)),
                        customer_name=customer_name or o.name,
                        customer_phone=phone,
                        customer_address=addr_str,
                        cod_amount=_cod,
                        package_description=_pkg_desc if _pkg_desc else '',
                        package_qty=total_qty or 1,
                        order_status='to_review',
                        is_transferred=False,
                        original_order_data=original_data,
                    )

                    # Create OrderItems from Shopify line items
                    for li in line_items:
                        li_title = getattr(li, 'title', '') or getattr(li, 'name', '') or ''
                        li_qty = int(getattr(li, 'quantity', 1) or 1)
                        li_price = 0
                        try:
                            li_price = float(str(getattr(li, 'price', 0) or 0).replace(',', ''))
                        except (ValueError, TypeError):
                            pass
                        if li_title:
                            matched, mtype = match_product(business, li_title)
                            orders_models.OrderItem.objects.create(
                                order=order,
                                product=matched,
                                quantity=li_qty,
                                unit_price=matched.item_price if matched else li_price,
                                notes=li_title if not matched else matched.item_name,
                            )
                            if matched and mtype == 'fuzzy':
                                matched.add_client_name(li_title)

                    created_orders.append(order)
                    created += 1
                except Exception as e:
                    errors.append(f"{pid}: {e}")

            shopify.ShopifyResource.clear_session()

        elif api.api_type == 'woocommerce':
            from woocommerce import API as WooAPI
            wcapi = WooAPI(
                url=api.site_api_url or '',
                consumer_key=api.api_key or '',
                consumer_secret=api.api_secret or '',
                version='wc/v3',
                timeout=15,
            )
            for pid in platform_ids:
                try:
                    if orders_models.Order.objects.filter(
                        business=business,
                        original_order_data__platform_id=pid,
                        original_order_data__source='woocommerce'
                    ).exists():
                        skipped += 1
                        continue

                    r = wcapi.get(f'orders/{pid}')
                    if r.status_code != 200:
                        errors.append(f"#{pid}: HTTP {r.status_code}")
                        continue
                    o = r.json()
                    billing = o.get('billing', {})
                    shipping = o.get('shipping', {})
                    addr_parts = [
                        shipping.get('address_1') or billing.get('address_1', ''),
                        shipping.get('city') or billing.get('city', ''),
                    ]
                    addr_str = ', '.join(filter(None, addr_parts))
                    customer_name = f"{billing.get('first_name','')} {billing.get('last_name','')}".strip()

                    # Extract line items for storage
                    wc_li_raw = o.get('line_items', []) or []
                    wc_li_data = []
                    for li in wc_li_raw:
                        wc_li_data.append({
                            'name': li.get('name', '') or '',
                            'quantity': int(li.get('quantity', 1) or 1),
                            'price': str(li.get('price', 0) or 0),
                            'sku': li.get('sku', '') or '',
                        })
                    original_data = {
                        'source': 'woocommerce',
                        'platform_id': str(o.get('id')),
                        'number': o.get('number'),
                        'status': o.get('status'),
                        'total': str(o.get('total')),
                        'currency': o.get('currency'),
                        'date_created': o.get('date_created'),
                        'line_items': wc_li_data,
                    }

                    _wc_cod = 0
                    try:
                        _wc_cod = int(float(str(o.get('total') or 0).replace(',', '').strip()))
                    except (ValueError, TypeError):
                        pass
                    _wc_phone = billing.get('phone', '')

                    # Apply row overrides from editable verify UI
                    import re as _re_woo
                    ovr = row_overrides.get(str(pid), row_overrides.get(pid, {}))
                    if ovr:
                        if 'customer_name' in ovr:
                            customer_name = ovr['customer_name']
                        if 'customer_phone' in ovr:
                            _wc_phone = ovr['customer_phone']
                        if 'customer_address' in ovr:
                            addr_str = ovr['customer_address']
                        if 'cod_amount' in ovr:
                            try:
                                _wc_cod = int(float(_re_woo.sub(r'[^\d.]', '', ovr['cod_amount']))) if ovr['cod_amount'] else 0
                            except (ValueError, TypeError):
                                pass

                    # Build package description from line items
                    wc_line_items = o.get('line_items', []) or []
                    pkg_parts = []
                    total_qty = 0
                    for li in wc_line_items:
                        li_name = li.get('name', '') or ''
                        li_qty = int(li.get('quantity', 1) or 1)
                        if li_name:
                            pkg_parts.append(f"{li_name} x{li_qty}")
                            total_qty += li_qty

                    _wc_pkg_desc = ovr.get('package_desc', ', '.join(pkg_parts))[:255] if ovr else ', '.join(pkg_parts)[:255]
                    _wc_order_code = ovr.get('client_order_code', '') if ovr else ''

                    order = orders_models.Order.objects.create(
                        business=business,
                        client_order_code=_wc_order_code or str(o.get('number', '')),
                        customer_name=customer_name or f"#{o.get('number')}",
                        customer_phone=_wc_phone,
                        customer_address=addr_str,
                        cod_amount=_wc_cod,
                        package_description=_wc_pkg_desc if _wc_pkg_desc else '',
                        package_qty=total_qty or 1,
                        order_status='to_review',
                        is_transferred=False,
                        original_order_data=original_data,
                    )

                    # Create OrderItems from WooCommerce line items
                    for li in wc_line_items:
                        li_name = li.get('name', '') or ''
                        li_qty = int(li.get('quantity', 1) or 1)
                        li_price = 0
                        try:
                            li_price = float(str(li.get('price', 0) or 0).replace(',', ''))
                        except (ValueError, TypeError):
                            pass
                        if li_name:
                            matched, mtype = match_product(business, li_name)
                            orders_models.OrderItem.objects.create(
                                order=order,
                                product=matched,
                                quantity=li_qty,
                                unit_price=matched.item_price if matched else li_price,
                                notes=li_name if not matched else matched.item_name,
                            )
                            if matched and mtype == 'fuzzy':
                                matched.add_client_name(li_name)

                    created_orders.append(order)
                    created += 1
                except Exception as e:
                    errors.append(f"{pid}: {e}")
        elif api.api_type == 'google_sheet':
            import re as _re
            import gspread
            from google.oauth2.credentials import Credentials as _GCreds
            from google.auth.transport.requests import Request as _GReq
            from django.conf import settings as django_settings
            from pathlib import Path as _Path
            import json as _json

            sheet_url = api.google_sheet_url or api.site_api_url or ''
            token_path = _Path(django_settings.BASE_DIR) / getattr(
                django_settings, 'GOOGLE_SHEETS_TOKEN_FILE', 'google_sheets_token.json'
            )
            if not token_path.exists():
                return JsonResponse({'success': False, 'error': 'Google Sheets not authorized.'}, status=400)

            _td = _json.loads(token_path.read_text())
            creds = _GCreds(
                token=_td.get('access_token'),
                refresh_token=_td.get('refresh_token'),
                token_uri=_td.get('token_uri', 'https://oauth2.googleapis.com/token'),
                client_id=_td.get('client_id'),
                client_secret=_td.get('client_secret'),
                scopes=_td.get('scope', '').split(),
            )
            if creds.expired and creds.refresh_token:
                creds.refresh(_GReq())
                _td['access_token'] = creds.token
                token_path.write_text(_json.dumps(_td, indent=2))

            gc = gspread.authorize(creds)
            match = _re.search(r'/spreadsheets/d/([^/]+)', sheet_url)
            if not match:
                return JsonResponse({'success': False, 'error': 'Invalid Google Sheet URL.'}, status=400)
            sheet_id = match.group(1)
            gid_match = _re.search(r'gid=(\d+)', sheet_url)
            gid = int(gid_match.group(1)) if gid_match else 0

            spreadsheet = gc.open_by_key(sheet_id)
            worksheet = None
            for ws in spreadsheet.worksheets():
                if ws.id == gid:
                    worksheet = ws
                    break
            if worksheet is None:
                worksheet = spreadsheet.sheet1

            all_values = worksheet.get_all_values()
            if len(all_values) <= 1:
                for ws in spreadsheet.worksheets():
                    if ws.id == (worksheet.id if worksheet else -1):
                        continue
                    candidate = ws.get_all_values()
                    if len(candidate) > 1:
                        worksheet = ws
                        all_values = candidate
                        break

            headers = all_values[0] if all_values else []
            data_rows = all_values[1:] if all_values else []

            # Use saved column mapping — authoritative; no auto-detection.
            saved_mapping = api.column_mapping or {}

            def col_idx_by_header(header_name):
                for j, h in enumerate(headers):
                    if h.strip() == header_name.strip():
                        return j
                return None

            def get_idx(field_name, *_ignored_auto_keys):
                # Mapping-config is authoritative — no auto-detection fallback.
                if field_name in saved_mapping:
                    return col_idx_by_header(saved_mapping[field_name])
                return None

            idx_name = get_idx('customer_name', 'name', 'customer name', 'customer', 'client name', 'client', 'first name')
            idx_phone = get_idx('customer_phone', 'phone', 'mobile', 'phone number', 'contact')
            idx_whatsapp = get_idx('customer_whatsapp', 'whatsapp', 'phone 2', 'alternate phone')
            idx_email = get_idx('customer_email', 'email', 'e-mail', 'customer email')
            idx_address = get_idx('customer_address', 'address', 'delivery address', 'location', 'area', 'city')
            idx_landmark = get_idx('dl_landmark', 'city', 'landmark', 'customer city', 'area')
            idx_building = get_idx('dl_building', 'building', 'villa', 'building no', 'villa no')
            idx_street = get_idx('dl_street', 'street', 'street no', 'street number')
            idx_zone = get_idx('dl_zone', 'zone', 'zone no', 'zone number')
            idx_location_link = get_idx('location_link', 'location link', 'google map', 'map link', 'gps')
            idx_lat = get_idx('dl_latitude', 'latitude', 'lat')
            idx_lng = get_idx('dl_longitude', 'longitude', 'lng', 'long')
            idx_cod = get_idx('cod_amount', 'cod', 'amount', 'cod amount', 'price', 'total')
            idx_dl_amount = get_idx('dl_amount', 'delivery fee', 'delivery amount', 'shipping')
            idx_order = get_idx('client_order_code', 'order', 'order number', 'order #', 'order id', 'ref', 'reference')
            idx_date = get_idx('order_date', 'date', 'order date', 'created')
            idx_deadline = get_idx('deadline_date', 'deadline', 'day', 'time', 'preferred', 'delivery date')
            idx_product = get_idx('package_desc', 'product', 'product name', 'item', 'items', 'description', 'package desc')
            idx_sku = get_idx('sku', 'sku', 'product sku', 'item sku', 'article')
            idx_product_url = get_idx('product_url', 'product url', 'url', 'product link')
            idx_qty = get_idx('package_qty', 'qty', 'quantity', 'count', 'pcs', 'package qty')
            idx_seller_notes = get_idx('seller_notes', 'notes', 'seller notes', 'note', 'remarks', 'comment')
            idx_internal_notes = get_idx('internal_notes', 'notes by ezzy', 'internal notes', 'staff notes')
            # Additional product columns
            idx_products = {}
            for i in range(1, 11):
                idx_products[f'product_{i}'] = get_idx(f'product_{i}', f'product {i}', f'product:{i}', f'item {i}')
                idx_products[f'count_{i}'] = get_idx(f'count_{i}', f'count {i}', f'count:{i}', f'qty {i}')

            def cell(row, idx):
                if idx is not None and idx < len(row):
                    v = row[idx]
                    return str(v).strip() if v is not None else ''
                return ''

            def safe_int(val):
                try:
                    return int(float(val)) if val else 0
                except (ValueError, TypeError):
                    return 0

            def safe_int_or_none(val):
                try:
                    if val is None or val == '' or (isinstance(val, str) and not val.strip()):
                        return None
                    return int(float(val))
                except (ValueError, TypeError):
                    return None

            def safe_decimal(val):
                try:
                    from decimal import Decimal
                    return Decimal(str(val)) if val else None
                except (ValueError, TypeError):
                    return None

            # Parse row indices from platform_ids (format: gs_{row_idx}_{order_num})
            for pid in platform_ids:
                try:
                    parts = pid.split('_', 2)  # gs, row_idx, order_num
                    if len(parts) < 2:
                        errors.append(f"{pid}: invalid format")
                        continue
                    row_idx = int(parts[1])
                    sheet_row = row_idx + 2  # +2 for header + 1-based

                    # Check if already imported
                    if orders_models.Order.objects.filter(
                        business=business,
                    ).filter(
                        Q(original_order_data__platform_id=pid) |
                        Q(original_order_data__row_number=sheet_row)
                    ).exists():
                        skipped += 1
                        continue

                    if row_idx >= len(data_rows):
                        errors.append(f"Row {sheet_row}: out of range")
                        continue

                    row = data_rows[row_idx]
                    customer = cell(row, idx_name) or f"Row {sheet_row}"
                    phone = cell(row, idx_phone)
                    whatsapp_raw = cell(row, idx_whatsapp)
                    address = cell(row, idx_address)
                    cod_val = cell(row, idx_cod)
                    order_num = cell(row, idx_order) or str(sheet_row)
                    product_desc = cell(row, idx_product)

                    # Format WhatsApp
                    if whatsapp_raw:
                        customer_whatsapp = format_whatsapp_number(whatsapp_raw)
                    elif phone:
                        customer_whatsapp = format_whatsapp_number(phone)
                    else:
                        customer_whatsapp = ''

                    # Parse COD amount
                    try:
                        cod_amount = float(_re.sub(r'[^\d.]', '', cod_val)) if cod_val else 0
                    except (ValueError, TypeError):
                        cod_amount = 0

                    # Parse delivery amount
                    dl_amount_val = cell(row, idx_dl_amount)
                    try:
                        dl_amount = float(_re.sub(r'[^\d.]', '', dl_amount_val)) if dl_amount_val else 0
                    except (ValueError, TypeError):
                        dl_amount = 0

                    # Build notes
                    notes_parts = []
                    seller_notes = cell(row, idx_seller_notes)
                    internal_notes = cell(row, idx_internal_notes)
                    if seller_notes:
                        notes_parts.append(f"Seller: {seller_notes}")
                    if internal_notes:
                        notes_parts.append(f"Staff: {internal_notes}")
                    combined_notes = ' | '.join(notes_parts)

                    # Apply row overrides from editable verify UI
                    ovr = row_overrides.get(pid, {})
                    if ovr:
                        if 'customer_name' in ovr: customer = ovr['customer_name']
                        if 'customer_phone' in ovr:
                            phone = ovr['customer_phone']
                            customer_whatsapp = format_whatsapp_number(phone)
                        if 'customer_whatsapp' in ovr:
                            whatsapp_raw = ovr['customer_whatsapp']
                            customer_whatsapp = format_whatsapp_number(whatsapp_raw)
                        if 'customer_address' in ovr: address = ovr['customer_address']
                        if 'cod_amount' in ovr:
                            try:
                                cod_amount = float(_re.sub(r'[^\d.]', '', ovr['cod_amount'])) if ovr['cod_amount'] else 0
                            except (ValueError, TypeError):
                                pass
                        if 'client_order_code' in ovr: order_num = ovr['client_order_code']
                        if 'package_desc' in ovr: product_desc = ovr['package_desc']
                        if 'dl_amount' in ovr:
                            try:
                                dl_amount = float(_re.sub(r'[^\d.]', '', ovr['dl_amount'])) if ovr['dl_amount'] else 0
                            except (ValueError, TypeError):
                                pass
                        if 'seller_notes' in ovr:
                            seller_notes = ovr['seller_notes']
                            notes_parts = [p for p in notes_parts if not p.startswith('Seller:')]
                            if seller_notes: notes_parts.insert(0, f"Seller: {seller_notes}")
                            combined_notes = ' | '.join(notes_parts)
                        if 'deadline_date' in ovr:
                            pass  # Will be applied at order creation below

                    original_data = {
                        'source': 'google_sheet',
                        'platform_id': pid,
                        'row_number': sheet_row,
                        'order_number': order_num,
                        'import_data': {h: cell(row, i) for i, h in enumerate(headers)},
                        'extra_fields': {
                            'customer_email': cell(row, idx_email),
                            'dl_landmark': cell(row, idx_landmark),
                            'location_link': cell(row, idx_location_link),
                            'dl_latitude': cell(row, idx_lat),
                            'dl_longitude': cell(row, idx_lng),
                            'package_desc': product_desc,
                            'sku': cell(row, idx_sku),
                            'product_url': cell(row, idx_product_url),
                            'package_qty': cell(row, idx_qty),
                            'seller_notes': seller_notes,
                            'internal_notes': internal_notes,
                        },
                    }

                    # Resolve override-able fields
                    _dl_zone = safe_int_or_none(ovr.get('dl_zone', cell(row, idx_zone)))
                    _dl_street = safe_int_or_none(ovr.get('dl_street', cell(row, idx_street)))
                    _dl_building = safe_int_or_none(ovr.get('dl_building', cell(row, idx_building)))
                    _deadline = ovr.get('deadline_date', cell(row, idx_deadline))

                    order = orders_models.Order.objects.create(
                        business=business,
                        client_order_code=order_num if order_num != str(sheet_row) else '',
                        customer_name=customer,
                        customer_phone=phone,
                        customer_whatsapp=customer_whatsapp,
                        customer_address=address,
                        dl_zone=_dl_zone,
                        dl_street=_dl_street,
                        dl_building=_dl_building,
                        cod_amount=cod_amount,
                        dl_amount=dl_amount,
                        package_description=product_desc[:255] if product_desc else '',
                        package_qty=safe_int(ovr.get('package_qty', cell(row, idx_qty))) or 1,
                        deadline_date=_deadline,
                        order_notes=combined_notes[:100] if combined_notes else '',
                        order_status='to_review',
                        verification_status='pending',
                        is_transferred=False,
                        original_order_data=original_data,
                    )

                    # Set package_description & package_qty
                    if product_desc:
                        # Use package_desc directly — no summary needed
                        sku_val = cell(row, idx_sku)
                        label = f"{product_desc} (SKU:{sku_val})" if sku_val else product_desc
                        order.package_description = label[:255]
                        order.package_qty = safe_int(cell(row, idx_qty)) or 1
                    else:
                        # Build from product_1..10 columns
                        desc_parts = []
                        total_qty = 0
                        for i in range(1, 11):
                            prod_name = cell(row, idx_products.get(f'product_{i}'))
                            prod_count = safe_int(cell(row, idx_products.get(f'count_{i}'))) or 1
                            if prod_name:
                                clean_pn, _ = _parse_coded_product_name(prod_name)
                                desc_parts.append(f"{clean_pn} x{prod_count}")
                                total_qty += prod_count
                        if desc_parts:
                            order.package_description = ', '.join(desc_parts)[:255]
                            order.package_qty = total_qty

                    order.save(update_fields=['package_description', 'package_qty'])

                    # Match product columns to Product records → create OrderItems
                    product_names = []
                    if product_desc:
                        product_names.append((product_desc, safe_int(cell(row, idx_qty)) or 1))
                    for i in range(1, 11):
                        pn = cell(row, idx_products.get(f'product_{i}'))
                        if pn:
                            pc = safe_int(cell(row, idx_products.get(f'count_{i}'))) or 1
                            product_names.append((pn, pc))
                    for pname, pqty in product_names:
                        matched, mtype = match_product(business, pname)
                        orders_models.OrderItem.objects.create(
                            order=order,
                            product=matched,
                            quantity=pqty,
                            unit_price=matched.item_price if matched else 0,
                            notes=pname if not matched else matched.item_name,
                        )
                        # Auto-save fuzzy-matched client name as alias for next import
                        if matched and mtype == 'fuzzy':
                            matched.add_client_name(pname)

                    # Create AddressVerification if lat/long provided
                    lat = safe_decimal(cell(row, idx_lat))
                    lng = safe_decimal(cell(row, idx_lng))
                    if lat and lng:
                        orders_models.AddressVerification.objects.create(
                            order=order,
                            original_address=address,
                            latitude=lat,
                            longitude=lng,
                            zone_number=safe_int(cell(row, idx_zone)) or None,
                            street_number=safe_int(cell(row, idx_street)) or None,
                            building_number=safe_int(cell(row, idx_building)) or None,
                            notes=f"Landmark: {cell(row, idx_landmark)} | Link: {cell(row, idx_location_link)}",
                            verification_result='pending'
                        )

                    created_orders.append(order)
                    created += 1
                except Exception as e:
                    errors.append(f"{pid}: {e}")

        else:
            import_log.mark_failed(f'Import not supported for {api.api_type}')
            return JsonResponse({'success': False, 'error': f'Import not supported for {api.api_type}'}, status=400)

    except Exception as e:
        logger.exception('import_api_orders error: %s', e)
        try:
            import_log.mark_failed(str(e))
        except Exception:
            pass
        return JsonResponse({'success': False, 'error': str(e)}, status=500)

    # Finalize ImportLog
    if created_orders:
        import_log.orders.add(*created_orders)
    import_log.orders_created = created
    import_log.orders_skipped = skipped
    import_log.orders_failed = len([e for e in errors if e])
    import_log.errors = errors[:50] if errors else []
    import_log.mark_completed()

    return JsonResponse({
        'success': True,
        'created': created,
        'skipped': skipped,
        'errors': errors,
    })


@login_required(login_url='/accounts/login/')
@staff_required
def mapping_manager(request):
    """
    Dedicated column mapping manager page for import wizard.
    URL: /workforce/import-wizard/mapping-manager/?business=<business_id>
    Shows a two-panel (both-side) interface: system fields ↔ sheet columns.
    """
    business_id = request.GET.get('business', '').strip()
    business = None
    api = None

    if business_id:
        try:
            business = business_models.Business.objects.get(business_id=business_id)
            api = business.business_settings_api.filter(
                api_type='google_sheet', is_verify_api=True
            ).first()
        except business_models.Business.DoesNotExist:
            pass

    # All businesses with Google Sheet config for the selector
    businesses_with_sheet = business_models.Business.objects.filter(
        business_status='active',
        business_settings_api__api_type='google_sheet',
        business_settings_api__is_verify_api=True,
    ).distinct().order_by('business_name')

    return render(request, 'workforce/mapping_manager.html', {
        'business': business,
        'api': api,
        'business_id': business_id,
        'businesses_with_sheet': businesses_with_sheet,
    })


def _gspread_client_or_error():
    """Return (gc, error_string). Shared bootstrap for Google Sheets endpoints."""
    import json as _json, gspread
    from google.oauth2.credentials import Credentials as _GCreds
    from google.auth.transport.requests import Request as _GReq
    from django.conf import settings as django_settings
    from pathlib import Path as _Path

    token_path = _Path(django_settings.BASE_DIR) / getattr(
        django_settings, 'GOOGLE_SHEETS_TOKEN_FILE', 'google_sheets_token.json'
    )
    if not token_path.exists():
        return None, 'Google Sheets not authorized.'
    _td = _json.loads(token_path.read_text())
    creds = _GCreds(
        token=_td.get('access_token'),
        refresh_token=_td.get('refresh_token'),
        token_uri=_td.get('token_uri', 'https://oauth2.googleapis.com/token'),
        client_id=_td.get('client_id'),
        client_secret=_td.get('client_secret'),
        scopes=_td.get('scope', '').split(),
    )
    if creds.expired and creds.refresh_token:
        creds.refresh(_GReq())
        _td['access_token'] = creds.token
        token_path.write_text(_json.dumps(_td, indent=2))
    return gspread.authorize(creds), None


def _resolve_gsheet_api(business_id, source_id):
    """Return BusinessApiSettings row for the selected (or default) Google Sheet source."""
    qs = business_models.BusinessApiSettings.objects.filter(
        business__business_id=business_id, api_type='google_sheet', is_verify_api=True
    )
    if source_id:
        try:
            return qs.get(pk=int(source_id))
        except (ValueError, business_models.BusinessApiSettings.DoesNotExist):
            return None
    return qs.order_by('-is_default', 'id').first()


def _select_gsheet_worksheet(spreadsheet, api):
    """
    Pick the worksheet to use, in priority order:
      1) saved api.google_sheet_gid
      2) gid in the URL (?gid=N or #gid=N)
      3) first sheet
    """
    import re as _re
    if api and api.google_sheet_gid is not None:
        for ws in spreadsheet.worksheets():
            if ws.id == int(api.google_sheet_gid):
                return ws
    sheet_url = (api.google_sheet_url or api.site_api_url or '') if api else ''
    gid_match = _re.search(r'gid=(\d+)', sheet_url)
    if gid_match:
        gid = int(gid_match.group(1))
        for ws in spreadsheet.worksheets():
            if ws.id == gid:
                return ws
    return spreadsheet.sheet1


@login_required(login_url='/accounts/login/')
@staff_required
def wf_sheet_worksheets(request):
    """GET: list all worksheets (tabs) inside the selected Google Sheet."""
    business_id = request.GET.get('business_id', '').strip()
    source_id = request.GET.get('source_id', '').strip()
    if not business_id:
        return JsonResponse({'success': False, 'error': 'Missing business_id'}, status=400)

    api = _resolve_gsheet_api(business_id, source_id)
    if not api:
        return JsonResponse({'success': False, 'error': 'No approved Google Sheet config'}, status=404)

    sheet_url = api.google_sheet_url or api.site_api_url or ''
    if not sheet_url:
        return JsonResponse({'success': False, 'error': 'Google Sheet URL not set on this source'}, status=400)

    gc, err = _gspread_client_or_error()
    if err:
        return JsonResponse({'success': False, 'error': err}, status=400)

    import re as _re
    match = _re.search(r'/spreadsheets/d/([^/]+)', sheet_url)
    if not match:
        return JsonResponse({'success': False, 'error': 'Invalid Sheet URL'}, status=400)
    try:
        spreadsheet = gc.open_by_key(match.group(1))
        worksheets = []
        for ws in spreadsheet.worksheets():
            worksheets.append({
                'gid': ws.id,
                'title': ws.title,
                'rows': getattr(ws, 'row_count', None),
                'cols': getattr(ws, 'col_count', None),
            })
        current_ws = _select_gsheet_worksheet(spreadsheet, api)
        return JsonResponse({
            'success': True,
            'worksheets': worksheets,
            'current_gid': current_ws.id if current_ws else None,
            'current_title': current_ws.title if current_ws else '',
            'spreadsheet_title': spreadsheet.title,
        })
    except Exception as e:
        logger.exception('wf_sheet_worksheets failed')
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@login_required(login_url='/accounts/login/')
@staff_required
@require_POST
def wf_sheet_save_tab(request):
    """POST: save the selected worksheet (gid + title) on the BusinessApiSettings row."""
    business_id = (request.POST.get('business_id') or '').strip()
    source_id = (request.POST.get('source_id') or '').strip()
    gid_raw = (request.POST.get('gid') or '').strip()
    title = (request.POST.get('title') or '').strip()[:255]

    if not business_id or not gid_raw:
        return JsonResponse({'success': False, 'error': 'Missing business_id or gid'}, status=400)
    try:
        gid = int(gid_raw)
    except ValueError:
        return JsonResponse({'success': False, 'error': 'Invalid gid'}, status=400)

    api = _resolve_gsheet_api(business_id, source_id)
    if not api:
        return JsonResponse({'success': False, 'error': 'No matching Google Sheet config'}, status=404)

    api.google_sheet_gid = gid
    api.google_sheet_tab_name = title
    api.save(update_fields=['google_sheet_gid', 'google_sheet_tab_name'])
    return JsonResponse({'success': True, 'gid': gid, 'title': title})


@login_required(login_url='/accounts/login/')
@staff_required
def wf_sheet_headers(request):
    """GET: Return the column headers from a business's Google Sheet config."""
    business_id = request.GET.get('business_id', '').strip()
    source_id = request.GET.get('source_id', '').strip()
    if not business_id:
        return JsonResponse({'success': False, 'error': 'Missing business_id'}, status=400)

    api = _resolve_gsheet_api(business_id, source_id)
    if not api:
        return JsonResponse({'success': False, 'error': 'No approved Google Sheet config'}, status=404)

    import re as _re

    sheet_url = api.google_sheet_url or api.site_api_url or ''
    if not sheet_url:
        return JsonResponse({'success': False, 'error': 'Google Sheet URL not set on this source'}, status=400)

    gc, err = _gspread_client_or_error()
    if err:
        return JsonResponse({'success': False, 'error': err}, status=400)

    try:
        match = _re.search(r'/spreadsheets/d/([^/]+)', sheet_url)
        if not match:
            return JsonResponse({'success': False, 'error': 'Invalid Sheet URL'}, status=400)

        spreadsheet = gc.open_by_key(match.group(1))
        worksheet = _select_gsheet_worksheet(spreadsheet, api)

        # Cache the chosen tab title back on the row for display
        if worksheet and api.google_sheet_tab_name != worksheet.title:
            api.google_sheet_tab_name = worksheet.title[:255]
            update_fields = ['google_sheet_tab_name']
            if api.google_sheet_gid is None:
                api.google_sheet_gid = worksheet.id
                update_fields.append('google_sheet_gid')
            api.save(update_fields=update_fields)

        all_values = worksheet.get_all_values()
        headers = all_values[0] if all_values else []
        sample = all_values[1] if len(all_values) > 1 else []

        # Persist headers so preview/transfer can resolve raw_row positions to db fields
        if headers and list(api.last_headers or []) != list(headers):
            api.last_headers = list(headers)
            api.save(update_fields=['last_headers'])

        return JsonResponse({
            'success': True,
            'headers': headers,
            'sample': sample,
            'saved_mapping': api.column_mapping or {},
            'current_gid': worksheet.id if worksheet else None,
            'current_title': worksheet.title if worksheet else '',
        })
    except Exception as e:
        logger.exception('wf_sheet_headers failed')
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@login_required(login_url='/accounts/login/')
@staff_required
def wf_source_headers(request):
    """GET: Return column headers for a business source (onedrive or google_sheet)."""
    business_id = request.GET.get('business_id', '').strip()
    platform = request.GET.get('platform', '').strip()
    if not business_id or not platform:
        return JsonResponse({'success': False, 'error': 'Missing business_id or platform'}, status=400)

    if platform == 'google_sheet':
        # Delegate to existing Google Sheet header fetch
        return wf_sheet_headers(request)

    if platform == 'onedrive':
        try:
            source_id = request.GET.get('source_id', '').strip()
            if source_id:
                source = orders_models.OneDriveSource.objects.filter(
                    id=source_id, business__business_id=business_id, is_active=True
                ).first()
            else:
                # Default: pick default source, then any with sheet name, then any
                source = orders_models.OneDriveSource.objects.filter(
                    business__business_id=business_id, is_active=True, is_default_mapping=True
                ).first()
                if not source:
                    source = orders_models.OneDriveSource.objects.filter(
                        business__business_id=business_id, is_active=True
                    ).exclude(last_sheet_name='').first()
                if not source:
                    source = orders_models.OneDriveSource.objects.filter(
                        business__business_id=business_id, is_active=True
                    ).first()
            if not source:
                return JsonResponse({'success': False, 'error': 'No active OneDrive source for this business'}, status=404)

            file_bytes, err = _onedrive_download_file(source)
            if err:
                return JsonResponse({'success': False, 'error': err}, status=500)

            wb = _safe_load_workbook(file_bytes)
            sheet_name = source.last_sheet_name
            if not sheet_name or sheet_name not in wb.sheetnames:
                sheet_name = wb.sheetnames[0]
            ws = wb[sheet_name]
            all_rows = list(ws.iter_rows(values_only=True, max_row=2))
            wb.close()

            headers = [str(c).strip() if c is not None else '' for c in all_rows[0]] if all_rows else []
            sample = [str(c).strip() if c is not None else '' for c in all_rows[1]] if len(all_rows) > 1 else []

            # Save sheet name and headers back
            update_fields = []
            if not source.last_sheet_name and sheet_name:
                source.last_sheet_name = sheet_name
                update_fields.append('last_sheet_name')
            if headers != (source.last_headers or []):
                source.last_headers = headers
                update_fields.append('last_headers')
            if update_fields:
                source.save(update_fields=update_fields)

            return JsonResponse({
                'success': True,
                'headers': headers,
                'sample': sample,
                'source_label': source.label,
                'sheet_name': sheet_name,
            })
        except Exception as e:
            logger.exception("OneDrive header fetch error")
            return JsonResponse({'success': False, 'error': str(e)}, status=500)

    if platform == 'public_link':
        try:
            source_id = request.GET.get('source_id', '').strip()
            if source_id:
                source = orders_models.PublicLinkSource.objects.filter(
                    id=source_id, business__business_id=business_id, is_active=True
                ).first()
            else:
                source = orders_models.PublicLinkSource.objects.filter(
                    business__business_id=business_id, is_active=True
                ).first()
            if not source:
                return JsonResponse({'success': False, 'error': 'No active Public Link source for this business'}, status=404)

            # Fetch headers from the public link URL
            import requests as http_requests
            from bs4 import BeautifulSoup
            resp = http_requests.get(source.url, timeout=30)
            resp.raise_for_status()
            resp.encoding = resp.apparent_encoding or 'utf-8'
            soup = BeautifulSoup(resp.text, 'html.parser')
            table = soup.find('table')
            if not table:
                return JsonResponse({'success': False, 'error': 'No table found at URL'}, status=400)
            header_row = table.find('tr')
            headers = [th.get_text(strip=True) for th in header_row.find_all(['th', 'td'])] if header_row else []
            # Sample data from second row
            rows = table.find_all('tr')
            sample = [td.get_text(strip=True) for td in rows[1].find_all(['td', 'th'])] if len(rows) > 1 else []

            # Save headers
            if headers != (source.last_headers or []):
                source.last_headers = headers
                source.save(update_fields=['last_headers'])

            return JsonResponse({
                'success': True,
                'headers': headers,
                'sample': sample,
                'source_label': source.label,
            })
        except Exception as e:
            logger.exception("Public Link header fetch error")
            return JsonResponse({'success': False, 'error': str(e)}, status=500)

    return JsonResponse({'success': False, 'error': f'Unsupported platform: {platform}'}, status=400)


@login_required(login_url='/accounts/login/')
@staff_required
def wf_upload_sample_headers(request):
    """POST: Upload a sample Excel/CSV file and return column headers."""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    uploaded = request.FILES.get('file')
    if not uploaded:
        return JsonResponse({'success': False, 'error': 'No file uploaded'}, status=400)

    try:
        fname = uploaded.name.lower()
        if fname.endswith(('.xlsx', '.xls')):
            from openpyxl import load_workbook
            wb = load_workbook(uploaded, read_only=True, data_only=True)
            ws = wb[wb.sheetnames[0]]
            hdr_row = next(ws.iter_rows(values_only=True, max_row=1), ())
            sample_row = None
            for row in ws.iter_rows(values_only=True, min_row=2, max_row=2):
                sample_row = row
            wb.close()
            headers = [str(c).strip() for c in hdr_row if c is not None and str(c).strip()]
            sample = [str(c).strip() if c is not None else '' for c in sample_row] if sample_row else []
        elif fname.endswith('.csv'):
            import csv as csv_mod, io
            text = uploaded.read().decode('utf-8-sig')
            reader = csv_mod.reader(io.StringIO(text))
            header_row = next(reader, [])
            sample_row = next(reader, [])
            headers = [h.strip() for h in header_row if h.strip()]
            sample = [s.strip() for s in sample_row]
        else:
            return JsonResponse({'success': False, 'error': 'Unsupported file type. Upload .xlsx, .xls, or .csv'}, status=400)

        return JsonResponse({
            'success': True,
            'headers': headers,
            'sample': sample,
            'filename': uploaded.name,
        })
    except Exception as e:
        logger.exception("Sample upload header parse error")
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@login_required(login_url='/accounts/login/')
@staff_required
def wf_save_column_mapping(request):
    """POST: Save column mapping for a business's Google Sheet config."""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    import json
    business_id = request.POST.get('business_id', '').strip()
    mapping_json = request.POST.get('mapping', '{}')

    if not business_id:
        return JsonResponse({'success': False, 'error': 'Missing business_id'}, status=400)

    try:
        api = business_models.BusinessApiSettings.objects.get(
            business__business_id=business_id, api_type='google_sheet', is_verify_api=True
        )
    except business_models.BusinessApiSettings.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'No approved Google Sheet config'}, status=404)

    try:
        mapping = json.loads(mapping_json)
    except (json.JSONDecodeError, TypeError):
        return JsonResponse({'success': False, 'error': 'Invalid JSON'}, status=400)

    api.column_mapping = mapping
    api.save(update_fields=['column_mapping'])
    # Sync to shared business import mapping (nested format, google_sheet key)
    if mapping:
        existing = api.business.import_mapping or {}
        existing['google_sheet'] = mapping
        api.business.import_mapping = existing
        api.business.save(update_fields=['import_mapping'])
    return JsonResponse({'success': True, 'mapping': mapping})


@login_required(login_url='/accounts/login/')
@staff_required
def import_wizard_prepare(request):
    """
    POST: Prepare data for the reusable import wizard page.
    Creates/updates an ImportLog with raw_data, columns, and source info,
    then returns the redirect URL to the wizard page.

    Params:
        source: 'csv_upload' | 'google_sheet' | 'shopify' | 'woocommerce' | 'onedrive'
        business_id: business ID
        import_log_id: (optional) existing ImportLog to use
        platform_ids[]: (for API imports) list of platform order IDs
        source_id: (for OneDrive) OneDrive source ID
        sheet_name: (for OneDrive) sheet name
        row_numbers[]: (for OneDrive) selected row numbers
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    source = request.POST.get('source', '').strip()
    business_id = request.POST.get('business_id', '').strip()
    import_log_id = request.POST.get('import_log_id', '').strip()

    if not business_id:
        return JsonResponse({'success': False, 'error': 'Missing business_id'}, status=400)

    try:
        business = business_models.Business.objects.get(business_id=business_id)
    except business_models.Business.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Business not found'}, status=404)

    # For CSV: reuse existing ImportLog from bulk_import_preview
    if import_log_id:
        try:
            import_log = orders_models.ImportLog.objects.get(id=import_log_id)
        except orders_models.ImportLog.DoesNotExist:
            return JsonResponse({'success': False, 'error': 'ImportLog not found'}, status=404)
        # Update business if it was created without one or with a different one
        if import_log.business_id != business.business_id:
            import_log.business = business
            import_log.save(update_fields=['business'])
    else:
        # Create new ImportLog for API/OneDrive flows
        import_log = orders_models.ImportLog.objects.create(
            business=business,
            source=source or 'csv_upload',
            status='started',
            initiated_by=request.user,
            source_meta={},
        )

    # Store additional context in source_meta
    meta = import_log.source_meta or {}
    meta['source_type'] = source

    if source in ('google_sheet', 'shopify', 'woocommerce'):
        platform_ids = request.POST.getlist('platform_ids[]')
        meta['platform_ids'] = platform_ids
        meta['needs_mapping'] = source in ('google_sheet', 'shopify', 'woocommerce')

        # Get API config for the business
        api = business.business_settings_api.filter(is_verify_api=True).first()
        if api:
            meta['api_settings_id'] = api.id
            meta['api_type'] = api.api_type
    elif source == 'onedrive':
        source_id = request.POST.get('source_id', '')
        sheet_name = request.POST.get('sheet_name', '')
        row_numbers = [int(n) for n in request.POST.getlist('row_numbers[]') if n.isdigit()]
        meta['source_id'] = source_id
        meta['sheet_name'] = sheet_name
        meta['row_numbers'] = row_numbers
        meta['needs_mapping'] = True

        # Download OneDrive file and extract selected rows as raw_data
        try:
            od_source = orders_models.OneDriveSource.objects.get(id=source_id)
            import_log.onedrive_source = od_source
            file_bytes, err = _onedrive_download_file(od_source)
            if not err and file_bytes:
                wb = _safe_load_workbook(file_bytes)
                if sheet_name in wb.sheetnames:
                    ws = wb[sheet_name]
                    all_rows = list(ws.iter_rows(values_only=True))
                    wb.close()
                    if all_rows:
                        headers = [str(h).strip() if h else '' for h in all_rows[0]]
                        meta['columns_order'] = headers
                        # Convert selected rows to list of dicts
                        raw_data = []
                        for row_num in row_numbers:
                            idx = row_num - 1  # row_num is 1-indexed, row 1 = header
                            if 0 < idx < len(all_rows):
                                cells = [str(c).strip() if c is not None else '' for c in all_rows[idx]]
                                row_dict = {headers[i]: cells[i] if i < len(cells) else '' for i in range(len(headers))}
                                row_dict['__row_num__'] = row_num
                                raw_data.append(row_dict)
                        import_log.raw_data = raw_data
                        import_log.total_rows = len(raw_data)
                else:
                    wb.close()
        except orders_models.OneDriveSource.DoesNotExist:
            pass
        except Exception as e:
            logger.warning(f'OneDrive data load in wizard prepare failed: {e}')
    elif source == 'temp_order':
        temp_ids = [int(x) for x in request.POST.getlist('temp_ids[]') if x.isdigit()]
        if not temp_ids:
            return JsonResponse({'success': False, 'error': 'No temp orders selected'}, status=400)

        temps = orders_models.TempOrder.objects.filter(
            id__in=temp_ids
        ).select_related('business', 'onedrive_source', 'api_settings', 'public_link_source')

        if not temps.exists():
            return JsonResponse({'success': False, 'error': 'No temp orders found'}, status=404)

        first_temp = temps.first()
        # Use temp order's business
        import_log.business = first_temp.business

        # Get headers from source — prefer shared business mapping, fall back to per-source
        headers = []
        saved_mapping = {}
        # Resolve the canonical mapping (business-level preferred)
        biz_mapping = first_temp.business.import_mapping if first_temp.business_id else {}
        src_mapping = (
            (first_temp.onedrive_source.last_column_mapping if first_temp.onedrive_source else None)
            or (first_temp.public_link_source.last_column_mapping if first_temp.public_link_source else None)
            or {}
        )
        canonical_mapping = biz_mapping or src_mapping  # {col_idx_str: db_field}

        if canonical_mapping:
            raw_len = max(len(first_temp.raw_row) if first_temp.raw_row else 0,
                         max((int(k) for k in canonical_mapping if str(k).isdigit()), default=0) + 1)
            headers = [f'Column {i}' for i in range(raw_len)]
            for col_idx, db_field in canonical_mapping.items():
                idx = int(col_idx) if str(col_idx).isdigit() else -1
                if db_field and 0 <= idx < len(headers):
                    saved_mapping[db_field] = headers[idx]
        elif first_temp.public_link_source:
            headers = first_temp.public_link_source.last_headers or []
            pl_mapping = first_temp.public_link_source.last_column_mapping or {}
            for col_idx, db_field in pl_mapping.items():
                idx = int(col_idx) if str(col_idx).isdigit() else -1
                if db_field and 0 <= idx < len(headers):
                    saved_mapping[db_field] = headers[idx]
        elif first_temp.api_settings:
            # Google Sheet: column_mapping is {db_field: header_name}
            saved_mapping = first_temp.api_settings.column_mapping or {}
            # Preserve insertion order — dict.values() is ordered in Python 3.7+
            seen_hdrs = {}
            for v in saved_mapping.values():
                if v:
                    seen_hdrs[v] = True
            headers = list(seen_hdrs.keys())

        # Convert raw_row to dicts using headers (list sources) or directly (dict sources like Shopify)
        raw_data = []
        for t in temps:
            if isinstance(t.raw_row, dict):
                # Shopify/API sources store raw_row as dict already
                row_dict = {k: str(v) if v is not None else '' for k, v in t.raw_row.items()}
                if not headers:
                    headers = [k for k in t.raw_row.keys()]
            elif isinstance(t.raw_row, list):
                row_dict = {}
                for j, h in enumerate(headers):
                    if h and j < len(t.raw_row):
                        row_dict[h] = str(t.raw_row[j]) if t.raw_row[j] is not None else ''
            else:
                row_dict = {}
            row_dict['__row_num__'] = t.row_num or t.id
            row_dict['__temp_id__'] = t.id
            raw_data.append(row_dict)

        import_log.raw_data = raw_data
        import_log.total_rows = len(raw_data)

        # Auto-map for Shopify/WooCommerce dict-based temp orders
        if not saved_mapping and raw_data and isinstance(first_temp.raw_row, dict):
            source_type = first_temp.raw_row.get('source', '')
            if source_type in ('shopify', 'woocommerce'):
                saved_mapping = {
                    'client_order_code': 'order_id',
                    'customer_name': 'name',
                    'customer_phone': 'phone',
                    'customer_address': 'address',
                    'cod_amount': 'cod',
                    'package_desc': 'package_desc',
                    'package_qty': 'package_qty',
                }
                # Map product/count fields — check ALL rows for max products
                all_keys = set()
                for row in raw_data:
                    if isinstance(row, dict):
                        all_keys.update(row.keys())
                for i in range(1, 6):
                    pk = f'product_{i}'
                    ck = f'count_{i}'
                    if pk in all_keys:
                        saved_mapping[pk] = pk
                    if ck in all_keys:
                        saved_mapping[ck] = ck

        if saved_mapping:
            import_log.column_mapping = saved_mapping

        # Ensure columns_order includes all product/count fields from all rows
        all_col_keys = set()
        for row in raw_data:
            if isinstance(row, dict):
                all_col_keys.update(k for k in row.keys() if not k.startswith('__'))
        col_list = [h for h in headers if h and not h.startswith('__')]
        for k in sorted(all_col_keys):
            if k not in col_list and not k.startswith('__'):
                col_list.append(k)
        meta['columns_order'] = col_list
        meta['temp_ids'] = temp_ids
        meta['needs_mapping'] = True

    else:
        # CSV - already has raw_data from bulk_import_preview
        meta['needs_mapping'] = True

    import_log.source_meta = meta
    import_log.save(update_fields=['source_meta', 'raw_data', 'total_rows', 'onedrive_source', 'business', 'column_mapping'])

    wizard_url = reverse('workforce:import_wizard', args=[import_log.id])
    return JsonResponse({'success': True, 'redirect': wizard_url, 'import_log_id': import_log.id})


@login_required(login_url='/accounts/login/')
@staff_required
def import_wizard(request, import_log_id):
    """
    GET: Render the full-page reusable import wizard.
    Works for all import sources: CSV, Google Sheet, Shopify, WooCommerce, OneDrive.
    Steps: 1) Column Mapping (if needed) → 2) Verify & Edit → 3) Confirm Import
    """
    import_log = get_object_or_404(orders_models.ImportLog, id=import_log_id)
    business = import_log.business
    meta = import_log.source_meta or {}
    source = meta.get('source_type', import_log.source)
    needs_mapping = meta.get('needs_mapping', source in ('csv_upload', 'google_sheet', 'onedrive', 'temp_order'))

    # API imports (Shopify/WooCommerce) always show the mapping step too
    if source in ('shopify', 'woocommerce'):
        needs_mapping = True

    # Load columns and saved mapping based on source
    columns = []
    saved_mapping = import_log.column_mapping or {}
    raw_rows = import_log.raw_data or []

    # ── Helper: extract per-platform mapping from nested or flat Business.import_mapping ──
    def _biz_platform_mapping(src):
        raw = business.import_mapping or {}
        is_nested = any(k in raw for k in ('shopify', 'woocommerce', 'csv', 'google_sheet', 'onedrive'))
        if is_nested:
            return raw.get(src, {})
        return raw  # legacy flat — use as-is for any source

    # ── Shopify / WooCommerce: virtual columns + mapping manager only ──
    if source in ('shopify', 'woocommerce'):
        if source == 'shopify':
            columns = SHOPIFY_VIRTUAL_COLS
            # Only load from mapping manager — no fallback to ImportLog or defaults
            saved_mapping = _biz_platform_mapping('shopify') or {}
        else:
            columns = WOO_VIRTUAL_COLS
            saved_mapping = _biz_platform_mapping('woocommerce') or {}

        # Fetch first selected order as sample row for the mapping table
        if not raw_rows:
            _platform_ids = meta.get('platform_ids', [])
            _api = business.business_settings_api.filter(is_verify_api=True).first()
            if _platform_ids and _api:
                _first_pid = _platform_ids[0]
                try:
                    if source == 'shopify':
                        import shopify as _shopify
                        _shop = (_api.site_api_url or '').replace('https://', '').replace('http://', '').replace('.myshopify.com', '').strip()
                        _session = _shopify.Session(_shop, _api.api_version or '2023-10', _api.api_access_token)
                        _shopify.ShopifyResource.activate_session(_session)
                        _o = _shopify.Order.find(_first_pid)
                        raw_rows = [_shopify_extract_row(_o, _first_pid)]
                        _shopify.ShopifyResource.clear_session()
                    else:
                        from woocommerce import API as _WooAPI
                        _wc = _WooAPI(url=_api.site_api_url or '', consumer_key=_api.api_key or '', consumer_secret=_api.api_secret or '', version='wc/v3', timeout=10)
                        _r = _wc.get(f'orders/{_first_pid}')
                        if _r.status_code == 200:
                            raw_rows = [_woo_extract_row(_r.json())]
                except Exception as _e:
                    logger.warning(f'Sample row fetch failed for {source} wizard: {_e}')

    elif source in ('csv_upload', 'onedrive', 'temp_order'):
        # Columns from stored order (preserves file order), fallback to dict keys
        columns = meta.get('columns_order', [])
        if not columns and raw_rows:
            columns = list(raw_rows[0].keys()) if isinstance(raw_rows[0], dict) else []
        # Filter out internal fields
        columns = [c for c in columns if not c.startswith('__')]
        # Priority: 1) mapping manager  2) previous ImportLog  3) OneDriveSource
        biz_key = 'onedrive' if source == 'onedrive' else 'csv'
        saved_mapping = (
            _biz_platform_mapping(biz_key)
            or saved_mapping
            or None
        )
        if not saved_mapping:
            prev_source = 'csv_upload' if source == 'csv_upload' else 'onedrive'
            prev_log = orders_models.ImportLog.objects.filter(
                business=business, source=prev_source
            ).exclude(column_mapping={}).exclude(id=import_log_id).order_by('-id').first()
            if prev_log and prev_log.column_mapping:
                saved_mapping = prev_log.column_mapping
        if source == 'onedrive' and not saved_mapping:
            od_source = import_log.onedrive_source
            if od_source and od_source.last_column_mapping:
                saved_mapping = od_source.last_column_mapping
        saved_mapping = saved_mapping or {}

    elif source == 'google_sheet':
        api = business.business_settings_api.filter(is_verify_api=True).first()
        # Prefer mapping manager saved mapping, fallback to API settings
        saved_mapping = _biz_platform_mapping('google_sheet')
        if not saved_mapping and api and api.column_mapping:
            saved_mapping = api.column_mapping
        # Load Google Sheet headers as columns
        if api:
            try:
                import re as _re
                import gspread
                from google.oauth2.credentials import Credentials as _GCreds
                from google.auth.transport.requests import Request as _GReq
                from django.conf import settings as django_settings
                from pathlib import Path as _Path

                sheet_url = api.google_sheet_url or api.site_api_url or ''
                token_path = _Path(django_settings.BASE_DIR) / getattr(
                    django_settings, 'GOOGLE_SHEETS_TOKEN_FILE', 'google_sheets_token.json'
                )
                if token_path.exists():
                    _td = json.loads(token_path.read_text())
                    creds = _GCreds(
                        token=_td.get('access_token'),
                        refresh_token=_td.get('refresh_token'),
                        token_uri=_td.get('token_uri', 'https://oauth2.googleapis.com/token'),
                        client_id=_td.get('client_id'),
                        client_secret=_td.get('client_secret'),
                        scopes=_td.get('scope', '').split(),
                    )
                    if creds.expired and creds.refresh_token:
                        creds.refresh(_GReq())
                        _td['access_token'] = creds.token
                        token_path.write_text(json.dumps(_td, indent=2))

                    gc = gspread.authorize(creds)
                    match = _re.search(r'/spreadsheets/d/([^/]+)', sheet_url)
                    if match:
                        spreadsheet = gc.open_by_key(match.group(1))
                        gid_match = _re.search(r'gid=(\d+)', sheet_url)
                        gid = int(gid_match.group(1)) if gid_match else 0
                        worksheet = None
                        for ws in spreadsheet.worksheets():
                            if ws.id == gid:
                                worksheet = ws
                                break
                        if worksheet is None:
                            worksheet = spreadsheet.sheet1
                        all_values = worksheet.get_all_values()
                        if all_values:
                            headers_row = [h.strip() for h in all_values[0]]
                            columns = [h for h in headers_row if h]
                            # Build sample row from first data row
                            if len(all_values) > 1 and not raw_rows:
                                sample_vals = all_values[1]
                                raw_rows = [{
                                    headers_row[i]: str(sample_vals[i]).strip() if i < len(sample_vals) else ''
                                    for i in range(len(headers_row)) if headers_row[i]
                                }]
            except Exception as e:
                logger.warning(f'Failed to load Google Sheet headers for wizard: {e}')

    pickup_locations = business_models.PickupLocation.objects.filter(
        business=business, pickup_status='active'
    ).order_by('-is_fulfilment_center', 'pickup_location_title')
    default_pickup_location = pickup_locations.filter(is_fulfilment_center=True).first() or pickup_locations.first()

    context = {
        'import_log': import_log,
        'import_log_id': import_log.id,
        'business': business,
        'business_id': business.business_id,
        'source': source,
        'needs_mapping': needs_mapping,
        'columns_json': json.dumps(columns),
        'saved_mapping_json': json.dumps(saved_mapping),
        'sample_row_json': json.dumps(raw_rows[0] if raw_rows else {}),
        'raw_rows_count': len(raw_rows),
        'platform_ids_json': json.dumps(meta.get('platform_ids', [])),
        'source_label': dict(orders_models.ImportLog.SOURCE_CHOICES).get(source, source),
        'pickup_locations': pickup_locations,
        'default_pickup_location_id': default_pickup_location.id if default_pickup_location else '',
    }
    return render(request, 'workforce/import_wizard.html', context)


# ── Shared extraction helpers (used by import_wizard + import_wizard_preview) ─

import re as _re_mapping

def _resolve_mapping_value(template, raw_row):
    """
    Resolve a mapping value against a source row dict.
    Supports:
      - plain key:     'Column A'           → raw_row['Column A']
      - template:      '{Col A} {Col B}'    → 'value_a value_b'
      - with sep:      '{Col A}, {Col B}'   → 'value_a, value_b'
    Extra whitespace between empty substitutions is collapsed.
    """
    if not template or not isinstance(raw_row, dict):
        return ''
    if '{' not in template:
        return str(raw_row.get(template, '') or '')
    def _sub(m):
        return str(raw_row.get(m.group(1), '') or '')
    result = _re_mapping.sub(r'\{([^}]+)\}', _sub, template)
    # Collapse multiple spaces / leading-trailing junk from empty substitutions
    result = _re_mapping.sub(r'[ \t]{2,}', ' ', result).strip(' ,;/\\-')
    return result


def _shopify_extract_row(o, pid):
    """Extract ALL Shopify order JSON fields as virtual columns."""
    def _ga(obj, *attrs, default=''):
        for a in attrs:
            obj = getattr(obj, a, None)
            if obj is None:
                return default
        return str(obj) if obj is not None else default

    def _sv(val, default=''):
        return default if val is None else str(val)

    ship = getattr(o, 'shipping_address', None)
    bill = getattr(o, 'billing_address', None)
    cust = getattr(o, 'customer', None)
    items = getattr(o, 'line_items', []) or []
    note_attrs = getattr(o, 'note_attributes', []) or []
    disc_codes = getattr(o, 'discount_codes', []) or []
    disc = disc_codes[0] if disc_codes else None
    pgw = getattr(o, 'payment_gateway_names', None) or []

    cname = f"{_ga(cust,'first_name')} {_ga(cust,'last_name')}".strip()

    ship_total = ''
    try:
        ship_total = str(o.total_shipping_price_set.shop_money.amount or '')
    except Exception:
        pass

    row = {
        'order.id':                   str(getattr(o, 'id', pid)),
        'order.name':                 _ga(o, 'name') or str(pid),
        'order.number':               str(getattr(o, 'order_number', '') or ''),
        'order.created_at':           str(getattr(o, 'created_at', '') or '')[:10],
        'order.updated_at':           str(getattr(o, 'updated_at', '') or '')[:10],
        'order.processed_at':         str(getattr(o, 'processed_at', '') or '')[:10],
        'order.cancelled_at':         str(getattr(o, 'cancelled_at', '') or '')[:10],
        'order.currency':             _ga(o, 'currency'),
        'order.source_name':          _ga(o, 'source_name'),
        'order.tags':                 _ga(o, 'tags'),
        'order.contact_email':        _ga(o, 'contact_email'),
        'order.phone':                _ga(o, 'phone'),
        'order.token':                _ga(o, 'token'),
        'order.cancel_reason':        _ga(o, 'cancel_reason'),
        'order.confirmation_number':  _ga(o, 'confirmation_number'),
        'order.po_number':            _ga(o, 'po_number'),
        'order.total_weight':         str(getattr(o, 'total_weight', '') or ''),
        'order.total_outstanding':    str(getattr(o, 'total_outstanding', '') or ''),
        'customer.id':                str(getattr(cust, 'id', '') or '') if cust else '',
        'customer.name':              cname,
        'customer.email':             _ga(cust, 'email'),
        'customer.phone':             _ga(cust, 'phone'),
        'customer.first_name':        _ga(cust, 'first_name'),
        'customer.last_name':         _ga(cust, 'last_name'),
        'customer.orders_count':      str(getattr(cust, 'orders_count', '') or '') if cust else '',
        'customer.total_spent':       str(getattr(cust, 'total_spent', '') or '') if cust else '',
        'customer.tags':              _ga(cust, 'tags'),
        'customer.verified_email':    str(getattr(cust, 'verified_email', '') or '') if cust else '',
        'customer.note':              _ga(cust, 'note'),
        'shipping.name':              _ga(ship, 'name'),
        'shipping.first_name':        _ga(ship, 'first_name'),
        'shipping.last_name':         _ga(ship, 'last_name'),
        'shipping.address1':          _ga(ship, 'address1'),
        'shipping.address':           _ga(ship, 'address1'),   # alias used by mapping manager
        'shipping.address2':          _ga(ship, 'address2'),
        'shipping.city':              _ga(ship, 'city'),
        'shipping.province':          _ga(ship, 'province'),
        'shipping.province_code':     _ga(ship, 'province_code'),
        'shipping.zip':               _ga(ship, 'zip'),
        'shipping.country':           _ga(ship, 'country'),
        'shipping.country_code':      _ga(ship, 'country_code'),
        'shipping.company':           _ga(ship, 'company'),
        'shipping.phone':             _ga(ship, 'phone'),
        'billing.name':               _ga(bill, 'name'),
        'billing.first_name':         _ga(bill, 'first_name'),
        'billing.last_name':          _ga(bill, 'last_name'),
        'billing.address1':           _ga(bill, 'address1'),
        'billing.address':            _ga(bill, 'address1'),   # alias
        'billing.address2':           _ga(bill, 'address2'),
        'billing.city':               _ga(bill, 'city'),
        'billing.province':           _ga(bill, 'province'),
        'billing.zip':                _ga(bill, 'zip'),
        'billing.country':            _ga(bill, 'country'),
        'billing.company':            _ga(bill, 'company'),
        'billing.phone':              _ga(bill, 'phone'),
        'financial_status':           _ga(o, 'financial_status'),
        'fulfillment_status':         _ga(o, 'fulfillment_status'),
        'total_price':                _sv(getattr(o, 'total_price', None)),
        'subtotal_price':             _sv(getattr(o, 'subtotal_price', None)),
        'total_tax':                  _sv(getattr(o, 'total_tax', None)),
        'total_discounts':            _sv(getattr(o, 'total_discounts', None)),
        'total_shipping_price':       ship_total,
        'payment_gateway':            _ga(o, 'payment_gateway'),
        'payment_gateway_names':      ', '.join(str(p) for p in pgw),
        'note':                       _ga(o, 'note'),
        'discount.code':              _ga(disc, 'code'),
        'discount.amount':            _sv(getattr(disc, 'amount', None)) if disc else '',
        'discount.type':              _ga(disc, 'type'),
        'cod.amount':                 _sv(getattr(o, 'total_price', None)),
        'cod.status':                 _ga(o, 'financial_status'),
        'cod.currency':               _ga(o, 'currency'),
    }

    ship_lines = getattr(o, 'shipping_lines', []) or []
    for n in range(1, 3):
        sl = ship_lines[n - 1] if len(ship_lines) >= n else None
        row[f'shipping_line_{n}.title']            = _ga(sl, 'title') if sl else ''
        row[f'shipping_line_{n}.price']            = _sv(getattr(sl, 'price', None)) if sl else ''
        row[f'shipping_line_{n}.code']             = _ga(sl, 'code') if sl else ''
        row[f'shipping_line_{n}.discounted_price'] = _sv(getattr(sl, 'discounted_price', None)) if sl else ''
        row[f'shipping_line_{n}.source']           = _ga(sl, 'source') if sl else ''

    for n in range(1, 4):
        na = note_attrs[n - 1] if len(note_attrs) >= n else None
        row[f'note_attribute.{n}.name']  = getattr(na, 'name', '') or '' if na else ''
        row[f'note_attribute.{n}.value'] = getattr(na, 'value', '') or '' if na else ''

    for n in range(1, 11):
        item = items[n - 1] if len(items) >= n else None
        row[f'line_item_{n}.title']              = _ga(item, 'title') if item else ''
        row[f'line_item_{n}.name']               = _ga(item, 'name') if item else ''
        row[f'line_item_{n}.variant_title']      = _ga(item, 'variant_title') if item else ''
        row[f'line_item_{n}.product_id']         = _sv(getattr(item, 'product_id', None)) if item else ''
        row[f'line_item_{n}.variant_id']         = _sv(getattr(item, 'variant_id', None)) if item else ''
        row[f'line_item_{n}.quantity']           = _sv(getattr(item, 'quantity', None)) if item else ''
        row[f'line_item_{n}.sku']                = _ga(item, 'sku') if item else ''
        row[f'line_item_{n}.price']              = _sv(getattr(item, 'price', None)) if item else ''
        row[f'line_item_{n}.total_discount']     = _sv(getattr(item, 'total_discount', None)) if item else ''
        row[f'line_item_{n}.grams']              = _sv(getattr(item, 'grams', None)) if item else ''
        row[f'line_item_{n}.vendor']             = _ga(item, 'vendor') if item else ''
        row[f'line_item_{n}.requires_shipping']  = _sv(getattr(item, 'requires_shipping', None)) if item else ''
        row[f'line_item_{n}.taxable']            = _sv(getattr(item, 'taxable', None)) if item else ''
        row[f'line_item_{n}.fulfillment_status'] = _ga(item, 'fulfillment_status') if item else ''

    row['line_items.titles']          = ', '.join(_ga(i, 'title') for i in items)
    row['line_items.skus']            = ', '.join(_ga(i, 'sku') for i in items if _ga(i, 'sku'))
    row['line_items.vendors']         = ', '.join(_ga(i, 'vendor') for i in items if _ga(i, 'vendor'))
    row['line_items.total_qty']       = str(sum(int(getattr(i, 'quantity', 0) or 0) for i in items)) if items else ''
    row['line_items.titles_with_qty'] = ', '.join(
        f"{_ga(i,'title')} x{getattr(i,'quantity',0)}" for i in items
    )
    return row


def _woo_extract_row(o):
    """Extract all virtual column values from a WooCommerce order dict."""
    billing  = o.get('billing', {})
    shipping = o.get('shipping', {})
    cname    = f"{billing.get('first_name','') or ''} {billing.get('last_name','') or ''}".strip()
    items    = o.get('line_items', []) or []

    row = {
        'order.number':                   str(o.get('number', o.get('id', ''))),
        'order.date_created':             str(o.get('date_created', '') or '')[:10],
        'billing.first_name + last_name': cname,
        'billing.email':                  billing.get('email', '') or '',
        'billing.phone':                  billing.get('phone', '') or '',
        'shipping.address_1':             shipping.get('address_1', '') or '',
        'shipping.address_2':             shipping.get('address_2', '') or '',
        'shipping.city':                  (shipping.get('city', '') or billing.get('city', '') or ''),
        'shipping.state':                 (shipping.get('state', '') or billing.get('state', '') or ''),
        'shipping.postcode':              (shipping.get('postcode', '') or billing.get('postcode', '') or ''),
        'shipping.country':               (shipping.get('country', '') or billing.get('country', '') or ''),
        'total':                          str(o.get('total', '')),
        'subtotal':                       str(o.get('subtotal', '')),
        'shipping_total':                 str(o.get('shipping_total', '')),
        'total_tax':                      str(o.get('total_tax', '')),
        'discount_total':                 str(o.get('discount_total', '')),
        'status':                         o.get('status', '') or '',
        'payment_method_title':           o.get('payment_method_title', '') or '',
        'customer_note':                  o.get('customer_note', '') or '',
        'line_items.names':               ', '.join(i.get('name', '') or '' for i in items),
        'line_items.total_qty':           str(sum(int(i.get('quantity', 0) or 0) for i in items)),
    }
    for n in range(1, 6):
        item = items[n - 1] if len(items) >= n else None
        row[f'line_item_{n}.name']     = item.get('name', '') or '' if item else ''
        row[f'line_item_{n}.quantity'] = str(item.get('quantity', '') or '') if item else ''
        row[f'line_item_{n}.sku']      = item.get('sku', '') or '' if item else ''
        row[f'line_item_{n}.price']    = str(item.get('price', '') or '') if item else ''
    return row


class _NullObj:
    """Null object: returns None for any attribute access — used to derive column keys."""
    def __getattr__(self, _): return None


def _shopify_col_keys():
    """Return the canonical Shopify virtual column list derived from _shopify_extract_row."""
    keys = list(_shopify_extract_row(_NullObj(), '').keys())
    # Preserve a sensible display order: order.* first, then customer, shipping, billing, etc.
    prefix_order = ['order.', 'customer.', 'shipping.', 'billing.', 'total', 'subtotal',
                    'financial', 'fulfillment', 'payment', 'discount', 'note',
                    'shipping_line', 'note_attribute', 'line_item', 'line_items', 'cod.']
    def _sort_key(k):
        for i, p in enumerate(prefix_order):
            if k.startswith(p):
                return (i, k)
        return (len(prefix_order), k)
    return sorted(keys, key=_sort_key)


def _woo_col_keys():
    """Return the canonical WooCommerce virtual column list derived from _woo_extract_row."""
    keys = list(_woo_extract_row({}).keys())
    prefix_order = ['order.', 'billing.', 'shipping.', 'total', 'subtotal', 'shipping_total',
                    'total_tax', 'discount', 'status', 'payment', 'customer_note', 'line_item', 'line_items']
    def _sort_key(k):
        for i, p in enumerate(prefix_order):
            if k.startswith(p):
                return (i, k)
        return (len(prefix_order), k)
    return sorted(keys, key=_sort_key)


@login_required(login_url='/accounts/login/')
@staff_required
def import_wizard_preview(request):
    """
    POST: Return transformed preview rows for the wizard verify step.
    Applies column mapping to raw data and returns preview table data.
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    import_log_id = request.POST.get('import_log_id', '')
    mapping_json = request.POST.get('mapping', '{}')

    try:
        import_log = orders_models.ImportLog.objects.get(id=import_log_id)
    except orders_models.ImportLog.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'ImportLog not found'}, status=404)

    try:
        mapping = json.loads(mapping_json)
    except (json.JSONDecodeError, TypeError):
        mapping = {}

    business = import_log.business
    meta = import_log.source_meta or {}
    source = meta.get('source_type', import_log.source)

    if source == 'google_sheet':
        # Delegate to existing preview_api_import logic (Google Sheet)
        platform_ids = meta.get('platform_ids', [])
        if not platform_ids:
            return JsonResponse({'success': False, 'error': 'No platform_ids found'})
        from django.http import QueryDict
        from django.test import RequestFactory
        factory = RequestFactory()
        post_data = QueryDict(mutable=True)
        post_data['business_id'] = str(business.business_id)
        for pid in platform_ids:
            post_data.appendlist('platform_ids[]', pid)
        fake_request = factory.post('/')
        fake_request.POST = post_data
        fake_request.user = request.user
        return preview_api_import(fake_request)

    elif source in ('shopify', 'woocommerce'):
        # Fetch raw order data from API, then apply user's mapping {db_field: virtual_col}
        platform_ids = meta.get('platform_ids', [])
        if not platform_ids:
            return JsonResponse({'success': False, 'error': 'No platform_ids found'})

        api = business.business_settings_api.filter(is_verify_api=True).first()
        if not api:
            return JsonResponse({'success': False, 'error': 'No approved API config'})

        _extract_shopify_row = _shopify_extract_row

        def _noop_shopify_row(o, pid):
            """Placeholder — actual logic now in module-level _shopify_extract_row."""
            def _ga(obj, *attrs, default=''):
                for a in attrs:
                    obj = getattr(obj, a, None)
                    if obj is None:
                        return default
                return str(obj) if obj is not None else default

            def _sv(val, default=''):
                return default if val is None else str(val)

            ship = getattr(o, 'shipping_address', None)
            bill = getattr(o, 'billing_address', None)
            cust = getattr(o, 'customer', None)
            items = getattr(o, 'line_items', []) or []
            note_attrs = getattr(o, 'note_attributes', []) or []
            disc_codes = getattr(o, 'discount_codes', []) or []
            disc = disc_codes[0] if disc_codes else None
            pgw = getattr(o, 'payment_gateway_names', None) or []

            cname = f"{_ga(cust,'first_name')} {_ga(cust,'last_name')}".strip()

            # shipping total via nested set
            ship_total = ''
            try:
                ship_total = str(o.total_shipping_price_set.shop_money.amount or '')
            except Exception:
                pass

            row = {
                # ── Order ──────────────────────────────────────────────────
                'order.id':                   str(getattr(o, 'id', pid)),
                'order.name':                 _ga(o, 'name') or str(pid),
                'order.number':               str(getattr(o, 'order_number', '') or ''),
                'order.created_at':           str(getattr(o, 'created_at', '') or '')[:10],
                'order.updated_at':           str(getattr(o, 'updated_at', '') or '')[:10],
                'order.processed_at':         str(getattr(o, 'processed_at', '') or '')[:10],
                'order.cancelled_at':         str(getattr(o, 'cancelled_at', '') or '')[:10],
                'order.currency':             _ga(o, 'currency'),
                'order.source_name':          _ga(o, 'source_name'),
                'order.tags':                 _ga(o, 'tags'),
                'order.contact_email':        _ga(o, 'contact_email'),
                'order.phone':                _ga(o, 'phone'),
                'order.token':                _ga(o, 'token'),
                'order.cancel_reason':        _ga(o, 'cancel_reason'),
                'order.confirmation_number':  _ga(o, 'confirmation_number'),
                'order.po_number':            _ga(o, 'po_number'),
                'order.total_weight':         str(getattr(o, 'total_weight', '') or ''),
                'order.total_outstanding':    str(getattr(o, 'total_outstanding', '') or ''),
                # ── Customer ───────────────────────────────────────────────
                'customer.id':              str(getattr(cust, 'id', '') or '') if cust else '',
                'customer.name':            cname,
                'customer.first_name':      _ga(cust, 'first_name') if cust else '',
                'customer.last_name':       _ga(cust, 'last_name') if cust else '',
                'customer.email':           _ga(cust, 'email') if cust else '',
                'customer.phone':           _ga(cust, 'phone') if cust else '',
                'customer.tags':            _ga(cust, 'tags') if cust else '',
                'customer.orders_count':    str(getattr(cust, 'orders_count', '') or '') if cust else '',
                'customer.total_spent':     str(getattr(cust, 'total_spent', '') or '') if cust else '',
                'customer.verified_email':  str(getattr(cust, 'verified_email', '') or '') if cust else '',
                'customer.note':            _ga(cust, 'note') if cust else '',
                # ── Shipping ───────────────────────────────────────────────
                'shipping.name':          _ga(ship, 'name') if ship else '',
                'shipping.first_name':    _ga(ship, 'first_name') if ship else '',
                'shipping.last_name':     _ga(ship, 'last_name') if ship else '',
                'shipping.company':       _ga(ship, 'company') if ship else '',
                'shipping.phone':         (_ga(ship, 'phone') or _ga(cust, 'phone') if cust else '') if ship else '',
                'shipping.address':       _ga(ship, 'address1') if ship else '',
                'shipping.address2':      _ga(ship, 'address2') if ship else '',
                'shipping.city':          _ga(ship, 'city') if ship else '',
                'shipping.province':      _ga(ship, 'province') if ship else '',
                'shipping.province_code': _ga(ship, 'province_code') if ship else '',
                'shipping.zip':           _ga(ship, 'zip') if ship else '',
                'shipping.country':       _ga(ship, 'country') if ship else '',
                'shipping.country_code':  _ga(ship, 'country_code') if ship else '',
                # ── Billing ────────────────────────────────────────────────
                'billing.name':          _ga(bill, 'name') if bill else '',
                'billing.first_name':    _ga(bill, 'first_name') if bill else '',
                'billing.last_name':     _ga(bill, 'last_name') if bill else '',
                'billing.company':       _ga(bill, 'company') if bill else '',
                'billing.phone':         _ga(bill, 'phone') if bill else '',
                'billing.address':       _ga(bill, 'address1') if bill else '',
                'billing.address2':      _ga(bill, 'address2') if bill else '',
                'billing.city':          _ga(bill, 'city') if bill else '',
                'billing.province':      _ga(bill, 'province') if bill else '',
                'billing.province_code': _ga(bill, 'province_code') if bill else '',
                'billing.zip':           _ga(bill, 'zip') if bill else '',
                'billing.country':       _ga(bill, 'country') if bill else '',
                'billing.country_code':  _ga(bill, 'country_code') if bill else '',
                # ── Financials ─────────────────────────────────────────────
                'total_price':             _sv(getattr(o, 'total_price', None)),
                'subtotal_price':          _sv(getattr(o, 'subtotal_price', None)),
                'total_line_items_price':  _sv(getattr(o, 'total_line_items_price', None)),
                'total_shipping':          ship_total,
                'total_tax':               _sv(getattr(o, 'total_tax', None)),
                'total_discounts':         _sv(getattr(o, 'total_discounts', None)),
                'total_outstanding':       _sv(getattr(o, 'total_outstanding', None)),
                'total_tip_received':      _sv(getattr(o, 'total_tip_received', None)),
                'current_total_price':     _sv(getattr(o, 'current_total_price', None)),
                'current_subtotal_price':  _sv(getattr(o, 'current_subtotal_price', None)),
                'financial_status':        _ga(o, 'financial_status'),
                'fulfillment_status':      _ga(o, 'fulfillment_status') or 'unfulfilled',
                # ── Discount ───────────────────────────────────────────────
                'discount_code':   getattr(disc, 'code', '') if disc else '',
                'discount_amount': _sv(getattr(disc, 'amount', None)) if disc else '',
                'discount_type':   getattr(disc, 'type', '') if disc else '',
                # ── Payment ────────────────────────────────────────────────
                'payment_gateway': pgw[0] if pgw else '',
                'payment_terms':   str(getattr(o, 'payment_terms', '') or ''),
                # ── Notes ──────────────────────────────────────────────────
                'note': _ga(o, 'note'),
            }

            # Additional order fields
            row.update({
                'order.landing_site':            _ga(o, 'landing_site'),
                'order.referring_site':          _ga(o, 'referring_site'),
                'order.customer_locale':         _ga(o, 'customer_locale'),
                'order.buyer_accepts_marketing': str(getattr(o, 'buyer_accepts_marketing', '') or ''),
                'order.test':                    str(getattr(o, 'test', '') or ''),
                'order.closed_at':               str(getattr(o, 'closed_at', '') or '')[:10],
                'order.taxes_included':          str(getattr(o, 'taxes_included', '') or ''),
                'order.estimated_taxes':         str(getattr(o, 'estimated_taxes', '') or ''),
                # COD specific (derived)
                'cod.amount':    _sv(getattr(o, 'total_price', None)),
                'cod.status':    _ga(o, 'financial_status'),
                'cod.currency':  _ga(o, 'currency'),
            })

            # Shipping lines (up to 2)
            ship_lines = getattr(o, 'shipping_lines', []) or []
            for n in range(1, 3):
                sl = ship_lines[n - 1] if len(ship_lines) >= n else None
                row[f'shipping_line_{n}.title']            = _ga(sl, 'title') if sl else ''
                row[f'shipping_line_{n}.price']            = _sv(getattr(sl, 'price', None)) if sl else ''
                row[f'shipping_line_{n}.code']             = _ga(sl, 'code') if sl else ''
                row[f'shipping_line_{n}.discounted_price'] = _sv(getattr(sl, 'discounted_price', None)) if sl else ''
                row[f'shipping_line_{n}.source']           = _ga(sl, 'source') if sl else ''

            # Note attributes (up to 3)
            for n in range(1, 4):
                na = note_attrs[n - 1] if len(note_attrs) >= n else None
                row[f'note_attribute.{n}.name']  = getattr(na, 'name', '') or '' if na else ''
                row[f'note_attribute.{n}.value'] = getattr(na, 'value', '') or '' if na else ''

            # Line items (up to 10)
            for n in range(1, 11):
                item = items[n - 1] if len(items) >= n else None
                row[f'line_item_{n}.title']              = _ga(item, 'title') if item else ''
                row[f'line_item_{n}.name']               = _ga(item, 'name') if item else ''
                row[f'line_item_{n}.variant_title']      = _ga(item, 'variant_title') if item else ''
                row[f'line_item_{n}.product_id']         = _sv(getattr(item, 'product_id', None)) if item else ''
                row[f'line_item_{n}.variant_id']         = _sv(getattr(item, 'variant_id', None)) if item else ''
                row[f'line_item_{n}.quantity']           = _sv(getattr(item, 'quantity', None)) if item else ''
                row[f'line_item_{n}.sku']                = _ga(item, 'sku') if item else ''
                row[f'line_item_{n}.price']              = _sv(getattr(item, 'price', None)) if item else ''
                row[f'line_item_{n}.total_discount']     = _sv(getattr(item, 'total_discount', None)) if item else ''
                row[f'line_item_{n}.grams']              = _sv(getattr(item, 'grams', None)) if item else ''
                row[f'line_item_{n}.vendor']             = _ga(item, 'vendor') if item else ''
                row[f'line_item_{n}.requires_shipping']  = _sv(getattr(item, 'requires_shipping', None)) if item else ''
                row[f'line_item_{n}.taxable']            = _sv(getattr(item, 'taxable', None)) if item else ''
                row[f'line_item_{n}.fulfillment_status'] = _ga(item, 'fulfillment_status') if item else ''

            # Aggregated
            row['line_items.titles']          = ', '.join(_ga(i, 'title') for i in items)
            row['line_items.skus']            = ', '.join(_ga(i, 'sku') for i in items if _ga(i, 'sku'))
            row['line_items.vendors']         = ', '.join(_ga(i, 'vendor') for i in items if _ga(i, 'vendor'))
            row['line_items.total_qty']       = str(sum(int(getattr(i, 'quantity', 0) or 0) for i in items)) if items else ''
            row['line_items.titles_with_qty'] = ', '.join(
                f"{_ga(i,'title')} x{getattr(i,'quantity',0)}" for i in items
            )
            return row

        def _extract_woo_row(o):
            """Extract all virtual column values from a WooCommerce order dict."""
            billing  = o.get('billing', {})
            shipping = o.get('shipping', {})
            cname    = f"{billing.get('first_name','') or ''} {billing.get('last_name','') or ''}".strip()
            items    = o.get('line_items', []) or []

            row = {
                'order.number':                   str(o.get('number', o.get('id', ''))),
                'order.date_created':             str(o.get('date_created', '') or '')[:10],
                'billing.first_name + last_name': cname,
                'billing.email':                  billing.get('email', '') or '',
                'billing.phone':                  billing.get('phone', '') or '',
                'shipping.address_1':             shipping.get('address_1', '') or '',
                'shipping.address_2':             shipping.get('address_2', '') or '',
                'shipping.city':                  (shipping.get('city', '') or billing.get('city', '') or ''),
                'shipping.state':                 (shipping.get('state', '') or billing.get('state', '') or ''),
                'shipping.postcode':              (shipping.get('postcode', '') or billing.get('postcode', '') or ''),
                'shipping.country':               (shipping.get('country', '') or billing.get('country', '') or ''),
                'total':                          str(o.get('total', '')),
                'subtotal':                       str(o.get('subtotal', '')),
                'shipping_total':                 str(o.get('shipping_total', '')),
                'total_tax':                      str(o.get('total_tax', '')),
                'discount_total':                 str(o.get('discount_total', '')),
                'status':                         o.get('status', '') or '',
                'payment_method_title':           o.get('payment_method_title', '') or '',
                'customer_note':                  o.get('customer_note', '') or '',
                'line_items.names':               ', '.join(i.get('name', '') or '' for i in items),
                'line_items.total_qty':           str(sum(int(i.get('quantity', 0) or 0) for i in items)),
            }
            for n in range(1, 6):
                item = items[n - 1] if len(items) >= n else None
                row[f'line_item_{n}.name']     = item.get('name', '') or '' if item else ''
                row[f'line_item_{n}.quantity'] = str(item.get('quantity', '') or '') if item else ''
                row[f'line_item_{n}.sku']      = item.get('sku', '') or '' if item else ''
                row[f'line_item_{n}.price']    = str(item.get('price', '') or '') if item else ''
            return row

        # Save updated mapping to ImportLog
        if mapping:
            import_log.column_mapping = mapping
            import_log.save(update_fields=['column_mapping'])

        preview_rows = []
        already_imported = []
        errors = []

        if source == 'shopify':
            try:
                import shopify as _shopify
                shop_name = (api.site_api_url or '').replace('https://', '').replace('http://', '').replace('.myshopify.com', '').strip()
                session = _shopify.Session(shop_name, api.api_version or '2023-10', api.api_access_token)
                _shopify.ShopifyResource.activate_session(session)
                for i, pid in enumerate(platform_ids):
                    try:
                        already = orders_models.Order.objects.filter(
                            business=business,
                            original_order_data__platform_id=str(pid),
                            original_order_data__source='shopify',
                        ).exists()
                        if already:
                            already_imported.append(str(pid))
                        o = _shopify.Order.find(pid)
                        raw = _extract_shopify_row(o, pid)
                        row_data = {'row_number': str(pid)}
                        for db_field, virtual_col in mapping.items():
                            row_data[db_field] = _resolve_mapping_value(virtual_col, raw)
                        # Build product_matches from line items
                        li_items = getattr(o, 'line_items', []) or []
                        product_matches = []
                        for li in li_items:
                            li_title = getattr(li, 'title', '') or getattr(li, 'name', '') or ''
                            li_qty = int(getattr(li, 'quantity', 1) or 1)
                            if li_title:
                                matched, mtype = match_product(business, li_title)
                                product_matches.append({
                                    'raw': li_title,
                                    'qty': li_qty,
                                    'matched_name': matched.item_name if matched else None,
                                    'match_type': mtype,
                                })
                        row_data['product_matches'] = product_matches
                        preview_rows.append(row_data)
                    except Exception as e:
                        errors.append(f"{pid}: {e}")
                _shopify.ShopifyResource.clear_session()
            except Exception as e:
                return JsonResponse({'success': False, 'error': f'Shopify connection failed: {e}'})

        else:  # woocommerce
            try:
                from woocommerce import API as _WooAPI
                wcapi = _WooAPI(
                    url=api.site_api_url or '',
                    consumer_key=api.api_key or '',
                    consumer_secret=api.api_secret or '',
                    version='wc/v3',
                    timeout=15,
                )
                for pid in platform_ids:
                    try:
                        already = orders_models.Order.objects.filter(
                            business=business,
                            original_order_data__platform_id=str(pid),
                            original_order_data__source='woocommerce',
                        ).exists()
                        if already:
                            already_imported.append(str(pid))
                        r = wcapi.get(f'orders/{pid}')
                        if r.status_code != 200:
                            errors.append(f"{pid}: HTTP {r.status_code}")
                            continue
                        wc_order = r.json()
                        raw = _extract_woo_row(wc_order)
                        row_data = {'row_number': str(pid)}
                        for db_field, virtual_col in mapping.items():
                            row_data[db_field] = _resolve_mapping_value(virtual_col, raw)
                        # Build product_matches from line items
                        wc_li_items = wc_order.get('line_items', []) or []
                        product_matches = []
                        for li in wc_li_items:
                            li_name = li.get('name', '') or ''
                            li_qty = int(li.get('quantity', 1) or 1)
                            if li_name:
                                matched, mtype = match_product(business, li_name)
                                product_matches.append({
                                    'raw': li_name,
                                    'qty': li_qty,
                                    'matched_name': matched.item_name if matched else None,
                                    'match_type': mtype,
                                })
                        row_data['product_matches'] = product_matches
                        preview_rows.append(row_data)
                    except Exception as e:
                        errors.append(f"{pid}: {e}")
            except Exception as e:
                return JsonResponse({'success': False, 'error': f'WooCommerce connection failed: {e}'})

        fields = [{'name': 'row_number', 'label': '#', 'sheet_col': ''}]
        for db_field, virtual_col in mapping.items():
            fields.append({
                'name': db_field,
                'label': IMPORT_FIELD_LABELS.get(db_field, db_field.replace('_', ' ').title()),
                'sheet_col': virtual_col,
            })

        return JsonResponse({
            'success': True,
            'preview': preview_rows,
            'fields': fields,
            'total_rows': len(platform_ids),
            'already_imported': already_imported,
            'errors': errors,
        })

    elif source in ('csv_upload', 'onedrive', 'temp_order'):
        # Transform raw_data using mapping
        raw_rows = import_log.raw_data or []
        if not raw_rows:
            return JsonResponse({'success': False, 'error': 'No data in ImportLog'})

        # mapping is {db_field: source_column}
        # Build preview rows
        preview = []
        for i, raw_row in enumerate(raw_rows[:100]):  # Limit preview
            row_data = {'row_number': raw_row.get('__row_num__', i + 1)}
            for db_field, src_col in mapping.items():
                row_data[db_field] = _resolve_mapping_value(src_col, raw_row) if src_col else ''
            preview.append(row_data)

        fields = [{'name': 'row_number', 'label': '#', 'sheet_col': ''}]
        for db_field, src_col in mapping.items():
            fields.append({
                'name': db_field,
                'label': IMPORT_FIELD_LABELS.get(db_field, db_field.replace('_', ' ').title()),
                'sheet_col': src_col,
            })

        return JsonResponse({
            'success': True,
            'preview': preview,
            'fields': fields,
            'total_rows': len(raw_rows),
            'already_imported': [],
        })

    return JsonResponse({'success': False, 'error': f'Unsupported source: {source}'})


@login_required(login_url='/accounts/login/')
@staff_required
def import_wizard_confirm(request):
    """
    POST: Execute the import from the wizard.
    Delegates to the appropriate importer based on source type.
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    import_log_id = request.POST.get('import_log_id', '')
    row_overrides_json = request.POST.get('row_overrides', '{}')
    mapping_json = request.POST.get('mapping', '{}')
    pickup_location_id = request.POST.get('pickup_location_id', '')

    try:
        import_log = orders_models.ImportLog.objects.get(id=import_log_id)
    except orders_models.ImportLog.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'ImportLog not found'}, status=404)

    try:
        row_overrides = json.loads(row_overrides_json)
    except (json.JSONDecodeError, TypeError):
        row_overrides = {}

    try:
        mapping = json.loads(mapping_json)
    except (json.JSONDecodeError, TypeError):
        mapping = {}

    # Save mapping to ImportLog
    if mapping:
        import_log.column_mapping = mapping
        import_log.save(update_fields=['column_mapping'])

    business = import_log.business
    meta = import_log.source_meta or {}
    source = meta.get('source_type', import_log.source)

    if source in ('google_sheet', 'shopify', 'woocommerce'):
        # Delegate to existing import_api_orders
        platform_ids = meta.get('platform_ids', [])
        from django.http import QueryDict
        from django.test import RequestFactory
        factory = RequestFactory()
        fake_request = factory.post('/')
        post_data = QueryDict(mutable=True)
        post_data['business_id'] = str(business.business_id)
        post_data['source'] = source
        post_data['row_overrides'] = json.dumps(row_overrides)
        for pid in platform_ids:
            post_data.appendlist('platform_ids[]', pid)
        fake_request.POST = post_data
        fake_request.user = request.user
        response = import_api_orders(fake_request)
        # After API import, apply selected pickup location to newly created orders
        if pickup_location_id:
            try:
                pl = business_models.PickupLocation.objects.get(id=pickup_location_id, business=business)
                import_log.refresh_from_db()
                import_log.orders.filter(pickup_location__isnull=True).update(pickup_location=pl)
                import_log.orders.update(pickup_location=pl)
            except business_models.PickupLocation.DoesNotExist:
                pass
        return response

    elif source in ('csv_upload', 'onedrive', 'temp_order'):
        # Process rows using mapping + overrides
        from orders.views import bulk_import_save
        from django.test import RequestFactory

        raw_rows = import_log.raw_data or []
        if not raw_rows:
            return JsonResponse({'success': False, 'error': 'No data to import'})

        created = 0
        skipped = 0
        errors_list = []

        import_log.status = 'processing'
        import_log.total_rows = len(raw_rows)
        import_log.save(update_fields=['status', 'total_rows'])

        factory = RequestFactory()

        for i, raw_row in enumerate(raw_rows):
            try:
                # Apply mapping: transform raw_row to mapped_row
                mapped_row = {}
                for db_field, src_col in mapping.items():
                    mapped_row[db_field] = _resolve_mapping_value(src_col, raw_row) if src_col else ''

                # Apply row overrides (key matches row_number from preview)
                row_key = str(raw_row.get('__row_num__', i + 1))
                if row_key in row_overrides:
                    for field, val in row_overrides[row_key].items():
                        mapped_row[field] = val

                # Call existing bulk_import_save endpoint
                fake_request = factory.post('/',
                    data=json.dumps({
                        'business_id': str(business.business_id),
                        'row': mapped_row,
                        'row_index': i,
                        'import_log_id': import_log.id,
                        'pickup_location_id': pickup_location_id or None,
                    }),
                    content_type='application/json'
                )
                fake_request.user = request.user
                resp = bulk_import_save(fake_request)
                resp_data = json.loads(resp.content)
                if resp_data.get('success'):
                    created += 1
                else:
                    errors_list.append(f"Row {i+1}: {resp_data.get('error', 'Unknown error')}")
            except Exception as e:
                errors_list.append(f"Row {i+1}: {str(e)}")

        import_log.status = 'completed' if not errors_list else 'completed_with_errors'
        import_log.orders_created = created
        import_log.orders_failed = len(errors_list)
        import_log.errors = [{'row': e.split(':')[0], 'error': e} for e in errors_list]
        import_log.save()

        # Mark temp orders as imported
        if source == 'temp_order' and created > 0:
            temp_ids = meta.get('temp_ids', [])
            if temp_ids:
                orders_models.TempOrder.objects.filter(id__in=temp_ids).update(status='imported')

        return JsonResponse({
            'success': True,
            'created': created,
            'skipped': skipped,
            'errors': errors_list,
        })

    return JsonResponse({'success': False, 'error': f'Unsupported source: {source}'})


@login_required(login_url='/accounts/login/')
@staff_required
def import_wizard_save_mapping(request):
    """POST: Save column mapping from the wizard page."""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    import_log_id = request.POST.get('import_log_id', '')
    mapping_json = request.POST.get('mapping', '{}')

    try:
        import_log = orders_models.ImportLog.objects.get(id=import_log_id)
    except orders_models.ImportLog.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'ImportLog not found'}, status=404)

    try:
        mapping = json.loads(mapping_json)
    except (json.JSONDecodeError, TypeError):
        return JsonResponse({'success': False, 'error': 'Invalid JSON'}, status=400)

    import_log.column_mapping = mapping
    import_log.save(update_fields=['column_mapping'])

    # Also save to API settings if Google Sheet
    source = (import_log.source_meta or {}).get('source_type', import_log.source)
    if source == 'google_sheet':
        api = import_log.business.business_settings_api.filter(
            is_verify_api=True, api_type='google_sheet'
        ).first()
        if api:
            api.column_mapping = mapping
            api.save(update_fields=['column_mapping'])

    # Sync to Business.import_mapping — preserve nested structure per platform
    if mapping:
        biz = import_log.business
        raw = biz.import_mapping or {}
        is_nested = any(k in raw for k in ('shopify', 'woocommerce', 'csv', 'google_sheet', 'onedrive'))
        if is_nested:
            # Update only the relevant platform key, keep other platforms intact
            platform_key = {
                'shopify': 'shopify', 'woocommerce': 'woocommerce',
                'google_sheet': 'google_sheet', 'onedrive': 'onedrive',
            }.get(source, 'csv')
            raw[platform_key] = mapping
            biz.import_mapping = raw
        else:
            # No nested structure yet — init it
            platform_key = {
                'shopify': 'shopify', 'woocommerce': 'woocommerce',
                'google_sheet': 'google_sheet', 'onedrive': 'onedrive',
            }.get(source, 'csv')
            biz.import_mapping = {platform_key: mapping}
        biz.save(update_fields=['import_mapping'])

    return JsonResponse({'success': True})


@login_required(login_url='/accounts/login/')
@staff_required
def wf_mapping_manager(request):
    """
    Dedicated column mapping manager — per-platform tabs.
    Mappings stored as nested dict in Business.import_mapping:
      {"shopify": {db_field: src_col}, "woocommerce": {...}, "csv": {...}, "google_sheet": {...}}
    Flat (legacy) format is shown on the csv tab as-is.
    """
    businesses = business_models.Business.objects.filter(
        business_status='active'
    ).order_by('business_name')

    selected_business_id = request.GET.get('business', '')
    # Auto-resolve business from logged-in user if not specified
    if not selected_business_id:
        user_biz = get_cached_business(request)
        if user_biz:
            selected_business_id = str(user_biz.business_id)
    selected_business = None
    platform_mappings = {}
    active_api_types = []
    od_sources_list = []
    gs_sources_list = []
    pl_sources_list = []

    PLATFORMS = [
        {'key': 'shopify',      'label': 'Shopify',         'icon': 'fab fa-shopify',   'src_type': 'select', 'cols': _shopify_col_keys(),  'default': SHOPIFY_DEFAULT_MAPPING},
        {'key': 'woocommerce',  'label': 'WooCommerce',     'icon': 'fab fa-wordpress', 'src_type': 'select', 'cols': _woo_col_keys(),      'default': WOO_DEFAULT_MAPPING},
        {'key': 'public_link',  'label': 'Public Link',     'icon': 'fas fa-link',      'src_type': 'select', 'cols': [],                   'default': {}},
        {'key': 'csv',          'label': 'CSV / Excel',     'icon': 'fas fa-file-csv',  'src_type': 'text',   'cols': [],                   'default': {}},
        {'key': 'google_sheet', 'label': 'Google Sheet',    'icon': 'fas fa-table',     'src_type': 'select', 'cols': [],                   'default': {}},
        {'key': 'onedrive',     'label': 'OneDrive',        'icon': 'fab fa-microsoft', 'src_type': 'select', 'cols': [],                   'default': {}},
    ]

    if selected_business_id:
        try:
            selected_business = businesses.prefetch_related('business_settings_api').get(
                business_id=selected_business_id
            )
        except business_models.Business.DoesNotExist:
            selected_business = None

        if selected_business:
            raw = selected_business.import_mapping or {}
            active_api_types = list(
                selected_business.business_settings_api.filter(is_verify_api=True)
                .values_list('api_type', flat=True).distinct()
            )

            # Build source lists for platforms with multiple sources
            od_sources_list = []
            od_default_source = None
            for s in orders_models.OneDriveSource.objects.filter(
                business=selected_business, is_active=True
            ).order_by('-is_default_mapping', 'label'):
                od_sources_list.append({
                    'id': s.id, 'label': s.label,
                    'is_default': s.is_default_mapping,
                    'sheet': s.last_sheet_name or '',
                })
                if s.is_default_mapping or od_default_source is None:
                    od_default_source = s

            gs_sources_list = []
            gs_default_source = None
            for a in selected_business.business_settings_api.filter(
                api_type='google_sheet', is_verify_api=True
            ).order_by('-is_default', 'id'):
                label = a.google_sheet_url or a.site_api_url or f'Sheet #{a.id}'
                # Truncate URL for display
                if len(label) > 50:
                    label = label[:47] + '...'
                gs_sources_list.append({
                    'id': a.id, 'label': label,
                    'is_default': a.is_default,
                })
                if a.is_default or gs_default_source is None:
                    gs_default_source = a

            # Build public link source list
            pl_sources_list = []
            pl_default_source = None
            for p in orders_models.PublicLinkSource.objects.filter(
                business=selected_business, is_active=True
            ).order_by('label'):
                pl_sources_list.append({
                    'id': p.id, 'label': p.label,
                    'is_default': False,
                    'sheet': '',
                })
                if pl_default_source is None:
                    pl_default_source = p

            # Include onedrive in active types if sources exist
            if od_sources_list and 'onedrive' not in active_api_types:
                active_api_types.append('onedrive')
            # Include public_link in active types if public link sources exist
            if pl_sources_list and 'public_link' not in active_api_types:
                active_api_types.append('public_link')

            # OneDrive headers are fetched on demand via "Fetch Headers" button
            # to avoid slow page loads from downloading Excel files

            # Load per-source mapping for the default source (overrides business-level)
            # Detect nested vs flat (legacy) format
            is_nested = any(k in raw for k in ('shopify', 'woocommerce', 'csv', 'google_sheet', 'onedrive', 'public_link'))
            if is_nested:
                platform_mappings = raw
            else:
                # Legacy flat — put on csv tab as starting point
                platform_mappings = {'csv': raw}

            # Pre-load saved headers into platform cols (no auto-fetch needed)
            if od_default_source and getattr(od_default_source, 'last_headers', None):
                for p in PLATFORMS:
                    if p['key'] == 'onedrive':
                        p['cols'] = od_default_source.last_headers
                        p['src_type'] = 'select'
                        break

            # Override with per-source mapping if the source has one saved
            if od_default_source and od_default_source.last_column_mapping:
                src_map = od_default_source.last_column_mapping
                # Convert index-based to header-name if needed
                if src_map and not all(str(k).isdigit() for k in src_map):
                    platform_mappings['onedrive'] = src_map
            if gs_default_source and gs_default_source.column_mapping:
                platform_mappings['google_sheet'] = gs_default_source.column_mapping
            # Load public link headers and mapping
            if pl_default_source:
                if pl_default_source.last_headers:
                    for p in PLATFORMS:
                        if p['key'] == 'public_link':
                            p['cols'] = pl_default_source.last_headers
                            p['src_type'] = 'select'
                            break
                # Convert old-format mapping to new-format for public_link tab
                if not platform_mappings.get('public_link') and pl_default_source.last_column_mapping:
                    pl_map = pl_default_source.last_column_mapping
                    pl_headers = pl_default_source.last_headers or []
                    if pl_map and all(str(k).isdigit() for k in pl_map):
                        pl_mapping = {}
                        for col_idx_str, db_field in pl_map.items():
                            if db_field:
                                idx = int(col_idx_str)
                                if idx < len(pl_headers) and pl_headers[idx]:
                                    pl_mapping[db_field] = pl_headers[idx]
                        if pl_mapping:
                            platform_mappings['public_link'] = pl_mapping

    # Build DB field list (required first)
    REQUIRED = {'customer_name', 'customer_phone', 'customer_address', 'cod_amount'}
    all_fields = [
        {'name': k, 'label': v, 'required': k in REQUIRED}
        for k, v in IMPORT_FIELD_LABELS.items()
    ]

    # Source lists for JS
    source_lists = {
        'onedrive': od_sources_list if selected_business else [],
        'google_sheet': gs_sources_list if selected_business else [],
        'public_link': pl_sources_list if selected_business else [],
    }

    # Default platform from saved preference
    default_platform = ''
    if selected_business and platform_mappings:
        default_platform = platform_mappings.get('_default', '')

    context = {
        'businesses': businesses,
        'selected_business': selected_business,
        'selected_business_id': selected_business_id,
        'platforms_json': json.dumps(PLATFORMS),
        'platform_mappings_json': json.dumps(platform_mappings),
        'all_fields_json': json.dumps(all_fields),
        'active_api_types_json': json.dumps(active_api_types),
        'source_lists_json': json.dumps(source_lists),
        'default_platform': default_platform,
    }
    return render(request, 'workforce/mapping_manager.html', context)


@login_required(login_url='/accounts/login/')
@staff_required
def wf_mapping_manager_save(request):
    """POST (AJAX): Save ALL platform mappings at once.
    Receives: {business_id, all_mappings: {platform: {db_field: src_col}},
               source_ids: {onedrive: id, google_sheet: id}}
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    business_id    = request.POST.get('business_id', '').strip()
    all_maps_json  = request.POST.get('all_mappings', '{}')
    source_ids_json = request.POST.get('source_ids', '{}')
    active_platform = request.POST.get('active_platform', '').strip()

    try:
        business = business_models.Business.objects.get(business_id=business_id)
    except business_models.Business.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Business not found'}, status=404)

    try:
        all_maps = json.loads(all_maps_json)
        source_ids = json.loads(source_ids_json)
    except (json.JSONDecodeError, TypeError):
        return JsonResponse({'success': False, 'error': 'Invalid JSON'}, status=400)

    # Clean each platform's mapping — remove empty entries
    nested = {}
    total = 0
    for platform, mapping in all_maps.items():
        if isinstance(mapping, dict):
            cleaned = {k: v for k, v in mapping.items() if k and v}
            nested[platform] = cleaned
            total += len(cleaned)

    # Save active platform as default tab preference
    if active_platform:
        nested['_default'] = active_platform
    business.import_mapping = nested
    business.save(update_fields=['import_mapping'])

    # Clear all source defaults if a different platform is now default
    if active_platform and active_platform != 'onedrive':
        orders_models.OneDriveSource.objects.filter(
            business=business, is_default_mapping=True
        ).update(is_default_mapping=False)
    if active_platform and active_platform != 'google_sheet':
        business.business_settings_api.filter(
            api_type='google_sheet', is_default=True
        ).update(is_default=False)

    # Save per-source mapping for OneDrive
    od_source_id = source_ids.get('onedrive')
    if od_source_id and 'onedrive' in nested:
        od_src = orders_models.OneDriveSource.objects.filter(
            id=od_source_id, business=business
        ).first()
        if od_src:
            od_src.last_column_mapping = nested['onedrive']
            if active_platform == 'onedrive':
                orders_models.OneDriveSource.objects.filter(
                    business=business, is_default_mapping=True
                ).exclude(id=od_src.id).update(is_default_mapping=False)
                od_src.is_default_mapping = True
                od_src.save(update_fields=['last_column_mapping', 'is_default_mapping'])
            else:
                od_src.save(update_fields=['last_column_mapping'])

    # Save per-source mapping for Google Sheet
    gs_source_id = source_ids.get('google_sheet')
    if gs_source_id and 'google_sheet' in nested:
        gs_api = business.business_settings_api.filter(id=gs_source_id).first()
        if gs_api:
            gs_api.column_mapping = nested['google_sheet']
            if active_platform == 'google_sheet':
                gs_api.is_default = True
                gs_api.save(update_fields=['column_mapping', 'is_default'])
                business.business_settings_api.filter(
                    api_type='google_sheet', is_default=True
                ).exclude(id=gs_api.id).update(is_default=False)
            else:
                gs_api.save(update_fields=['column_mapping'])
    elif 'google_sheet' in nested:
        # Fallback: save to first Google Sheet API settings
        gs_api = business.business_settings_api.filter(
            is_verify_api=True, api_type='google_sheet'
        ).first()
        if gs_api:
            gs_api.column_mapping = nested['google_sheet']
            gs_api.save(update_fields=['column_mapping'])

    # Save per-source mapping for Public Link
    pl_source_id = source_ids.get('public_link')
    if pl_source_id and 'public_link' in nested:
        pl_src = orders_models.PublicLinkSource.objects.filter(
            id=pl_source_id, business=business
        ).first()
        if pl_src:
            # Convert new-format {db_field: header_name} to old-format {col_idx: db_field}
            pl_headers = pl_src.last_headers or []
            header_lower = [h.lower() for h in pl_headers]
            idx_mapping = {}
            for db_field, header_name in nested['public_link'].items():
                if db_field and header_name:
                    try:
                        idx = header_lower.index(str(header_name).lower())
                        idx_mapping[str(idx)] = db_field
                    except ValueError:
                        pass
            pl_src.last_column_mapping = idx_mapping
            pl_src.save(update_fields=['last_column_mapping'])

    platform_counts = {k: len(v) for k, v in nested.items()}
    return JsonResponse({'success': True, 'total': total, 'platform_counts': platform_counts})


def _resolve_shopify_cols(order):
    """Delegate to _shopify_extract_row — single source of truth."""
    return _shopify_extract_row(order, str(getattr(order, 'id', '')))


def _resolve_woo_cols(order_dict):
    """Delegate to _woo_extract_row — single source of truth."""
    return _woo_extract_row(order_dict)



def _resolve_formula(formula, col_values):
    """Resolve a formula like '{col1} {col2}' using col_values dict."""
    import re
    def replace_col(m):
        col = m.group(1).strip()
        return col_values.get(col, '')
    return re.sub(r'\{([^}]+)\}', replace_col, formula)


@login_required(login_url='/accounts/login/')
@staff_required
def wf_mapping_manager_test(request):
    """AJAX GET: Fetch latest 1 order from the platform and resolve all virtual columns.
    Returns JSON with col_values and resolved_mapping for the active platform.
    """
    business_id = request.GET.get('business_id', '').strip()
    platform    = request.GET.get('platform', '').strip()

    if not business_id or not platform:
        return JsonResponse({'success': False, 'error': 'business_id and platform required'}, status=400)

    try:
        business = business_models.Business.objects.prefetch_related('business_settings_api').get(
            business_id=business_id
        )
    except business_models.Business.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Business not found'}, status=404)

    # OneDrive uses OneDriveSource (not business_settings_api); skip the API config check.
    api_cfg = None
    if platform != 'onedrive':
        api_cfg = business.business_settings_api.filter(is_verify_api=True, api_type=platform).first()
        if not api_cfg:
            return JsonResponse({'success': False, 'error': f'No active {platform} API config found'}, status=400)

    # Load current platform mapping
    raw_mapping = business.import_mapping or {}
    is_nested = any(k in raw_mapping for k in ('shopify', 'woocommerce', 'csv', 'google_sheet', 'onedrive'))
    platform_mapping = raw_mapping.get(platform, {}) if is_nested else {}

    col_values = {}
    order_info = {}
    raw_order  = {}

    try:
        if platform == 'shopify':
            import shopify
            shop_name = (api_cfg.site_api_url or '').replace('https://', '').replace('http://', '').replace('.myshopify.com', '').strip()
            session = shopify.Session(shop_name, api_cfg.api_version or '2023-10', api_cfg.api_access_token)
            shopify.ShopifyResource.activate_session(session)
            orders = shopify.Order.find(limit=1, status='any')
            shopify.ShopifyResource.clear_session()
            if not orders:
                return JsonResponse({'success': False, 'error': 'No orders found in this Shopify store'})
            col_values = _resolve_shopify_cols(orders[0])
            try:
                parsed = json.loads(orders[0].to_json())
                # to_json() wraps in {"order": {...}} — unwrap
                raw_order = parsed.get('order', parsed)
            except Exception:
                try:
                    raw_order = orders[0].to_dict()
                except Exception:
                    raw_order = col_values  # fallback: resolved cols
            order_info = {
                'id':   col_values.get('order.id', ''),
                'name': col_values.get('order.name', ''),
                'date': col_values.get('order.created_at', ''),
                'source': 'shopify',
            }

        elif platform == 'woocommerce':
            from woocommerce import API as WooAPI
            wcapi = WooAPI(
                url=api_cfg.site_api_url or '',
                consumer_key=api_cfg.api_key or '',
                consumer_secret=api_cfg.api_secret or '',
                version='wc/v3',
                timeout=15,
            )
            r = wcapi.get('orders', params={'per_page': 1, 'orderby': 'date', 'order': 'desc'})
            if r.status_code != 200:
                return JsonResponse({'success': False, 'error': f'WooCommerce API error {r.status_code}'})
            orders = r.json()
            if not orders:
                return JsonResponse({'success': False, 'error': 'No orders found in this WooCommerce store'})
            raw_order  = orders[0]
            col_values = _resolve_woo_cols(orders[0])
            order_info = {
                'id':   col_values.get('order.id', ''),
                'name': f"#{col_values.get('order.number', '')}",
                'date': col_values.get('order.date_created', ''),
                'source': 'woocommerce',
            }

        elif platform == 'google_sheet':
            import re as _re
            import gspread
            from google.oauth2.credentials import Credentials
            from google.auth.transport.requests import Request
            from django.conf import settings as django_settings
            from pathlib import Path
            import json as _json

            sheet_url = api_cfg.google_sheet_url or ''
            if not sheet_url:
                return JsonResponse({'success': False, 'error': 'Google Sheet URL is not set on this source.'})

            token_path = Path(django_settings.BASE_DIR) / getattr(
                django_settings, 'GOOGLE_SHEETS_TOKEN_FILE', 'google_sheets_token.json'
            )
            if not token_path.exists():
                return JsonResponse({'success': False, 'error': 'Google Sheets not authorized. Run: python scripts/google_sheets_auth.py'})

            _td = _json.loads(token_path.read_text())
            creds = Credentials(
                token=_td.get('access_token'),
                refresh_token=_td.get('refresh_token'),
                token_uri=_td.get('token_uri', 'https://oauth2.googleapis.com/token'),
                client_id=_td.get('client_id'),
                client_secret=_td.get('client_secret'),
                scopes=_td.get('scope', '').split(),
            )
            if creds.expired and creds.refresh_token:
                creds.refresh(Request())
                _td['access_token'] = creds.token
                token_path.write_text(_json.dumps(_td, indent=2))

            gc = gspread.authorize(creds)
            m = _re.search(r'/spreadsheets/d/([^/]+)', sheet_url)
            if not m:
                return JsonResponse({'success': False, 'error': 'Invalid Google Sheet URL.'})
            sheet_id = m.group(1)
            gid_match = _re.search(r'gid=(\d+)', sheet_url)
            url_gid = int(gid_match.group(1)) if gid_match else 0

            spreadsheet = gc.open_by_key(sheet_id)
            saved_gid = getattr(api_cfg, 'google_sheet_gid', None)
            worksheet = None
            if saved_gid is not None:
                for ws in spreadsheet.worksheets():
                    if ws.id == int(saved_gid):
                        worksheet = ws
                        break
            if worksheet is None:
                for ws in spreadsheet.worksheets():
                    if ws.id == url_gid:
                        worksheet = ws
                        break
            if worksheet is None:
                worksheet = spreadsheet.sheet1

            all_values = worksheet.get_all_values()
            if not all_values or len(all_values) <= 1:
                return JsonResponse({'success': False, 'error': 'No data rows in this sheet.'})

            headers = all_values[0]
            # Latest row = last non-empty row from the bottom
            latest_row = None
            latest_row_num = None
            for i in range(len(all_values) - 1, 0, -1):
                row = all_values[i]
                if any((c or '').strip() for c in row):
                    latest_row = row
                    latest_row_num = i + 1  # 1-based sheet row
                    break
            if latest_row is None:
                return JsonResponse({'success': False, 'error': 'No data rows in this sheet.'})

            col_values = {}
            for j, h in enumerate(headers):
                key = (h or '').strip()
                if not key:
                    continue
                col_values[key] = (latest_row[j] if j < len(latest_row) else '') or ''
            raw_order = dict(col_values)
            raw_order['_row_number'] = latest_row_num
            raw_order['_sheet_tab'] = worksheet.title

            order_info = {
                'id':   col_values.get(platform_mapping.get('client_order_code', ''), '') if platform_mapping else '',
                'name': col_values.get(platform_mapping.get('customer_name', ''), '') if platform_mapping else '',
                'date': col_values.get(platform_mapping.get('order_date', ''), '') if platform_mapping else '',
                'source': 'google_sheet',
            }

        elif platform == 'onedrive':
            source_id = request.GET.get('source_id', '').strip()
            if source_id:
                source = orders_models.OneDriveSource.objects.filter(
                    id=source_id, business__business_id=business_id, is_active=True
                ).first()
            else:
                source = orders_models.OneDriveSource.objects.filter(
                    business__business_id=business_id, is_active=True, is_default_mapping=True
                ).first()
                if not source:
                    source = orders_models.OneDriveSource.objects.filter(
                        business__business_id=business_id, is_active=True
                    ).exclude(last_sheet_name='').first()
                if not source:
                    source = orders_models.OneDriveSource.objects.filter(
                        business__business_id=business_id, is_active=True
                    ).first()
            if not source:
                return JsonResponse({'success': False, 'error': 'No active OneDrive source for this business'})

            file_bytes, err = _onedrive_download_file(source)
            if err:
                return JsonResponse({'success': False, 'error': err})

            wb = _safe_load_workbook(file_bytes)
            sheet_name = source.last_sheet_name
            if not sheet_name or sheet_name not in wb.sheetnames:
                sheet_name = wb.sheetnames[0]
            ws = wb[sheet_name]
            all_rows = list(ws.iter_rows(values_only=True))
            wb.close()

            if not all_rows or len(all_rows) <= 1:
                return JsonResponse({'success': False, 'error': 'No data rows in this OneDrive file.'})

            headers = [str(c).strip() if c is not None else '' for c in all_rows[0]]
            # Latest order = last non-empty data row
            latest_row = None
            latest_row_num = None
            for i in range(len(all_rows) - 1, 0, -1):
                row = all_rows[i]
                if any((str(c).strip() if c is not None else '') for c in row):
                    latest_row = row
                    latest_row_num = i + 1  # 1-based row
                    break
            if latest_row is None:
                return JsonResponse({'success': False, 'error': 'No data rows in this OneDrive file.'})

            col_values = {}
            for j, h in enumerate(headers):
                key = (h or '').strip()
                if not key:
                    continue
                val = latest_row[j] if j < len(latest_row) else ''
                col_values[key] = str(val).strip() if val is not None else ''
            raw_order = dict(col_values)
            raw_order['_row_number'] = latest_row_num
            raw_order['_sheet_tab'] = sheet_name

            order_info = {
                'id':   col_values.get(platform_mapping.get('client_order_code', ''), '') if platform_mapping else '',
                'name': col_values.get(platform_mapping.get('customer_name', ''), '') if platform_mapping else '',
                'date': col_values.get(platform_mapping.get('order_date', ''), '') if platform_mapping else '',
                'source': 'onedrive',
            }

        else:
            return JsonResponse({'success': False, 'error': f'Test not supported for platform: {platform}'})

    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)})

    # Build resolved_mapping: for each db_field in the platform mapping, resolve value
    resolved_mapping = {}
    for db_field, src_col in platform_mapping.items():
        if not src_col:
            continue
        if '{' in src_col:
            value = _resolve_formula(src_col, col_values)
        else:
            value = col_values.get(src_col, '')
        resolved_mapping[db_field] = {'col': src_col, 'value': value}

    return JsonResponse({
        'success': True,
        'platform': platform,
        'order_info': order_info,
        'raw_order': raw_order,
        'col_values': col_values,
        'resolved_mapping': resolved_mapping,
    })


@login_required(login_url='/accounts/login/')
@staff_required
def wf_api_orders(request):
    """
    List orders from approved API businesses.
    When a business is selected, fetch live orders from their Shopify/WooCommerce API.
    """
    # Businesses with at least one approved API config
    api_businesses = business_models.Business.objects.filter(
        business_settings_api__is_verify_api=True
    ).prefetch_related('business_settings_api').distinct().order_by('business_name')

    selected_business_id = request.GET.get('business', '')
    status_filter = request.GET.get('status', '')
    selected_business = None
    selected_api = None
    live_orders = []
    live_error = None
    live_total = None

    if selected_business_id:
        try:
            selected_business = business_models.Business.objects.prefetch_related(
                'business_settings_api'
            ).get(business_id=selected_business_id)
            # Get the approved API config for this business
            selected_api = selected_business.business_settings_api.filter(
                is_verify_api=True
            ).first()
        except business_models.Business.DoesNotExist:
            pass

    # Fetch live orders from the platform API when a business with approved config is selected
    if selected_api:
        try:
            if selected_api.api_type == 'shopify':
                import shopify
                shop_name = (selected_api.site_api_url or '').replace('https://', '').replace('http://', '').replace('.myshopify.com', '').strip()
                session = shopify.Session(shop_name, selected_api.api_version or '2023-10', selected_api.api_access_token)
                shopify.ShopifyResource.activate_session(session)
                orders = shopify.Order.find(limit=50, status='any')
                for o in orders:
                    ship = getattr(o, 'shipping_address', None)
                    items = [
                        {'name': li.name, 'qty': li.quantity, 'price': li.price}
                        for li in (o.line_items or [])
                    ] if hasattr(o, 'line_items') and o.line_items else []
                    cust = o.customer if hasattr(o, 'customer') and o.customer else None
                    cust_name = ''
                    if cust:
                        cust_name = f"{getattr(cust, 'first_name', '')} {getattr(cust, 'last_name', '')}".strip() or getattr(cust, 'email', '')
                    raw_shipping_lines = getattr(o, 'shipping_lines', None) or []
                    live_orders.append({
                        'platform_id': str(o.id),
                        'name': o.name,
                        'customer': cust_name or getattr(o, 'contact_email', ''),
                        'phone': getattr(ship, 'phone', '') if ship else '',
                        'address': getattr(ship, 'address1', '') if ship else '',
                        'country': getattr(ship, 'country', '') if ship else '',
                        'cod': o.total_price,
                        'subtotal': getattr(o, 'subtotal_price', None),
                        'shipping_lines': [
                            {'title': getattr(sl, 'title', ''), 'price': getattr(sl, 'price', '0.00')}
                            for sl in raw_shipping_lines
                        ],
                        'currency': o.currency,
                        'status': o.financial_status,
                        'fulfillment': o.fulfillment_status or 'unfulfilled',
                        'date': o.created_at,
                        'source': 'shopify',
                        'items': items,
                    })
                try:
                    live_total = shopify.Order.count(status='any')
                except Exception:
                    live_total = len(live_orders)
                shopify.ShopifyResource.clear_session()

            elif selected_api.api_type == 'woocommerce':
                from woocommerce import API as WooAPI
                wcapi = WooAPI(
                    url=selected_api.site_api_url or '',
                    consumer_key=selected_api.api_key or '',
                    consumer_secret=selected_api.api_secret or '',
                    version='wc/v3',
                    timeout=15,
                )
                r = wcapi.get('orders', params={'per_page': 50, 'orderby': 'date', 'order': 'desc'})
                if r.status_code == 200:
                    live_total = r.headers.get('X-WP-Total')
                    for o in r.json():
                        billing = o.get('billing', {})
                        shipping = o.get('shipping', {})
                        addr_parts = [shipping.get('address_1') or billing.get('address_1'), shipping.get('city') or billing.get('city')]
                        items = [
                            {'name': li.get('name', ''), 'qty': li.get('quantity', 1), 'price': li.get('price', '')}
                            for li in o.get('line_items', [])
                        ]
                        wc_subtotal = str(sum(float(li.get('subtotal', 0)) for li in o.get('line_items', [])))
                        wc_shipping_lines = [
                            {'title': sl.get('method_title', ''), 'price': sl.get('total', '0.00')}
                            for sl in o.get('shipping_lines', [])
                        ]
                        live_orders.append({
                            'platform_id': str(o.get('id')),
                            'name': f"#{o.get('number')}",
                            'customer': f"{billing.get('first_name','')} {billing.get('last_name','')}".strip(),
                            'phone': billing.get('phone', ''),
                            'address': ', '.join(filter(None, addr_parts)),
                            'country': shipping.get('country') or billing.get('country', ''),
                            'cod': o.get('total'),
                            'subtotal': wc_subtotal,
                            'shipping_lines': wc_shipping_lines,
                            'currency': o.get('currency'),
                            'status': o.get('status'),
                            'fulfillment': None,
                            'date': o.get('date_created'),
                            'source': 'woocommerce',
                            'items': items,
                        })
                else:
                    live_error = f"API error {r.status_code}: {r.text[:200]}"

            elif selected_api.api_type == 'google_sheet':
                import re
                import gspread
                from google.oauth2.credentials import Credentials
                from google.auth.transport.requests import Request
                from django.conf import settings as django_settings
                from pathlib import Path

                sheet_url = selected_api.google_sheet_url or selected_api.site_api_url or ''
                token_path = Path(django_settings.BASE_DIR) / getattr(
                    django_settings, 'GOOGLE_SHEETS_TOKEN_FILE', 'google_sheets_token.json'
                )
                if not token_path.exists():
                    raise Exception(
                        'Google Sheets not authorized yet. '
                        'Run: python scripts/google_sheets_auth.py (one-time setup)'
                    )

                import json as _json
                _td = _json.loads(token_path.read_text())
                creds = Credentials(
                    token=_td.get('access_token'),
                    refresh_token=_td.get('refresh_token'),
                    token_uri=_td.get('token_uri', 'https://oauth2.googleapis.com/token'),
                    client_id=_td.get('client_id'),
                    client_secret=_td.get('client_secret'),
                    scopes=_td.get('scope', '').split(),
                )
                if creds.expired and creds.refresh_token:
                    creds.refresh(Request())
                    _td['access_token'] = creds.token
                    token_path.write_text(_json.dumps(_td, indent=2))

                gc = gspread.authorize(creds)

                match = re.search(r'/spreadsheets/d/([^/]+)', sheet_url)
                if not match:
                    raise Exception('Invalid Google Sheet URL.')
                sheet_id = match.group(1)
                gid_match = re.search(r'gid=(\d+)', sheet_url)
                gid = int(gid_match.group(1)) if gid_match else 0

                spreadsheet = gc.open_by_key(sheet_id)
                worksheet = None
                for ws in spreadsheet.worksheets():
                    if ws.id == gid:
                        worksheet = ws
                        break
                if worksheet is None:
                    worksheet = spreadsheet.sheet1

                all_values = worksheet.get_all_values()
                if not all_values or len(all_values) <= 1:
                    # Try other worksheets if current one is empty
                    for ws in spreadsheet.worksheets():
                        if ws.id == worksheet.id:
                            continue
                        candidate = ws.get_all_values()
                        if len(candidate) > 1:
                            worksheet = ws
                            all_values = candidate
                            break

                if not all_values or len(all_values) <= 1:
                    raise Exception('Sheet is empty — no data rows found.')

                headers = all_values[0]
                data_rows = all_values[1:]
                live_total = len(data_rows)

                # Mapping config is authoritative — no auto-detection fallback.
                saved_mapping = selected_api.column_mapping or {}

                def col_idx_by_header(header_name):
                    """Find column index by exact header name."""
                    for j, h in enumerate(headers):
                        if h.strip() == header_name.strip():
                            return j
                    return None

                def get_idx(field_name, *_ignored_auto_keys):
                    if field_name in saved_mapping:
                        return col_idx_by_header(saved_mapping[field_name])
                    return None

                idx_name = get_idx('customer_name')
                idx_phone = get_idx('customer_phone')
                idx_address = get_idx('customer_address')
                idx_cod = get_idx('cod_amount')
                idx_status = get_idx('cod_status_by_client')
                idx_date = get_idx('order_date')
                idx_country = get_idx('country')
                idx_order = get_idx('client_order_code')
                idx_product = get_idx('package_desc')

                def cell(row, idx):
                    if idx is not None and idx < len(row):
                        v = row[idx]
                        return str(v).strip() if v is not None else ''
                    return ''

                # Build display headers: non-empty sheet headers
                sheet_display_headers = [h for h in headers if h.strip()]

                for i, row in enumerate(data_rows):
                    sheet_row = i + 2  # +2 for header + 1-based
                    order_num = cell(row, idx_order) or str(sheet_row)
                    # Build all cell values keyed by header name
                    all_cells = {}
                    for j, h in enumerate(headers):
                        if h.strip():
                            all_cells[h.strip()] = cell(row, j)
                    live_orders.append({
                        'platform_id': f'gs_{i}_{order_num}',
                        'name': order_num,
                        'customer': cell(row, idx_name),
                        'phone': cell(row, idx_phone),
                        'address': cell(row, idx_address),
                        'country': cell(row, idx_country),
                        'cod': cell(row, idx_cod),
                        'currency': '',
                        'status': cell(row, idx_status) or 'pending',
                        'fulfillment': None,
                        'date': cell(row, idx_date),
                        'source': 'google_sheet',
                        'row_number': sheet_row,
                        'cells': all_cells,
                    })

        except Exception as e:
            live_error = str(e)

    # Annotate live_orders with import status from DB
    if live_orders and selected_business and selected_api:
        if selected_api.api_type == 'google_sheet':
            # For Google Sheets, check by row_number stored in original_order_data
            imported_qs = orders_models.Order.objects.filter(
                business=selected_business,
            ).filter(
                Q(original_order_data__source='google_sheet') |
                Q(original_order_data__source='onedrive')
            ).values('original_order_data', 'id', 'order_number', 'client_order_code')

            imported_by_row = {}
            imported_by_pid = {}
            for r in imported_qs:
                od = r.get('original_order_data') or {}
                info = {
                    'id': r['id'],
                    'number': r['order_number'] or r['client_order_code'] or f"#{r['id']}",
                }
                rn = od.get('row_number')
                if rn is not None:
                    imported_by_row[int(rn)] = info
                pid = od.get('platform_id')
                if pid:
                    imported_by_pid[str(pid)] = info

            for o in live_orders:
                match = imported_by_row.get(o.get('row_number')) or imported_by_pid.get(str(o['platform_id']))
                o['imported'] = bool(match)
                o['imported_order_id'] = match['id'] if match else None
                o['imported_order_number'] = match['number'] if match else None
        else:
            platform_ids = [o['platform_id'] for o in live_orders]
            imported_qs = orders_models.Order.objects.filter(
                business=selected_business,
                original_order_data__source=selected_api.api_type,
                original_order_data__platform_id__in=platform_ids,
            ).values('original_order_data__platform_id', 'id', 'order_number', 'client_order_code')
            imported_map = {
                str(r['original_order_data__platform_id']): {
                    'id': r['id'],
                    'number': r['order_number'] or r['client_order_code'] or f"#{r['id']}",
                }
                for r in imported_qs
            }
            for o in live_orders:
                match = imported_map.get(str(o['platform_id']))
                o['imported'] = bool(match)
                o['imported_order_id'] = match['id'] if match else None
                o['imported_order_number'] = match['number'] if match else None

    # Apply import status filter
    if status_filter == 'imported':
        live_orders = [o for o in live_orders if o.get('imported')]
    elif status_filter == 'not_imported':
        live_orders = [o for o in live_orders if not o.get('imported')]

    # Find last imported row number for default "Go to row"
    last_imported_row = 0
    for o in live_orders:
        if o.get('imported') and o.get('row_number'):
            last_imported_row = max(last_imported_row, o['row_number'])
    # Default goto row: last imported - 5 (min row 2)
    default_goto_row = max(2, last_imported_row - 5) if last_imported_row else 0

    # Filters carried across pages by the shared pagination component.
    # The old hand-rolled pager hardcoded `business` + `status` into every
    # href, so both must survive here or page 2 silently drops the filter.
    filter_params = request.GET.copy()
    filter_params.pop('page', None)
    filter_params.pop('per_page', None)
    filter_params = filter_params.urlencode()

    # Paginate live_orders (list, not queryset)
    from django.core.paginator import Paginator
    try:
        per_page = max(1, min(200, int(request.GET.get('per_page', 50))))
    except (ValueError, TypeError):
        per_page = 25
    paginator = Paginator(live_orders, per_page)

    # If no page param and we have a default_goto_row, auto-navigate to that page
    explicit_page = request.GET.get('page')
    if not explicit_page and default_goto_row and selected_api and selected_api.api_type == 'google_sheet':
        # row_number is sheet_row (1-based, header=1), data index = row_number - 2
        data_idx = default_goto_row - 2
        page_number = max(1, (data_idx // per_page) + 1)
    else:
        try:
            page_number = int(explicit_page or 1)
        except (ValueError, TypeError):
            page_number = 1
    page_obj = paginator.get_page(page_number)

    # Sheet headers for Google Sheet dynamic columns
    gs_headers = []
    if selected_api and selected_api.api_type == 'google_sheet':
        try:
            gs_headers = sheet_display_headers
        except NameError:
            gs_headers = []

    context = {
        'api_businesses': api_businesses,
        'selected_business': selected_business,
        'selected_business_id': selected_business_id,
        'selected_api': selected_api,
        'status_filter': status_filter,
        'live_orders': page_obj,
        'live_error': live_error,
        'live_total': live_total,
        'total_filtered': len(live_orders),
        'page_obj': page_obj,
        # String so the shared pagination component's per-page <select>
        # (which compares strings) marks the current size as selected.
        'per_page': str(per_page),
        'filter_params': filter_params,
        'gs_headers': gs_headers,
        'default_goto_row': default_goto_row,
    }
    return render(request, 'workforce/orders_api.html', context)


