@login_required(login_url='/accounts/login/')
@staff_required
def dl_list_incompleted_details(request):
    # Get incomplete delivery tasks (not delivered, not cancelled)
    dl_tasks = delivery_models.DeliveryTask.objects.select_related(
        'order', 'driver', 'business', 'pickup_location', 'order__business'
    ).prefetch_related(
        'order__order_items',
    ).filter(
        order__business__business_status='active',
    ).exclude(
        dl_task_status__in=['delivered', 'partial_delivery', 'cancelled']
    ).order_by('-created_at')

    # Get filter parameters
    code = (request.GET.get('code', '') or request.GET.get('dlCode', '') or request.GET.get('cCode', '')).strip()
    customer = (request.GET.get('customer', '') or request.GET.get('mobile', '')).strip()
    driver_name = request.GET.get('driverName', '')
    c_status = request.GET.get('cStatus', '')
    dl_status = request.GET.get('dlStatus', '') or request.GET.get('dmsStatus', '')
    date_from = request.GET.get('dateFrom', '')
    date_to = request.GET.get('dateTo', '')
    business_id = request.GET.get('business', '')

    if code:
        dl_tasks = dl_tasks.filter(
            Q(dl_task_number__icontains=code) |
            Q(order__client_order_code__icontains=code) |
            Q(order__order_number__icontains=code)
        )
    if customer:
        dl_tasks = dl_tasks.filter(
            Q(order__customer_phone__icontains=customer) |
            Q(order__customer_name__icontains=customer)
        )
    if driver_name:
        dl_tasks = dl_tasks.filter(
            Q(driver__user__first_name__icontains=driver_name) |
            Q(driver__user__last_name__icontains=driver_name) |
            Q(driver__user__username__icontains=driver_name)
        )
    if c_status:
        dl_tasks = dl_tasks.filter(dl_task_status_client=c_status)
    if dl_status:
        dl_tasks = dl_tasks.filter(dl_task_status=dl_status)
    if date_from:
        dl_tasks = dl_tasks.filter(dl_task_date__gte=date_from)
    if date_to:
        dl_tasks = dl_tasks.filter(dl_task_date__lte=date_to)
    if business_id:
        dl_tasks = dl_tasks.filter(order__business_id=business_id)

    businesses = business_models.Business.objects.filter(
        business_status='active'
    ).order_by('business_name')

    dl_tasks = paginate_queryset(request, dl_tasks)

    # Attach the most recent "dl_task_status → failed" history entry per order
    # (driver's free-text reason lives in OrderStatusHistory.notes, not on the task)
    order_ids = [t.order_id for t in dl_tasks.object_list if t.order_id]
    latest_failed_by_order = {}
    if order_ids:
        failed_history = orders_models.OrderStatusHistory.objects.filter(
            order_id__in=order_ids,
            field_name='dl_task_status',
            new_value='failed',
        ).order_by('order_id', '-created_at')
        for entry in failed_history:
            if entry.order_id not in latest_failed_by_order:
                latest_failed_by_order[entry.order_id] = entry
    for t in dl_tasks.object_list:
        t.latest_failed_history = latest_failed_by_order.get(t.order_id)

    data = {
        'dl_tasks': dl_tasks,
        'businesses': businesses,
        'today': timezone.localtime().date(),
        'page_title': 'Incompleted Tasks',
        'page_subtitle': 'Pending delivery tasks',
        'page_icon': 'fa-clock-rotate-left',
        'list_type': 'incompleted',
        'show_filters': True,
        'show_failure_reason': True,
        'filters': {
            'code': code, 'customer': customer,
            'driverName': driver_name, 'cStatus': c_status, 'dlStatus': dl_status,
            'dateFrom': date_from, 'dateTo': date_to, 'business': business_id,
        }
    }
    return render(request, 'workforce/parts/lists/dl_list_all.html', data)


