# Order Detail View ------------------------------------------------------------------------------------------------------

@login_required(login_url='/accounts/login/')
@staff_required
def order_detail(request, order_id):
    """Display order detail page"""
    order = get_object_or_404(
        orders_models.Order.objects.select_related('business', 'pickup_location', 'verified_by'),
        id=order_id
    )

    # Get related data with select_related to avoid N+1 queries
    order_items = orders_models.OrderItem.objects.filter(order=order)
    order_comments = orders_models.OrderComments.objects.filter(order=order).select_related('user').order_by('-created_at')
    verification_logs = orders_models.OrderVerificationLog.objects.filter(order=order).select_related('verified_by').order_by('-created_at')

    # Get delivery task if exists with related driver
    delivery_task = delivery_models.DeliveryTask.objects.select_related(
        'driver', 'driver__user', 'pickup_location'
    ).filter(order=order).first()

    # Get status change timeline
    status_history = orders_models.OrderStatusHistory.objects.filter(
        order=order
    ).select_related('changed_by').order_by('created_at')

    from core.templatetags.custom_filters import whatsapp_number
    wa_data = _apply_wa_route(_fetch_whatsapp_instances(), 'orders_tasks')
    wa_default_to = whatsapp_number(order.customer_whatsapp or order.customer_phone)
    wa_default_message = _build_order_whatsapp_message(order)

    # Latest address-verification job for this order (for the detail panel).
    address_verify_job = None
    try:
        from whatsapp.models import AddressVerificationJob
        address_verify_job = (
            AddressVerificationJob.objects
            .filter(order=order)
            .select_related('received_message')
            .order_by('-created_at')
            .first()
        )
    except Exception:
        address_verify_job = None

    # Resolve the human-readable zone name for the delivery zone number, if any.
    dl_zone_name = None
    if order.dl_zone:
        try:
            zone_obj = delivery_models.ZoneName.objects.filter(
                zone_number=order.dl_zone
            ).first()
            if zone_obj:
                dl_zone_name = zone_obj.zone_name
        except Exception:
            dl_zone_name = None

    context = {
        'order': order,
        'order_items': order_items,
        'dl_zone_name': dl_zone_name,
        'order_comments': order_comments,
        'verification_logs': verification_logs,
        'delivery_task': delivery_task,
        'status_history': status_history,
        'timeline_count': status_history.count(),
        'wa_instances': wa_data['instances'],
        'wa_default_instance': wa_data['default'],
        'wa_instances_error': wa_data['error'],
        'wa_default_to': wa_default_to,
        'wa_default_message': wa_default_message,
        'address_verify_job': address_verify_job,
    }

    # Check if this is being loaded in a panel (via HTMX)
    # Use panel template only when targeting the slide panel, not main content
    is_htmx = request.headers.get('HX-Request') == 'true'
    hx_target = request.headers.get('HX-Target', '')

    # If targeting main-content or using hx-select, use full page template
    # Panel template is only for the slide-out panel (orderDetailContent)
    use_panel = is_htmx and hx_target == 'orderDetailContent'
    template = 'workforce/order_detail_panel.html' if use_panel else 'workforce/order_detail.html'

    return render(request, template, context)


def _build_delivery_recovery_whatsapp_message(order, driver_failure_note=''):
    """Recovery message sent 10 min after a driver marks a delivery failed.

    Includes the driver's structured failure reason (and any notes) so the
    customer knows exactly what went wrong, plus the same verify-link the
    auto-import flow uses so they can re-pin their location to retry.
    """
    from core.templatetags.custom_filters import generate_order_verify_key

    verify_key = generate_order_verify_key(order.order_number, order.customer_phone)
    note_line = ''
    if driver_failure_note:
        note_line = f"Reason: {driver_failure_note}\n"
    return (
        f"Hi {order.customer_name}, sorry — we couldn't complete delivery of "
        f"your order {order.order_number}.\n\n"
        f"{note_line}"
        f"We'd like to deliver again. Please confirm your location so the driver "
        f"can find you:\n"
        f"📌 https://ezzydelivery.qa/orders/verify/?order={order.order_number}&key={verify_key}\n\n"
        f"Or reply with your live WhatsApp location pin."
    )


def _build_order_whatsapp_message(order):
    """Default WhatsApp verification message including up to 2 product names."""
    from core.templatetags.custom_filters import generate_order_verify_key

    items = list(
        orders_models.OrderItem.objects
        .filter(order=order)
        .select_related('product')[:3]
    )
    names = []
    for it in items[:2]:
        name = it.product.item_name if it.product and it.product.item_name else None
        if not name and it.notes:
            parts = it.notes.split('__')
            name = (parts[1] if len(parts) >= 2 else it.notes).strip()
        if name:
            names.append(name)

    items_line = ''
    if names:
        joined = ' & '.join(names)
        more = len(items) - len(names)
        suffix = f' (+{more} more)' if more > 0 else ''
        items_line = f"🛒 Items: {joined}{suffix}\n"

    verify_key = generate_order_verify_key(order.order_number, order.customer_phone)
    return (
        f"Hi {order.customer_name}, this is regarding your order {order.order_number}. "
        f"Please confirm your delivery details and availability.\n\n"
        f"{items_line}"
        f"📌 Verify your location: https://ezzydelivery.qa/orders/verify/"
        f"?order={order.order_number}&key={verify_key}"
    )


def _fetch_whatsapp_instances():
    """Fetch Evolution API instances. Cached for 60s to avoid per-render hits."""
    import requests
    from django.conf import settings as dj_settings
    from django.core.cache import cache

    cached = cache.get('wsmw_evolution_instances')
    if cached is not None:
        return cached

    api_url = getattr(dj_settings, 'EVOLUTION_URL', '')
    api_key = getattr(dj_settings, 'EVOLUTION_API_KEY', '')
    default_instance = getattr(dj_settings, 'EVOLUTION_INSTANCE', '')

    result = {'instances': [], 'default': default_instance, 'error': None}

    if not api_url or not api_key:
        result['error'] = 'Evolution API not configured'
        return result

    try:
        resp = requests.get(
            f"{api_url.rstrip('/')}/instance/fetchInstances",
            headers={'apikey': api_key, 'Accept': 'application/json'},
            timeout=8,
        )
        raw = resp.json() if resp.text else []
    except Exception as e:
        result['error'] = str(e)
        return result

    items = raw if isinstance(raw, list) else raw.get('instances', []) or []
    instances = []
    for it in items:
        inst = it.get('instance', it) if isinstance(it, dict) else {}
        name = inst.get('instanceName') or inst.get('name') or it.get('name')
        if not name:
            continue
        owner = inst.get('owner') or inst.get('ownerJid') or it.get('ownerJid') or ''
        number = owner.split('@')[0] if owner else ''
        status = (
            inst.get('status')
            or inst.get('connectionStatus')
            or it.get('connectionStatus')
            or ''
        )
        instances.append({
            'name': name,
            'number': number,
            'status': status,
            'is_default': name == default_instance,
            'connected': bool(status) and status.lower() in ('open', 'connected'),
        })

    instances.sort(key=lambda x: (not x['is_default'], x['name'].lower()))
    result['instances'] = instances
    cache.set('wsmw_evolution_instances', result, 60)
    return result


def _wa_route_instance(section):
    """Return the active WhatsAppInstance configured for a platform section, or None."""
    from core.whatsapp_utils import get_route_instance
    return get_route_instance(section)


def _apply_wa_route(wa_data, section):
    """Limit a _fetch_whatsapp_instances() result to the section's configured sender."""
    inst = _wa_route_instance(section)
    if not inst:
        return wa_data
    matched = [dict(i, is_default=True) for i in wa_data.get('instances', [])
               if i['name'] == inst.instance_name]
    if not matched:
        # Configured sender missing from the Evolution server: still pin the
        # dropdown to it so messages never fall through to another number.
        digits = ''.join(c for c in (inst.phone_number or '') if c.isdigit())
        matched = [{'name': inst.instance_name, 'number': digits,
                    'status': '', 'is_default': True, 'connected': False}]
    return {**wa_data, 'instances': matched, 'default': inst.instance_name}


@login_required(login_url='/accounts/login/')
@staff_required
def order_whatsapp_defaults(request, order_id):
    """Return the default WhatsApp `to` and `message` for an order (used by list-page modal)."""
    from core.templatetags.custom_filters import whatsapp_number
    order = get_object_or_404(orders_models.Order, id=order_id)
    return JsonResponse({
        'success': True,
        'order_number': order.order_number,
        'customer_name': order.customer_name,
        'to': whatsapp_number(order.customer_whatsapp or order.customer_phone),
        'message': _build_order_whatsapp_message(order),
    })


def _send_order_whatsapp_internal(order, message=None, instance=None, to=None):
    """Send an order WhatsApp via Evolution API. Returns (ok: bool, info: dict).

    Reusable from the manual button view and the auto-import pipeline.
    Falls back to the order's customer_whatsapp/phone and the default verify
    message template when arguments are omitted.
    """
    import requests
    from django.conf import settings as dj_settings
    from core.templatetags.custom_filters import whatsapp_number

    instance = (instance or '').strip()
    if not instance:
        route_inst = _wa_route_instance('orders_tasks')
        instance = route_inst.instance_name if route_inst else getattr(dj_settings, 'EVOLUTION_INSTANCE', '')
    to_raw = (to or '').strip() or order.customer_whatsapp or order.customer_phone
    phone = whatsapp_number(to_raw)
    if not phone:
        return False, {'error': 'No WhatsApp number on order'}

    msg = (message or '').strip() or _build_order_whatsapp_message(order)

    api_url = getattr(dj_settings, 'EVOLUTION_URL', '')
    api_key = getattr(dj_settings, 'EVOLUTION_API_KEY', '')
    if not api_url or not api_key or not instance:
        return False, {'error': 'Evolution API not configured (missing url/key/instance)'}

    try:
        resp = requests.post(
            f"{api_url.rstrip('/')}/message/sendText/{instance}",
            json={'number': phone, 'text': msg},
            headers={'Content-Type': 'application/json', 'apikey': api_key},
            timeout=10,
        )
        ok = resp.status_code in (200, 201)
        data = resp.json() if resp.text else {}
    except requests.exceptions.RequestException as e:
        return False, {'error': f'Send failed: {e}'}

    if ok:
        return True, {'phone': phone, 'instance': instance}
    return False, {
        'error': data.get('message') or f'HTTP {resp.status_code}',
        'detail': data,
    }


@require_POST
@login_required(login_url='/accounts/login/')
@staff_required
def send_order_whatsapp(request, order_id):
    """Send a WhatsApp message for an order via Evolution API.

    Accepts JSON body with optional `instance`, `to`, and `message` overrides.
    Falls back to the order's customer WhatsApp + the default verification
    template when fields are omitted.
    """
    import json as _json

    order = get_object_or_404(orders_models.Order, id=order_id)

    try:
        body = _json.loads(request.body or b'{}')
    except ValueError:
        body = {}

    ok, info = _send_order_whatsapp_internal(
        order,
        message=body.get('message'),
        instance=body.get('instance'),
        to=body.get('to'),
    )
    if ok:
        return JsonResponse({'success': True, **info})
    status = 400 if info.get('error', '').startswith(('No WhatsApp', 'Evolution API not')) else 502
    return JsonResponse({'success': False, **info}, status=status)


@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def cancel_order(request, order_id):
    """Cancel an order"""
    try:
        order = get_object_or_404(
            orders_models.Order.objects.select_related('business').prefetch_related('order_items', 'delivery_task'),
            id=order_id
        )

        # Cannot cancel already delivered or already cancelled orders
        if order.order_status == 'delivered':
            return JsonResponse({
                'success': False,
                'error': 'Cannot cancel a delivered order'
            }, status=400)

        if order.order_status == 'cancelled':
            return JsonResponse({
                'success': False,
                'error': 'Order is already cancelled'
            }, status=400)

        # Block cancellation if driver has already physically picked up the package
        delivery_task = delivery_models.DeliveryTask.objects.filter(order=order).first()
        active_pickup_statuses = ('picked_up', 'start_ride', 'in_transit', 'out_for_delivery', 'contacted')
        if delivery_task and delivery_task.dl_task_status in active_pickup_statuses:
            return JsonResponse({
                'success': False,
                'error': f'Cannot cancel — driver has already picked up this order (status: {delivery_task.get_dl_task_status_display()}). Contact the driver directly.'
            }, status=400)

        # Collect optional cancellation reason from request body
        cancellation_reason = None
        cancellation_notes = None
        try:
            body = json.loads(request.body)
            cancellation_reason = body.get('cancellation_reason')
            cancellation_notes = body.get('cancellation_notes')
        except (json.JSONDecodeError, AttributeError):
            pass

        # Update order status
        old_status = order.order_status
        order.order_status = 'cancelled'
        order.cancelled_by = request.user
        if cancellation_reason:
            order.cancellation_reason = cancellation_reason
        if cancellation_notes:
            order.cancellation_notes = cancellation_notes
        order.save()

        # Cancel related delivery task (if not already picked up — already guarded above)
        if delivery_task and delivery_task.dl_task_status != 'cancelled':
            delivery_task.dl_task_status = 'cancelled'
            delivery_task.dl_task_status_client = '9'
            delivery_task.save(update_fields=['dl_task_status', 'dl_task_status_client'])

        # Log the cancellation
        notes_text = f'Order cancelled by {request.user.username}'
        if cancellation_reason:
            notes_text += f' | Reason: {cancellation_reason}'
        if cancellation_notes:
            notes_text += f' | Notes: {cancellation_notes}'
        orders_models.OrderVerificationLog.objects.create(
            order=order,
            verified_by=request.user,
            action='order_cancelled',
            old_status=old_status,
            new_status='cancelled',
            notes=notes_text
        )

        # Return updated row HTML for HTMX
        if request.headers.get('HX-Request'):
            return render(request, 'orders/parts/order_row.html', {'order': order})

        return JsonResponse({
            'success': True,
            'message': 'Order cancelled successfully',
            'order_id': order.id
        })
    except Http404:
        raise
    except Exception as e:
        logger.exception("Error cancelling order %s: %s", order_id, str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while cancelling the order'
        }, status=400)


@login_required(login_url='/accounts/login/')
@staff_required
def duplicate_order(request, order_id):
    """
    Duplicate an existing order into a fresh draft (status 'to_review') for a
    repeat customer. Copies customer/address/items/COD but resets the workflow:
    new order_number + client_order_code, no tasks, no COD collected, no locks,
    verification back to pending. Redirects to the new order's detail page.
    """
    import uuid
    from django.db import transaction

    src = get_object_or_404(
        orders_models.Order.objects.select_related('business', 'pickup_location')
        .prefetch_related('order_items'),
        id=order_id
    )

    try:
        with transaction.atomic():
            new_order = orders_models.Order.objects.create(
                business=src.business,
                client_order_code=f"WF-{uuid.uuid4().hex[:8].upper()}",  # new unique code per business
                # --- copied delivery / customer data ---
                customer_name=src.customer_name,
                customer_phone=src.customer_phone,
                customer_whatsapp=src.customer_whatsapp,
                customer_address=src.customer_address,
                dl_zone=src.dl_zone,
                dl_street=src.dl_street,
                dl_building=src.dl_building,
                latitude=src.latitude,
                longitude=src.longitude,
                coords_accuracy=src.coords_accuracy,
                pickup_location=src.pickup_location,
                cod_amount=src.cod_amount,
                dl_included=src.dl_included,
                dl_amount=src.dl_amount,
                order_notes=src.order_notes,
                package_description=src.package_description,
                package_qty=src.package_qty,
                order_type=src.order_type,
                delivery_speed=src.delivery_speed,
                preferred_time_slot=src.preferred_time_slot,
                # --- reset workflow ---
                order_status='to_review',
                task_status='new_order',
                verification_status='pending',
                platform='manual',
            )

            # Copy order items
            for item in src.order_items.all():
                orders_models.OrderItem.objects.create(
                    order=new_order,
                    product=item.product,
                    quantity=item.quantity,
                    unit_price=item.unit_price,
                    notes=item.notes,
                )

            # Audit trail linking the duplicate to its source
            orders_models.OrderComments.objects.create(
                order=new_order,
                name=request.user.username,
                body=f"Repeated from order {src.order_number}",
            )

        messages.success(
            request,
            f"Order duplicated from {src.order_number}. Review and publish the new draft."
        )
        return redirect('workforce:order_detail', order_id=new_order.id)

    except Exception as e:
        logger.exception("Error duplicating order %s: %s", order_id, str(e))
        messages.error(request, "An error occurred while duplicating the order.")
        return redirect('workforce:order_detail', order_id=order_id)


@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def partial_return_order(request, order_id):
    """
    Process partial return for a delivered order.
    Expects JSON body: { "items": [{"item_id": 42, "quantity": 1}, ...] }
    Restores stock for returned items and auto-creates RMA.
    """
    try:
        order = get_object_or_404(
            orders_models.Order.objects.select_related('business'),
            id=order_id
        )

        if order.order_status != 'delivered':
            return JsonResponse({
                'success': False,
                'error': f'Can only process returns for delivered orders (current: {order.get_order_status_display()})'
            }, status=400)

        data = json.loads(request.body)
        returned_items = data.get('items', [])

        if not returned_items:
            return JsonResponse({
                'success': False,
                'error': 'No items specified for return'
            }, status=400)

        # Validate items
        for ret in returned_items:
            if not ret.get('item_id') or not ret.get('quantity') or ret['quantity'] < 1:
                return JsonResponse({
                    'success': False,
                    'error': f'Invalid return item: {ret}. Each item needs item_id and quantity >= 1'
                }, status=400)

            # Check the item exists and quantity is valid
            try:
                item = orders_models.OrderItem.objects.get(pk=ret['item_id'], order=order)
                max_returnable = item.quantity - (item.quantity_returned or 0)
                if ret['quantity'] > max_returnable:
                    return JsonResponse({
                        'success': False,
                        'error': f'Cannot return {ret["quantity"]} of "{item.display_name}" — max returnable is {max_returnable}'
                    }, status=400)
            except orders_models.OrderItem.DoesNotExist:
                return JsonResponse({
                    'success': False,
                    'error': f'Order item {ret["item_id"]} not found in this order'
                }, status=400)

        # Process the partial return
        from django.db import transaction as db_transaction
        from warehouse.signals import process_partial_return

        with db_transaction.atomic():
            returned = process_partial_return(order, returned_items)

        # Log the action
        item_summary = ', '.join(
            f'{r["quantity"]}x item#{r["item_id"]}' for r in returned_items
        )
        orders_models.OrderVerificationLog.objects.create(
            order=order,
            verified_by=request.user,
            action='partial_return',
            notes=f'Partial return processed: {item_summary}'
        )

        return JsonResponse({
            'success': True,
            'message': f'{len(returned)} item(s) returned successfully',
            'returned_items': [
                {
                    'item_id': item.id,
                    'product': item.display_name,
                    'delivery_status': item.delivery_status,
                    'quantity_delivered': item.quantity_delivered,
                    'quantity_returned': item.quantity_returned,
                }
                for item in returned
            ]
        })

    except Http404:
        raise
    except json.JSONDecodeError:
        return JsonResponse({'success': False, 'error': 'Invalid JSON'}, status=400)
    except Exception as e:
        logger.exception("Error processing partial return for order %s: %s", order_id, str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while processing the return'
        }, status=500)


@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def assign_driver_to_order(request, order_id):
    """Assign a driver to an order (from AI suggest result)"""
    try:
        order = get_object_or_404(
            orders_models.Order.objects.select_related('business'),
            id=order_id
        )
        data = json.loads(request.body)
        driver_id = data.get('driver_id')

        if not driver_id:
            return JsonResponse({
                'success': False,
                'error': 'Driver ID is required'
            }, status=400)

        # Verify driver exists and is approved
        try:
            driver = fleet_models.Driver.objects.get(driver_id=driver_id, driver_status='approved')
        except fleet_models.Driver.DoesNotExist:
            return JsonResponse({
                'success': False,
                'error': f'Driver {driver_id} not found or not approved'
            }, status=400)

        # Check if order already has a delivery task - use select_for_update to prevent race conditions
        from django.db import transaction

        with transaction.atomic():
            existing_task = delivery_models.DeliveryTask.objects.select_for_update().filter(order=order).first()

            if existing_task:
                # Update existing task
                old_driver = existing_task.driver
                existing_task.driver = driver
                existing_task.save()

                # Log the update
                orders_models.OrderVerificationLog.objects.create(
                    order=order,
                    verified_by=request.user,
                    action='driver_reassigned',
                    old_status=str(old_driver.driver_id) if old_driver else 'None',
                    new_status=str(driver_id),
                    notes=f'Driver reassigned from AI suggestion: {driver.user.get_full_name() if driver.user else driver.driver_code}'
                )
            else:
                # Create new delivery task
                task = delivery_models.DeliveryTask.objects.create(
                    order=order,
                    driver=driver,
                    business=order.business,
                    pickup_location=order.pickup_location,
                    dl_task_status='pending',
                    dl_task_number=f'DL-{order.order_number}'
                )

                # Log the assignment
                orders_models.OrderVerificationLog.objects.create(
                    order=order,
                    verified_by=request.user,
                    action='driver_assigned',
                    old_status='None',
                    new_status=str(driver_id),
                    notes=f'Driver assigned from AI suggestion: {driver.user.get_full_name() if driver.user else driver.driver_code}'
                )

        driver_name = driver.user.get_full_name() if driver.user else driver.driver_code

        return JsonResponse({
            'success': True,
            'message': f'Driver {driver_name} assigned successfully',
            'driver_id': driver_id,
            'driver_name': driver_name
        })
    except json.JSONDecodeError:
        return JsonResponse({
            'success': False,
            'error': 'Invalid JSON data'
        }, status=400)
    except Exception as e:
        logger.exception("Error assigning driver to order %s: %s", order_id, str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while assigning driver'
        }, status=400)


@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def delete_order(request, order_id):
    """Permanently delete an order and its related records. Superadmin only."""
    profile = get_cached_profile(request)
    if not profile or not profile.is_superadmin:
        return JsonResponse({'success': False, 'error': 'Superadmin access required'}, status=403)
    try:
        order = get_object_or_404(
            orders_models.Order.objects.select_related('business'),
            id=order_id
        )

        # Block deletion of delivered orders with COD collected
        delivery_task = delivery_models.DeliveryTask.objects.filter(order=order).first()
        if delivery_task and delivery_task.cod_collected:
            return JsonResponse({
                'success': False,
                'error': 'Cannot delete — COD has been collected for this order. Cancel it instead.'
            }, status=400)

        # Only allow deletion while the delivery task is still in its initial
        # state (no fleet action yet). Once the status has been updated
        # (assigned/accepted/picked up/…), it must be cancelled, not deleted.
        INITIAL_TASK_STATUSES = {'', 'for_review', 'pending'}
        if delivery_task and (delivery_task.dl_task_status or '') not in INITIAL_TASK_STATUSES:
            status_label = delivery_task.get_dl_task_status_display() or delivery_task.dl_task_status
            return JsonResponse({
                'success': False,
                'error': f'Cannot delete — the delivery task has already been updated (status: {status_label}). Cancel it instead.'
            }, status=400)

        order_number = order.order_number or order.client_order_code or str(order.id)
        logger.info("Order %s (ID %s) deleted by %s", order_number, order.id, request.user.username)

        # Delete related records (order uses DO_NOTHING FKs, so manual cleanup)
        # Order matters: delivery tasks reference address updates, so tasks first
        orders_models.OrderVerificationLog.objects.filter(order=order).delete()
        orders_models.OrderStatusHistory.objects.filter(order=order).delete()
        delivery_models.DeliveryTask.objects.filter(order=order).delete()
        delivery_models.DlAddressUpdate.objects.filter(order=order).delete()
        order.order_items.all().delete()
        order.delete()

        if request.headers.get('HX-Request'):
            return HttpResponse('')

        return JsonResponse({
            'success': True,
            'message': f'Order {order_number} deleted'
        })
    except Http404:
        raise
    except Exception as e:
        logger.exception("Error deleting order %s: %s", order_id, str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while deleting the order'
        }, status=400)


@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def update_order_zone(request, order_id):
    """Update order delivery zone (from AI parse result)"""
    try:
        order = get_object_or_404(
            orders_models.Order.objects.select_related('business'),
            id=order_id
        )
        data = json.loads(request.body)
        zone_number = data.get('zone_number')
        street_number = data.get('street_number')
        building_number = data.get('building_number')
        latitude = data.get('latitude')
        longitude = data.get('longitude')
        coords_accuracy = data.get('coords_accuracy')  # optional, sent by JS

        if not zone_number:
            return JsonResponse({
                'success': False,
                'error': 'Zone number is required'
            }, status=400)

        # Look up zone name (optional — save even if zone not in ZoneName table)
        zone = delivery_models.ZoneName.objects.filter(zone_number=zone_number, is_active=True).first()
        zone_display = zone.zone_name if zone else f'Zone {zone_number}'

        # Update order zone and address fields
        old_zone = order.dl_zone
        old_lat, old_lng = order.latitude, order.longitude
        old_accuracy = order.coords_accuracy or ''
        order.dl_zone = zone_number
        if street_number:
            order.dl_street = str(street_number)
        if building_number:
            order.dl_building = str(building_number)

        # Update order coordinates and accuracy if provided
        coords_saved = False
        if latitude and longitude:
            order.latitude = latitude
            order.longitude = longitude
            # Derive accuracy: use value sent by JS, or infer from building presence
            if coords_accuracy:
                order.coords_accuracy = coords_accuracy
            elif building_number:
                order.coords_accuracy = 'exact'
            else:
                order.coords_accuracy = 'street'
            coords_saved = True

        order.save()

        if coords_saved:
            location_history.log_location_update(
                order, source='AI address parse', actor=request.user,
                old_lat=old_lat, old_lng=old_lng, old_accuracy=old_accuracy,
                new_lat=order.latitude, new_lng=order.longitude,
                new_accuracy=order.coords_accuracy,
                note=f'Zone {order.dl_zone}'
                     + (f' / Street {order.dl_street}' if order.dl_street else '')
                     + (f' / Building {order.dl_building}' if order.dl_building else ''),
            )

        # Also update delivery task address (dl_to_address) for legacy compatibility
        if latitude and longitude:
            delivery_task = delivery_models.DeliveryTask.objects.filter(order=order).first()
            if delivery_task and delivery_task.dl_to_address:
                dl_address = delivery_task.dl_to_address
                dl_address.dl_latitude = latitude
                dl_address.dl_longitude = longitude
                dl_address.dl_zone = zone_number
                if street_number:
                    dl_address.dl_street = str(street_number)
                if building_number:
                    dl_address.dl_building = str(building_number)
                dl_address.save()

        # Tier 4 self-learning: capture the customer's free-text address -> this zone
        # as an alias so the same spelling/typo resolves automatically next time.
        if order.customer_address:
            try:
                from delivery.zone_resolver import learn_alias
                learn_alias(order.customer_address, zone_number)
            except Exception as e:
                logger.warning("Zone alias learning failed for order %s: %s", order_id, e)

        # Log the update
        notes = f'Zone updated from AI parse: {zone_display}'
        if coords_saved:
            notes += f' | Coordinates saved: {latitude}, {longitude}'
        orders_models.OrderVerificationLog.objects.create(
            order=order,
            verified_by=request.user,
            action='zone_updated',
            old_status=str(old_zone) if old_zone else 'None',
            new_status=str(zone_number),
            notes=notes
        )

        return JsonResponse({
            'success': True,
            'message': f'Zone updated to {zone_number} ({zone_display})' + (' with coordinates' if coords_saved else ''),
            'zone_number': zone_number,
            'zone_name': zone_display,
            'coordinates_saved': coords_saved
        })
    except json.JSONDecodeError:
        return JsonResponse({
            'success': False,
            'error': 'Invalid JSON data'
        }, status=400)
    except Exception as e:
        logger.exception("Error updating zone for order %s: %s", order_id, str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while updating zone'
        }, status=400)


@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def resolve_location_link(request):
    """AJAX: resolve a Google Maps short link or Plus Code to lat/lng (staff version)."""
    try:
        data = json.loads(request.body) if request.body else {}
        text = data.get('text', '').strip()
        if not text:
            return JsonResponse({'error': 'No text provided'}, status=400)

        from ai_agent.tools.address_tools import extract_coords_from_text

        lat, lng, source, link = extract_coords_from_text(text)
        if lat and lng:
            return JsonResponse({'lat': float(lat), 'lng': float(lng), 'source': source})

        import re
        plus_code_match = re.match(r'^([A-Z0-9]{4,8}\+[A-Z0-9]{1,4})\s*(.*)', text, re.IGNORECASE)
        if plus_code_match:
            code = plus_code_match.group(1)
            locality = plus_code_match.group(2).strip() or 'Doha Qatar'
            try:
                import requests as http_requests
                resp = http_requests.get(
                    'https://nominatim.openstreetmap.org/search',
                    params={'q': f'{code} {locality}', 'format': 'json', 'limit': 1},
                    headers={'User-Agent': 'EzzyDelivery/1.0'},
                    timeout=5,
                )
                results = resp.json()
                if results:
                    lat = float(results[0]['lat'])
                    lng = float(results[0]['lon'])
                    if 24.0 <= lat <= 27.0 and 50.0 <= lng <= 52.5:
                        return JsonResponse({'lat': lat, 'lng': lng, 'source': 'plus_code'})
            except Exception:
                pass
            try:
                from openlocationcode import openlocationcode as olc
                if olc.isValid(code) and olc.isFull(code):
                    area = olc.decode(code)
                    return JsonResponse({'lat': area.latitudeCenter, 'lng': area.longitudeCenter, 'source': 'plus_code'})
            except ImportError:
                pass

        return JsonResponse({'error': 'Could not resolve coordinates'}, status=404)
    except (json.JSONDecodeError, ValueError):
        return JsonResponse({'error': 'Invalid request'}, status=400)


# AJAX Endpoints for Orders List ------------------------------------------------------------------------------------------------------

@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def publish_order_to_delivery(request, order_id):
    """AJAX endpoint to publish order to delivery"""
    try:
        order = get_object_or_404(
            orders_models.Order.objects.select_related('business').prefetch_related('order_items', 'delivery_task'),
            id=order_id
        )

        previous_status = order.order_status

        # Update order status to publish (triggers auto delivery task creation signal)
        order.order_status = 'publish'
        order.task_status = 'dl_task_listed'
        order.save()

        # Refresh to get updated delivery_task after signal runs
        order = orders_models.Order.objects.select_related('business').prefetch_related('order_items', 'delivery_task').get(id=order_id)

        # Log the publish action
        orders_models.OrderVerificationLog.objects.create(
            order=order,
            verified_by=request.user,
            action='order_published',
            old_status=previous_status,
            new_status='publish',
            notes=f'Order published to delivery by {request.user.username}'
        )

        # Return updated row HTML for HTMX
        if request.headers.get('HX-Request'):
            return render(request, 'orders/parts/order_row.html', {'order': order})

        return JsonResponse({
            'success': True,
            'message': 'Order published to delivery successfully',
            'order_id': order.id,
            'order_status': order.order_status
        })
    except Exception as e:
        logger.exception("Error publishing order %s: %s", order_id, str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while publishing order'
        }, status=400)


@require_http_methods(["POST"])
@login_required(login_url='/accounts/login/')
@staff_required
def update_order_status(request, order_id):
    """AJAX endpoint to update order status"""
    # Valid status values for validation
    VALID_ORDER_STATUSES = [
        'to_review', 'to_publish', 'published', 'processing', 'ready_to_pickup',
        'in_transit', 'delivered', 'failed', 'cancelled', 'returned', 'reported'
    ]
    VALID_TASK_STATUSES = [
        'pending', 'dl_task_listed', 'assigned', 'in_progress', 'completed',
        'failed', 'cancelled'
    ]

    try:
        order = get_object_or_404(
            orders_models.Order.objects.select_related('business'),
            id=order_id
        )

        # Parse JSON body
        data = json.loads(request.body)
        status = data.get('status')
        status_type = data.get('status_type', 'order')  # 'order' or 'task'

        if not status:
            return JsonResponse({
                'success': False,
                'error': 'Status is required'
            }, status=400)

        # Validate status_type
        if status_type not in ('order', 'task'):
            return JsonResponse({
                'success': False,
                'error': 'Invalid status_type. Must be "order" or "task"'
            }, status=400)

        # Validate status against allowed values
        if status_type == 'task' and status not in VALID_TASK_STATUSES:
            return JsonResponse({
                'success': False,
                'error': f'Invalid task status: {status}'
            }, status=400)
        elif status_type == 'order' and status not in VALID_ORDER_STATUSES:
            return JsonResponse({
                'success': False,
                'error': f'Invalid order status: {status}'
            }, status=400)

        old_status = order.order_status if status_type == 'order' else order.task_status

        # Update appropriate status field
        if status_type == 'task':
            order.task_status = status
        else:
            order.order_status = status
        order.save()

        # Log the status update
        from orders.models import OrderVerificationLog
        OrderVerificationLog.objects.create(
            order=order,
            verified_by=request.user,
            action=f'{status_type}_status_updated',
            notes=f'{status_type.title()} status changed from {old_status} to {status} by {request.user.username}',
        )

        return JsonResponse({
            'success': True,
            'message': f'Status updated to {status} successfully',
            'order_id': order.id,
            'new_status': status
        })
    except Exception as e:
        logger.exception("Error updating status for order %s: %s", order_id, str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while updating order status'
        }, status=400)


@login_required(login_url='/accounts/login/')
@staff_required
@require_http_methods(["POST"])
def bulk_update_order_status(request):
    """Bulk update order status for multiple orders"""
    VALID_ORDER_STATUSES = [
        'to_review', 'to_publish', 'publish', 'published', 'processing', 'ready_to_pickup',
        'in_transit', 'delivered', 'failed', 'cancelled', 'returned', 'reported'
    ]
    try:
        data = json.loads(request.body)
        order_ids = data.get('order_ids', [])
        status = data.get('status')

        if not order_ids:
            return JsonResponse({
                'success': False,
                'error': 'No orders selected'
            }, status=400)

        if not status:
            return JsonResponse({
                'success': False,
                'error': 'Status is required'
            }, status=400)

        if status not in VALID_ORDER_STATUSES:
            return JsonResponse({
                'success': False,
                'error': f'Invalid status: {status}'
            }, status=400)

        from orders.models import OrderVerificationLog
        from orders.signals import _create_delivery_task_from_order

        orders = orders_models.Order.objects.filter(id__in=order_ids)
        updated = 0
        tasks_created = 0
        for order in orders:
            old_status = order.order_status
            if old_status != status:
                order.order_status = status
                order.save(update_fields=['order_status'])
                OrderVerificationLog.objects.create(
                    order=order,
                    verified_by=request.user,
                    action='order_status_updated',
                    notes=f'Bulk status change from {old_status} to {status} by {request.user.username}',
                )
                updated += 1

            # Explicitly create delivery task for publish — signal may not fire
            # when order was already in publish state or update_fields skips it
            if status == 'publish' and not order.task_created:
                order.refresh_from_db()
                if not order.task_created:
                    task = _create_delivery_task_from_order(order)
                    if task:
                        tasks_created += 1

        return JsonResponse({
            'success': True,
            'message': f'{updated} order(s) updated to {status}' + (f', {tasks_created} task(s) created' if tasks_created else ''),
            'updated_count': updated,
            'tasks_created': tasks_created,
        })
    except Exception as e:
        logger.exception("Error in bulk order status update: %s", str(e))
        return JsonResponse({
            'success': False,
            'error': 'An error occurred while updating orders'
        }, status=400)


