@login_required(login_url='/accounts/login/')
@staff_required
@require_http_methods(["GET", "POST"])
def fleet_transactions(request):
    """View for fleet transactions with filtering and sorting"""
    from django.db.models import Sum, Value, CharField
    from django.db.models.functions import Coalesce, NullIf
    from decimal import Decimal
    from datetime import timedelta
    from fleet.wallet_service import WalletService

    # Handle POST requests for approve/reject actions
    if request.method == 'POST':
        import json
        try:
            data = json.loads(request.body)
            action = data.get('action')
            txn_id = data.get('txn_id')

            if not txn_id:
                return JsonResponse({'success': False, 'error': 'Missing transaction ID'})

            txn = fleet_models.DriverTransaction.objects.get(id=txn_id)

            if action == 'approve_cod':
                txn.is_verified = True
                txn.save(update_fields=['is_verified'])
                return JsonResponse({'success': True, 'message': 'COD submission approved'})

            elif action == 'reject_cod':
                reason = data.get('reason', 'No reason provided')
                # Mark as not verified and potentially add a note
                txn.is_verified = False
                txn.save(update_fields=['is_verified'])
                logger.info(f"COD submission {txn.id} rejected by {request.user}. Reason: {reason}")
                return JsonResponse({'success': True, 'message': 'COD submission rejected'})

            return JsonResponse({'success': False, 'error': 'Invalid action'})
        except fleet_models.DriverTransaction.DoesNotExist:
            return JsonResponse({'success': False, 'error': 'Transaction not found'})
        except Exception as e:
            logger.error(f"Error processing COD action: {str(e)}")
            return JsonResponse({'success': False, 'error': str(e)})

    # Active drivers only — the people actually on the fleet.
    #
    # `driver_status='approved'` alone was too narrow: only 3 of 132 drivers are
    # approved, so the picker could not reach the driver whose ledger was open.
    # Every driver was too wide: 120 of the 132 are unfinished applications from
    # the public sign-up form, which have no ledger and never will.
    #
    # Active = approved only. `processing` is still an application in progress,
    # not a driver on the road, so it does not belong in a ledger picker.
    #
    # Two exceptions keep the picker honest rather than merely short: anyone who
    # has a ledger stays reachable however they are flagged now — a blocked
    # driver still holding COD is exactly who this screen exists to chase — and
    # so does whoever is open on screen, so the picker can always show its own
    # selection.
    from django.db.models import Case, When, IntegerField, Q
    requested_driver_id = (request.GET.get('driver_id') or '').strip()

    active_drivers = Q(driver_status='approved') | Q(transactions__isnull=False)
    if requested_driver_id.isdigit():
        active_drivers |= Q(driver_id=int(requested_driver_id))

    all_drivers = fleet_models.Driver.objects.select_related('user').filter(
        active_drivers
    ).annotate(
        status_rank=Case(
            When(driver_status='approved', then=0),
            default=1,
            output_field=IntegerField(),
        )
    ).distinct().order_by('status_rank', 'user__first_name', 'driver_id')

    # Get selected driver
    driver_id = request.GET.get('driver_id')
    selected_driver = None
    transactions = fleet_models.DriverTransaction.objects.none()

    if driver_id:
        try:
            selected_driver = fleet_models.Driver.objects.select_related('user').get(driver_id=driver_id)
            transactions = fleet_models.DriverTransaction.objects.filter(
                driver=selected_driver
            ).select_related('delivery_task', 'delivery_task__cod_submission_txn', 'settlement')
        except fleet_models.Driver.DoesNotExist:
            selected_driver = None

    # Date preset filter
    date_preset = request.GET.get('date_preset', '')
    date_from = request.GET.get('date_from', '')
    date_to = request.GET.get('date_to', '')

    today = timezone.now().date()

    # Calculate dates based on preset
    if date_preset == 'today':
        date_from = today.isoformat()
        date_to = today.isoformat()
    elif date_preset == 'yesterday':
        yesterday = today - timedelta(days=1)
        date_from = yesterday.isoformat()
        date_to = yesterday.isoformat()
    elif date_preset == '3days':
        date_from = (today - timedelta(days=3)).isoformat()
        date_to = today.isoformat()
    elif date_preset == '1week':
        date_from = (today - timedelta(days=7)).isoformat()
        date_to = today.isoformat()
    elif date_preset == '1month':
        date_from = (today - timedelta(days=30)).isoformat()
        date_to = today.isoformat()
    # For 'custom', use the date_from and date_to from request

    # Get transaction type filter (empty string = all types)
    txn_type = request.GET.get('type', '')
    status = request.GET.get('status', '')
    min_amount = request.GET.get('min_amount', '')
    max_amount = request.GET.get('max_amount', '')
    business_filter = request.GET.get('business', '')
    payment_method_filter = request.GET.get('payment_method', '')
    task_search = request.GET.get('task_search', '').strip()

    def _apply_txn_filters(qs):
        """Apply every user-selected filter; called after the view tab picks its base set."""
        if date_from:
            qs = qs.filter(created_at__date__gte=date_from)
        if date_to:
            qs = qs.filter(created_at__date__lte=date_to)
        if txn_type == 'cod_driver_settle':
            # Include legacy cod_deposit too
            qs = qs.filter(transaction_type__in=['cod_driver_settle', 'cod_deposit'])
        elif txn_type == 'cod_collection':
            qs = qs.filter(transaction_type='cod_collection')
        elif txn_type:
            qs = qs.filter(transaction_type=txn_type)
        if status == 'settled':
            qs = qs.filter(settlement__isnull=False)
        elif status == 'pending':
            qs = qs.filter(settlement__isnull=True)
        if min_amount:
            qs = qs.filter(amount__gte=min_amount)
        if max_amount:
            qs = qs.filter(amount__lte=max_amount)
        if business_filter:
            qs = qs.filter(
                Q(business_id=business_filter) |
                Q(delivery_task__business_id=business_filter) |
                Q(delivery_task__order__business_id=business_filter)
            )
        if payment_method_filter:
            qs = qs.filter(
                Q(payment_method=payment_method_filter) |
                Q(delivery_task__payment_method=payment_method_filter)
            )
        if task_search:
            qs = qs.filter(
                Q(delivery_task__dl_task_number__icontains=task_search) |
                Q(reference_number__icontains=task_search)
            )
        return qs

    # Sorting
    sort_by = request.GET.get('sort', 'date_desc')
    sort_options = {
        'date_asc': 'created_at',
        'date_desc': '-created_at',
        'amount_asc': 'amount',
        'amount_desc': '-amount',
        'type_asc': 'transaction_type',
        'type_desc': '-transaction_type',
    }
    # Transaction type choices for filter dropdown
    transaction_types = fleet_models.DriverTransaction.TRANSACTION_TYPES

    # Calculate totals (on unfiltered queryset for selected driver)
    total_cod = Decimal('0.00')
    total_earnings = Decimal('0.00')
    cod_unsettled = Decimal('0.00')
    earnings_unsettled = Decimal('0.00')
    cod_unsettled_breakdown = []
    cod_in_hand_breakdown = []
    current_cod_by_method = {}
    deposited_refs = set()
    view_type = 'cod'

    if selected_driver:
        from delivery import models as delivery_models

        # Real COD from DeliveryTask (source of truth)
        dl_tasks = delivery_models.DeliveryTask.objects.filter(driver=selected_driver)
        total_cod = dl_tasks.filter(
            cod_collected=True
        ).aggregate(total=Sum('cod_collected_amount'))['total'] or Decimal('0.00')
        cod_unsettled_qs = dl_tasks.filter(
            cod_collected=True, cod_settled=False
        )

        # Current COD in hand breakdown (all unsettled, no date filter)
        cod_in_hand_breakdown = (
            cod_unsettled_qs
            .values('payment_method')
            .annotate(total=Sum('cod_collected_amount'))
            .order_by('-total')
        )

        # Convert to dict for template access with defaults for all methods
        current_cod_by_method = {
            'cash': Decimal('0'),
            'pos': Decimal('0'),
            'fawran': Decimal('0'),
            'bank': Decimal('0'),
            'atm': Decimal('0'),
            'unknown': Decimal('0'),
        }
        for row in cod_in_hand_breakdown:
            method = row['payment_method'] or 'unknown'
            current_cod_by_method[method] = row['total']

        # Apply date filters to COD breakdown queryset for filtered view
        if date_from:
            cod_unsettled_qs = cod_unsettled_qs.filter(completed_at__date__gte=date_from)
        if date_to:
            cod_unsettled_qs = cod_unsettled_qs.filter(completed_at__date__lte=date_to)

        cod_unsettled = cod_unsettled_qs.aggregate(total=Sum('cod_collected_amount'))['total'] or Decimal('0.00')

        # Breakdown of unsettled COD by payment method (filtered by date)
        cod_unsettled_breakdown = (
            cod_unsettled_qs
            .values('payment_method')
            .annotate(total=Sum('cod_collected_amount'))
            .order_by('-total')
        )

        # Get all transactions for earnings totals and deposit refs
        all_txns = fleet_models.DriverTransaction.objects.filter(driver=selected_driver)

        # Fetch all COD deposit reference numbers in one query to avoid N+1
        deposited_refs = set(
            all_txns.filter(transaction_type='cod_deposit').values_list('reference_number', flat=True)
        )

        for txn in all_txns:
            if txn.transaction_type == 'earning':
                total_earnings += txn.amount
                # Earnings not yet settled
                if not txn.settlement_id:
                    earnings_unsettled += txn.amount

        # Recalculate COD balances once per day per driver (first page load triggers it)
        from django.core.cache import cache
        from fleet.wallet_service import WalletService
        cache_key = f"cod_bal_recalc_{driver_id}_{timezone.now().date()}"
        if not cache.get(cache_key):
            WalletService.recalculate_cod_balances(selected_driver)
            cache.set(cache_key, True, timeout=86400)  # 24 hours

        # Get tab view type (cod, cod_submit, earnings, or settled)
        view_type = request.GET.get('view', 'cod')

        # Filter transactions based on selected view
        if view_type == 'earnings':
            transactions = all_txns.filter(transaction_type__in=['earning', 'settlement'])
        elif view_type == 'cod_submit':
            transactions = all_txns.filter(transaction_type='cod_driver_settle')
        else:
            transactions = all_txns.filter(transaction_type__in=['cod_collection', 'cod_driver_settle', 'cod_deposit'])
            view_type = 'cod'

        # Re-apply ALL user filters after the view_type reassignment (previously only
        # business/payment/search survived — date, type, status, amount were dropped)
        transactions = _apply_txn_filters(transactions).select_related(
            'delivery_task', 'delivery_task__cod_submission_txn', 'settlement'
        )

        # Apply sort after view_type filter
        transactions = transactions.order_by(sort_options.get(sort_by, '-created_at'))
    else:
        view_type = 'cod'

    # Build filter params for pagination (page and per_page are set by the
    # pagination component itself, so they are stripped here).
    # `view` is deliberately KEPT: the shared brand pagination only re-appends
    # filter_params, so dropping it would bounce staff back to the default COD
    # tab on every page change.
    filter_params = request.GET.copy()
    if 'page' in filter_params:
        del filter_params['page']
    if 'per_page' in filter_params:
        del filter_params['per_page']

    # CSV export — stream the full filtered queryset (not paginated)
    if request.GET.get('export') == 'csv':
        driver_tag = selected_driver.driver_id if selected_driver else 'all'
        return csv_columns_response(
            request, transactions, FLEET_TXN_EXPORT_COLUMNS,
            f'driver_transactions_{driver_tag}_{view_type}', limit=50000)

    transactions_paginated = paginate_queryset(request, transactions, items_per_page=50)

    # Per-method breakdown for the settlement rows on this page. One query for
    # the whole page rather than three aggregates per row, and split-aware:
    # a task's payment_method is only its dominant method, so a mixed
    # collection has to be read off payment_split instead.
    if selected_driver and transactions_paginated:
        deposit_txns = [t for t in transactions_paginated
                        if t.transaction_type in ['cod_deposit', 'cod_driver_settle']]
        if deposit_txns:
            splits = {t.id: {'cash': Decimal('0'), 'pos': Decimal('0'),
                             'fawran': Decimal('0'), 'total': Decimal('0')}
                      for t in deposit_txns}
            rows = delivery_models.DeliveryTask.objects.filter(
                cod_submission_txn_id__in=list(splits), cod_collected=True,
            ).values_list('cod_submission_txn_id', 'payment_method',
                          'payment_split', 'cod_collected_amount')
            for txn_id, method, split, amount in rows:
                bucket = splits[txn_id]
                cash_leg = WalletService.split_cash_leg(split)
                if cash_leg is not None:
                    bucket['cash'] += cash_leg
                    bucket['pos'] += Decimal(str(split.get('pos') or 0))
                    bucket['fawran'] += Decimal(str(split.get('fawran') or 0))
                elif method in ('cash', 'pos', 'fawran'):
                    bucket[method] += amount or Decimal('0')
                else:
                    bucket['cash'] += amount or Decimal('0')
            for txn in deposit_txns:
                bucket = splits[txn.id]
                # Precomputed so the template never chains the `add` filter,
                # which truncates decimals via int().
                bucket['total'] = bucket['cash'] + bucket['pos'] + bucket['fawran']
                txn.settlement_split = bucket

    # Payment method breakdown for filtered transactions. Falls back to the
    # task's method because ~18% of collection rows carry a null
    # payment_method and would otherwise land in an unlabelled bucket.
    payment_method_breakdown = (
        transactions
        .annotate(method=Coalesce(
            NullIf('delivery_task__payment_method', Value('')),
            'payment_method', Value('cash'),
            output_field=CharField(),
        ))
        .values('method')
        .annotate(total=Sum('amount'))
        .order_by('-total')
    ) if selected_driver else []

    # Businesses associated with this driver's transactions (for filter dropdown)
    driver_businesses = []
    if selected_driver:
        driver_businesses = business_models.Business.objects.filter(
            Q(transactions__driver=selected_driver) |
            Q(deliverytask__driver=selected_driver)
        ).distinct().order_by('business_name')

    # Payment method choices for filter dropdown
    payment_method_choices = [
        ('cash', 'Cash'),
        ('fawran', 'Fawran'),
        ('pos', 'POS'),
        ('bank', 'Bank'),
        ('atm', 'ATM'),
    ]

    # When task_search is active, surface delivery tasks that match but have
    # no transaction in the current view (e.g. delivered without COD, or no
    # earning entry yet). These are tasks the user is hunting for that don't
    # show up in the transactions table because no DriverTransaction exists.
    unmatched_tasks = []
    if task_search and selected_driver:
        from delivery import models as delivery_models
        matched_task_ids = set(
            transactions.exclude(delivery_task__isnull=True)
            .values_list('delivery_task_id', flat=True)
        )
        unmatched_tasks = (
            delivery_models.DeliveryTask.objects.filter(
                driver=selected_driver,
                dl_task_number__icontains=task_search,
            )
            .exclude(id__in=matched_task_ids)
            .select_related('order', 'business')
            .order_by('-completed_at', '-id')[:50]
        )

    # Zero-COD (prepaid) deliveries for this driver — these never create a
    # DriverTransaction (no COD collected), so they are invisible in the COD tab.
    # Surface them as their own list so staff see the full delivery manifest,
    # mirroring the driver app's COD list. They carry no cash, so totals are
    # unaffected.
    zero_cod_tasks = []
    if selected_driver and view_type == 'cod' and not task_search:
        zct_qs = delivery_models.DeliveryTask.objects.filter(
            driver=selected_driver,
            order__cod_amount=0,
            cod_collected=False,
            dl_task_status__in=['delivered', 'partial_delivery'],
        ).select_related('order', 'business', 'order__business')
        if date_from:
            zct_qs = zct_qs.filter(completed_at__date__gte=date_from)
        if date_to:
            zct_qs = zct_qs.filter(completed_at__date__lte=date_to)
        if business_filter:
            zct_qs = zct_qs.filter(
                Q(business_id=business_filter) | Q(order__business_id=business_filter)
            )
        zero_cod_tasks = list(zct_qs.order_by('-completed_at', '-id')[:100])

    context = {
        'page_title': 'Fleet Transactions',
        'transactions': transactions_paginated,
        'zero_cod_tasks': zero_cod_tasks,
        'all_drivers': all_drivers,
        'selected_driver': selected_driver,
        'total_cod': total_cod,
        'total_earnings': total_earnings,
        'cod_unsettled': cod_unsettled,
        'earnings_unsettled': earnings_unsettled,
        'cod_unsettled_breakdown': cod_unsettled_breakdown,
        'cod_in_hand_breakdown': cod_in_hand_breakdown,
        'current_cod_by_method': current_cod_by_method,
        'deposited_refs': deposited_refs,
        'electronic_methods': WalletService.ELECTRONIC_METHODS,
        'filter_params': filter_params.urlencode(),
        'per_page': get_per_page(request, default=50),
        # Filter values for form
        'date_preset': date_preset,
        'date_from': date_from or '',
        'date_to': date_to or '',
        'txn_type': txn_type or '',
        'status': status or '',
        'min_amount': min_amount or '',
        'max_amount': max_amount or '',
        'business_filter': business_filter or '',
        'payment_method_filter': payment_method_filter or '',
        'task_search': task_search or '',
        'sort_by': sort_by,
        'transaction_types': transaction_types,
        'payment_method_breakdown': payment_method_breakdown,
        'view_type': view_type,
        'driver_businesses': driver_businesses,
        'payment_method_choices': payment_method_choices,
        'unmatched_tasks': unmatched_tasks,
        # Lets the empty state tell the difference between "this driver has
        # nothing" and "this tab/filter matched nothing" — the tabs filter by
        # transaction type, so a driver with 23 rows can still show an empty
        # COD-submit tab and the old copy called that "no transactions yet".
        'driver_txn_total': (
            fleet_models.DriverTransaction.objects.filter(driver=selected_driver).count()
            if selected_driver else 0
        ),
        **export_columns_context(FLEET_TXN_EXPORT_COLUMNS, storage_key='wf_fleet_txn_export_cols',
                                 url=request.path + '?export=csv'),
    }
    return render(request, 'workforce/fleet_transactions.html', context)


def _format_pickup_location(pickup_location):
    """Build a human-readable 'from' address string from a PickupLocation."""
    if not pickup_location:
        return '-'
    parts = [pickup_location.pickup_location_title or '']
    detail = []
    if pickup_location.pickup_zone_no:
        detail.append(f"Zone {pickup_location.pickup_zone_no}")
    if pickup_location.pickup_street_no:
        detail.append(f"St {pickup_location.pickup_street_no}")
    if pickup_location.pickup_building_no:
        detail.append(f"Bldg {pickup_location.pickup_building_no}")
    if pickup_location.locality:
        detail.append(pickup_location.locality)
    if detail:
        parts.append(", ".join(detail))
    return " — ".join(p for p in parts if p) or '-'


_SELLER_EXPORT_HEADERS = ['Order Code', 'Client Code', 'Order Date', 'Customer',
                          'From / To Location', 'COD Amount (QAR)', 'Status', 'Order Status']
_SELLER_COD_STATUS_LABELS = {
    'cod_settled_with_business': 'Settled',
    'fully_paid': 'Collected',
    'cod_with_ezzy': 'With Ezzy',
    'cod_with_driver': 'With Driver',
}


def _seller_transactions_export_rows(orders):
    """Shared row data for the CSV and XLSX exports.

    'From / To Location' is a single value with two lines:
    line 1 = pickup (from) location, line 2 = delivery (to) address.
    """
    rows = []
    for order in orders:
        from_loc = _format_pickup_location(order.pickup_location)
        to_loc = order.customer_address or '-'
        rows.append([
            order.order_number or '-',
            order.client_order_code or '-',
            order.order_date.strftime('%d %b %Y') if order.order_date else '-',
            order.customer_name or '-',
            f"From: {from_loc}\nTo: {to_loc}",
            float(order.cod_amount or 0),
            _SELLER_COD_STATUS_LABELS.get(order.cod_status_by_staff, 'Pending'),
            (order.order_status or '').replace('_', ' ').title() or '-',
        ])
    return rows


SELLER_TXN_EXPORT_COLUMNS = [
    ('order_code',   'Order Code',          lambda o: o.order_number or '-'),
    ('client_code',  'Client Code',         lambda o: o.client_order_code or '-'),
    ('order_date',   'Order Date',          lambda o: o.order_date.strftime('%d %b %Y') if o.order_date else '-'),
    ('customer',     'Customer',            lambda o: o.customer_name or '-'),
    ('from_to',      'From / To Location',  lambda o: f"From: {_format_pickup_location(o.pickup_location)}\nTo: {o.customer_address or '-'}"),
    ('cod_amount',   'COD Amount (QAR)',    lambda o: float(o.cod_amount or 0)),
    ('status',       'Status',              lambda o: _SELLER_COD_STATUS_LABELS.get(o.cod_status_by_staff, 'Pending')),
    ('order_status', 'Order Status',        lambda o: (o.order_status or '').replace('_', ' ').title() or '-'),
]


def _seller_transactions_csv(orders, selected_seller):
    """Generate a .csv export of seller COD transactions (all filtered rows)."""
    import csv

    filename = "seller_cod_transactions_%s_%s.csv" % (
        selected_seller.business_id, timezone.now().strftime('%Y-%m-%d'))
    response = HttpResponse(content_type='text/csv; charset=utf-8')
    response['Content-Disposition'] = 'attachment; filename="%s"' % filename
    response.write('﻿')  # BOM so Excel opens UTF-8 correctly
    writer = csv.writer(response)
    writer.writerow(_SELLER_EXPORT_HEADERS)
    for row in _seller_transactions_export_rows(orders):
        writer.writerow(row)
    return response


def _seller_transactions_xlsx(orders, selected_seller):
    """Generate an .xlsx export of seller COD transactions.

    The 'From / To Location' is a single column with two lines per cell:
    line 1 = pickup (from) location, line 2 = delivery (to) address.
    """
    import openpyxl
    from openpyxl.styles import Font, Alignment, PatternFill
    from openpyxl.utils import get_column_letter

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'Seller Transactions'

    ws.append(_SELLER_EXPORT_HEADERS)

    header_fill = PatternFill(start_color='1F2A44', end_color='1F2A44', fill_type='solid')
    header_font = Font(bold=True, color='FFFFFF')
    for col_idx in range(1, len(_SELLER_EXPORT_HEADERS) + 1):
        cell = ws.cell(row=1, column=col_idx)
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = Alignment(vertical='center', horizontal='left')

    wrap = Alignment(wrap_text=True, vertical='top')
    for row in _seller_transactions_export_rows(orders):
        ws.append(row)
        row_idx = ws.max_row
        ws.cell(row=row_idx, column=5).alignment = wrap
        ws.cell(row=row_idx, column=6).number_format = '#,##0.00'

    # Column widths
    widths = [16, 14, 14, 22, 48, 16, 14, 16]
    for i, width in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = width
    ws.freeze_panes = 'A2'

    filename = "seller_cod_transactions_%s_%s.xlsx" % (
        selected_seller.business_id, timezone.now().strftime('%Y-%m-%d'))
    response = HttpResponse(
        content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    response['Content-Disposition'] = 'attachment; filename="%s"' % filename
    wb.save(response)
    return response


@login_required(login_url='/accounts/login/')
@staff_required
def seller_transactions(request):
    """View for seller COD transactions tracking and settlement"""
    from django.db.models import Sum, Q, Count
    from decimal import Decimal
    from datetime import timedelta

    # Get all active sellers/businesses
    all_sellers = business_models.Business.objects.filter(
        business_status='active'
    ).select_related('user').order_by('business_name')


    # Get selected seller
    seller_id = request.GET.get('seller_id')
    selected_seller = None
    orders = Order.objects.none()

    if seller_id:
        try:
            selected_seller = business_models.Business.objects.select_related('user').get(business_id=seller_id)
            # Show ALL of the seller's transactions — including zero-COD orders and
            # undelivered ones. The COD *totals* below are still computed only from
            # delivered / partial-delivery orders so undelivered orders never inflate them.
            orders = Order.objects.filter(
                business=selected_seller,
            ).select_related('business', 'pickup_location').distinct()
        except business_models.Business.DoesNotExist:
            selected_seller = None

    # Roster figures for the landing state. The page used to open on a bare
    # dropdown, which told staff nothing — they had to select accounts one at
    # a time to find out who was owed money. Each active seller now gets a
    # card carrying its COD position, ordered so the largest balance leads.
    #
    # Two grouped queries, never one per seller: the COD legs come from
    # DeliveryTask (the money truth) and the order counts from Order.
    seller_roster = []
    if not selected_seller:
        # NB: no `from delivery import models as delivery_models` here — a local
        # import inside this branch would make the name local to the *whole*
        # function and shadow the module-level import that the selected-seller
        # path below relies on.
        from django.db.models import Case, When, Value, DecimalField, IntegerField, Max

        def leg(**conditions):
            return Sum(
                Case(
                    When(then='cod_collected_amount', **conditions),
                    default=Value(0),
                    output_field=DecimalField(max_digits=12, decimal_places=2),
                )
            )

        cod_rows = {
            row['order__business_id']: row
            for row in delivery_models.DeliveryTask.objects.filter(
                order__business__business_status='active',
                cod_collected=True,
            ).values('order__business_id').annotate(
                with_driver=leg(cod_settled=False),
                owed=leg(cod_settled=True, cod_client_settled=False),
                paid_out=leg(cod_client_settled=True),
            )
        }

        order_rows = {
            row['business_id']: row
            for row in Order.objects.filter(
                business__business_status='active'
            ).values('business_id').annotate(
                order_count=Count('id', output_field=IntegerField()),
                last_order=Max('order_date'),
            )
        }

        zero = Decimal('0.00')
        for biz in all_sellers:
            cod = cod_rows.get(biz.business_id, {})
            orders_row = order_rows.get(biz.business_id, {})
            owed = cod.get('owed') or zero
            with_driver = cod.get('with_driver') or zero
            paid_out = cod.get('paid_out') or zero
            total = owed + with_driver + paid_out
            seller_roster.append({
                'business': biz,
                'owed': owed,
                'with_driver': with_driver,
                'paid_out': paid_out,
                'order_count': orders_row.get('order_count') or 0,
                'last_order': orders_row.get('last_order'),
                # Rail proportions, precomputed so the template stays markup.
                'pct_driver': float(with_driver / total * 100) if total else 0,
                'pct_owed': float(owed / total * 100) if total else 0,
                'pct_paid': float(paid_out / total * 100) if total else 0,
            })
        # Money first: the accounts with an outstanding balance are the ones
        # staff came here to act on.
        seller_roster.sort(key=lambda r: (-r['owed'], -r['with_driver'],
                                          r['business'].business_name or ''))

    # Date filters
    date_preset = request.GET.get('date_preset', '')
    date_from = request.GET.get('date_from', '')
    date_to = request.GET.get('date_to', '')

    today = timezone.now().date()

    # Calculate dates based on preset
    if date_preset == 'today':
        date_from = today.isoformat()
        date_to = today.isoformat()
    elif date_preset == 'yesterday':
        yesterday = today - timedelta(days=1)
        date_from = yesterday.isoformat()
        date_to = yesterday.isoformat()
    elif date_preset == '3days':
        date_from = (today - timedelta(days=3)).isoformat()
        date_to = today.isoformat()
    elif date_preset == '1week':
        date_from = (today - timedelta(days=7)).isoformat()
        date_to = today.isoformat()
    elif date_preset == '1month':
        date_from = (today - timedelta(days=30)).isoformat()
        date_to = today.isoformat()

    # Filter status
    status = request.GET.get('status', '')
    task_statuses = request.GET.getlist('task_status')  # multi-select delivery task status
    min_amount = request.GET.get('min_amount', '')
    max_amount = request.GET.get('max_amount', '')

    total_cod = Decimal('0.00')
    cod_unsettled = Decimal('0.00')

    if selected_seller:
        # Get COD orders from selected seller
        if status == 'settled':
            orders = orders.filter(Q(cod_status_by_staff='cod_settled_with_business') | Q(fulfilled_at__isnull=False))
        elif status == 'pending':
            orders = orders.filter(cod_status_by_staff__in=['not_collected', 'partially_collected', 'fully_paid', 'cod_with_driver', 'cod_with_ezzy'])

        # Delivery task status (multi-select)
        if task_statuses:
            orders = orders.filter(delivery_task__dl_task_status__in=task_statuses).distinct()

        # Date filters
        if date_from:
            orders = orders.filter(order_date__gte=date_from)
        if date_to:
            orders = orders.filter(order_date__lte=date_to)

        # Amount filters
        if min_amount:
            orders = orders.filter(cod_amount__gte=min_amount)
        if max_amount:
            orders = orders.filter(cod_amount__lte=max_amount)

        # Calculate totals — only delivered / partial-delivery orders carry settleable
        # COD (cash was actually collected), so undelivered orders never inflate them.
        settleable = orders.filter(
            delivery_task__dl_task_status__in=['delivered', 'partial_delivery'],
        )
        total_cod = settleable.filter(
            cod_amount__gt=0
        ).aggregate(total=Sum('cod_amount'))['total'] or Decimal('0.00')

        cod_unsettled = settleable.filter(
            cod_amount__gt=0,
            cod_status_by_staff__in=['pending', 'to_review', 'accepted']
        ).aggregate(total=Sum('cod_amount'))['total'] or Decimal('0.00')

    # Sorting
    sort_by = request.GET.get('sort', 'date_desc')
    sort_options = {
        'date_asc': 'order_date',
        'date_desc': '-order_date',
        'amount_asc': 'cod_amount',
        'amount_desc': '-cod_amount',
        'status_asc': 'cod_status_by_staff',
        'status_desc': '-cod_status_by_staff',
    }
    orders = orders.order_by(sort_options.get(sort_by, '-order_date'))

    # Export — returns ALL filtered orders (not just the current page)
    export_fmt = request.GET.get('export')
    if selected_seller and export_fmt in ('xlsx', 'csv'):
        if export_fmt == 'csv':
            return csv_columns_response(
                request, orders, SELLER_TXN_EXPORT_COLUMNS,
                f'seller_cod_transactions_{selected_seller.business_id}', limit=50000)
        return _seller_transactions_xlsx(orders, selected_seller)

    # Build filter params for pagination
    filter_params = request.GET.copy()
    if 'page' in filter_params:
        del filter_params['page']
    if 'per_page' in filter_params:
        del filter_params['per_page']

    orders_paginated = paginate_queryset(request, orders, items_per_page=50)

    context = {
        'page_title': 'Seller Transactions',
        'all_sellers': all_sellers,
        'seller_roster': seller_roster,
        'selected_seller': selected_seller,
        'orders': orders_paginated,
        'total_cod': total_cod,
        'cod_unsettled': cod_unsettled,
        'filter_params': filter_params.urlencode(),
        'per_page': get_per_page(request, default=50),
        # Filter values for form
        'date_preset': date_preset,
        'date_from': date_from or '',
        'date_to': date_to or '',
        'status': status or '',
        'task_status_choices': delivery_models.DeliveryTask.DL_TASK_STATUS_CHOICES,
        'selected_task_statuses': task_statuses,
        'min_amount': min_amount or '',
        'max_amount': max_amount or '',
        'sort_by': sort_by,
        **export_columns_context(SELLER_TXN_EXPORT_COLUMNS, storage_key='wf_seller_txn_export_cols',
                                 url=request.path + '?export=csv'),
    }
    return render(request, 'workforce/seller_transactions.html', context)


@login_required(login_url='/accounts/login/')
@staff_required
def fleet_transaction_cod_details(request, txn_id):
    """AJAX: Return list of delivery tasks for a COD submission transaction"""
    from datetime import timedelta
    from delivery import models as delivery_models

    try:
        txn = fleet_models.DriverTransaction.objects.select_related('driver', 'driver__user').get(
            id=txn_id
        )
    except fleet_models.DriverTransaction.DoesNotExist:
        return JsonResponse({'error': 'Transaction not found'}, status=404)

    tasks = []
    if txn.transaction_type in ['cod_deposit', 'cod_driver_settle']:
        window = timedelta(seconds=10)
        settled_tasks = delivery_models.DeliveryTask.objects.filter(
            driver=txn.driver,
            cod_collected=True,
            cod_settled=True,
            cod_settled_at__gte=txn.created_at - window,
            cod_settled_at__lte=txn.created_at + window,
        ).select_related('order', 'order__business', 'dl_to_address').order_by('-completed_at')

        for d in settled_tasks:
            tasks.append({
                'task_id': d.id,
                'task_number': d.dl_task_number or '-',
                'order_code': d.order.client_order_code if d.order else '-',
                'business': d.order.business.business_name if d.order and d.order.business else '-',
                'customer': d.order.customer_name if d.order else '-',
                'location': d.dl_to_address.area_name if d.dl_to_address else '-',
                'delivered_at': d.completed_at.strftime('%d %b %Y, %H:%M') if d.completed_at else '-',
                'amount': float(d.cod_collected_amount or 0),
                'cod_settled': d.cod_settled,
            })
    elif txn.transaction_type == 'cod_collection' and txn.delivery_task:
        d = txn.delivery_task
        tasks.append({
            'task_id': d.id,
            'task_number': d.dl_task_number or '-',
            'order_code': d.order.client_order_code if d.order else '-',
            'business': d.order.business.business_name if d.order and d.order.business else '-',
            'customer': d.order.customer_name if d.order else '-',
            'location': d.dl_to_address.area_name if d.dl_to_address else '-',
            'delivered_at': d.completed_at.strftime('%d %b %Y, %H:%M') if d.completed_at else '-',
            'amount': float(d.cod_collected_amount or 0),
            'cod_settled': d.cod_settled,
        })

    driver_name = '-'
    driver_code = '-'
    if txn.driver:
        driver_code = txn.driver.driver_id or '-'
        if txn.driver.user:
            driver_name = f"{txn.driver.user.first_name} {txn.driver.user.last_name}".strip() or txn.driver.user.username

    return JsonResponse({
        'txn_id': txn.id,
        'transaction_code': txn.transaction_code or '-',
        'transaction_type': txn.get_transaction_type_display(),
        'driver_name': driver_name,
        'driver_code': driver_code,
        'amount': float(txn.amount),
        'date': txn.created_at.strftime('%d %b %Y, %H:%M'),
        'payment_method': txn.get_payment_method_display() if txn.payment_method else '-',
        'notes': txn.notes or '',
        'is_received': txn.is_received,
        'is_verified': txn.is_verified,
        'tasks': tasks,
        'tasks_count': len(tasks),
        'tasks_total': sum(t['amount'] for t in tasks),
    })


@login_required(login_url='/accounts/login/')
@staff_required
def fleet_transaction_update_status(request, txn_id):
    """AJAX: Toggle is_received or is_verified on a DriverTransaction"""
    if request.method != 'POST':
        return JsonResponse({'error': 'POST required'}, status=405)

    try:
        txn = fleet_models.DriverTransaction.objects.get(id=txn_id)
    except fleet_models.DriverTransaction.DoesNotExist:
        return JsonResponse({'error': 'Transaction not found'}, status=404)

    field = request.POST.get('field')
    if field not in ('is_received', 'is_verified'):
        return JsonResponse({'error': 'Invalid field'}, status=400)

    # If explicit value passed use it, otherwise toggle
    explicit = request.POST.get('value')
    if explicit == 'true':
        new_value = True
    elif explicit == 'false':
        new_value = False
    else:
        new_value = not getattr(txn, field)

    setattr(txn, field, new_value)
    txn.save(update_fields=[field])

    return JsonResponse({'success': True, 'field': field, 'value': new_value})


@login_required(login_url='/accounts/login/')
@staff_required
def fleet_task_cod_correct(request, task_id):
    """Staff COD correction for a delivery task.

    Updates DeliveryTask.cod_collected / cod_collected_amount / payment_method
    and creates or updates the linked cod_collection DriverTransaction so the
    driver wallet stays consistent. Refused if the task's COD is already
    settled (submitted to admin) — that requires reversing the deposit first.
    """
    from decimal import Decimal, InvalidOperation
    from django.db import transaction as db_transaction
    from delivery import models as delivery_models
    from fleet.wallet_service import WalletService

    if request.method != 'POST':
        return JsonResponse({'error': 'POST required'}, status=405)

    try:
        task = delivery_models.DeliveryTask.objects.select_related(
            'driver', 'order', 'business'
        ).get(id=task_id)
    except delivery_models.DeliveryTask.DoesNotExist:
        return JsonResponse({'error': 'Delivery task not found'}, status=404)

    if not task.driver:
        return JsonResponse({'error': 'Task has no driver assigned'}, status=400)

    if task.cod_settled:
        return JsonResponse({
            'error': 'COD for this task is already settled with admin. '
                     'Reverse the COD deposit before correcting.'
        }, status=400)

    try:
        data = json.loads(request.body or '{}')
    except json.JSONDecodeError:
        data = {}

    cod_collected_raw = str(data.get('cod_collected', '')).lower()
    cod_collected = cod_collected_raw in ('true', '1', 'yes', 'on')
    payment_method = (data.get('payment_method') or '').strip().lower() or None
    reason = (data.get('reason') or '').strip()[:255]

    valid_methods = {'cash', 'pos', 'fawran', 'bank', 'atm'}
    if cod_collected and payment_method not in valid_methods:
        return JsonResponse({'error': 'Valid payment method required when COD is collected'}, status=400)

    try:
        amount = Decimal(str(data.get('amount') or '0'))
    except (InvalidOperation, ValueError):
        return JsonResponse({'error': 'Invalid amount'}, status=400)

    if amount < 0:
        return JsonResponse({'error': 'Amount cannot be negative'}, status=400)
    if cod_collected and amount <= 0:
        return JsonResponse({'error': 'Amount must be greater than 0 when COD is collected'}, status=400)

    old_collected = bool(task.cod_collected)
    old_amount = Decimal(task.cod_collected_amount or 0)
    old_method = task.payment_method or ''

    try:
        with db_transaction.atomic():
            # Update task
            task.cod_collected = cod_collected
            task.cod_collected_amount = amount if cod_collected else Decimal('0')
            task.payment_method = (payment_method or '') if cod_collected else ''
            if cod_collected and not task.cod_collected_at:
                task.cod_collected_at = timezone.now()
            if not cod_collected:
                task.cod_collected_at = None
            task.save(update_fields=[
                'cod_collected', 'cod_collected_amount', 'payment_method',
                'cod_collected_at',
            ])

            # Sync the cod_collection DriverTransaction
            existing_txn = fleet_models.DriverTransaction.objects.filter(
                delivery_task=task, transaction_type='cod_collection'
            ).first()

            audit_suffix = (
                f" — corrected by {request.user.username}: "
                f"{old_amount} {old_method or '-'} → {amount} {payment_method or '-'}"
                f"{' (' + reason + ')' if reason else ''}"
            )

            created_new_txn = False
            if cod_collected:
                if existing_txn:
                    existing_txn.amount = amount
                    existing_txn.payment_method = payment_method
                    existing_txn.description = (
                        f"COD collected for task {task.dl_task_number}{audit_suffix}"
                    )[:255]
                    existing_txn.save(update_fields=[
                        'amount', 'payment_method', 'description'
                    ])
                else:
                    created_new_txn = True
                    WalletService.record_transaction(
                        driver=task.driver,
                        transaction_type='cod_collection',
                        amount=amount,
                        description=(
                            f"COD collected for task {task.dl_task_number}{audit_suffix}"
                        )[:255],
                        delivery_task=task,
                        created_by=request.user,
                        reference_number=task.dl_task_number,
                        payment_method=payment_method,
                    )
            else:
                # Marking as not collected: delete the linked cod_collection txn
                # so balances don't include it.
                if existing_txn:
                    existing_txn.delete()

            # Sync driver.wallet_balance for the delta in cash liability.
            # Only cash cod_collection debits wallet_balance (see
            # WalletService.record_transaction); mirror that rule here so a
            # correction adjusts the wallet by exactly the change, including
            # when the payment method itself changes to/from cash.
            # When a brand-new transaction was just created above, record_transaction()
            # already applied the new-side debit internally — only the old side
            # (if any) still needs manual reversal here to avoid double-counting.
            old_wallet_hit = (
                old_amount if (old_collected and old_method not in WalletService.ELECTRONIC_METHODS)
                else Decimal('0')
            )
            new_wallet_hit = (
                amount if (cod_collected and payment_method not in WalletService.ELECTRONIC_METHODS)
                else Decimal('0')
            )
            wallet_delta = new_wallet_hit - old_wallet_hit
            if created_new_txn:
                wallet_delta -= new_wallet_hit
            if wallet_delta != 0:
                driver = fleet_models.Driver.objects.select_for_update().get(pk=task.driver_id)
                driver.wallet_balance -= wallet_delta
                driver.save(update_fields=['wallet_balance'])

            # Recalculate driver balances after the change
            WalletService.recalculate_cod_balances(task.driver)

            # cod_in_hand is a denormalization of task truth — refresh it now
            # that DeliveryTask.cod_collected_amount has changed.
            WalletService.sync_cod_in_hand(task.driver)

            # Staff-facing task timeline entry (workforce dashboard only — the
            # client order timeline templates never generically loop over
            # OrderStatusHistory, so this field_name won't surface there).
            if task.order:
                old_display = (
                    f"{old_amount} QAR ({old_method or 'unknown'})" if old_collected else 'Not collected'
                )
                new_display = (
                    f"{amount} QAR ({payment_method})" if cod_collected else 'Not collected'
                )
                orders_models.OrderStatusHistory.objects.create(
                    order=task.order,
                    field_name='cod_correction',
                    old_value=str(old_amount),
                    new_value=str(amount),
                    old_display=old_display,
                    new_display=new_display,
                    changed_by=request.user,
                    notes=reason,
                )

            logger.info(
                "COD correction by %s on task %s (id=%s): collected=%s amount %s→%s method %s→%s",
                request.user, task.dl_task_number, task.id,
                cod_collected, old_amount, amount, old_method, payment_method,
            )
    except Exception as e:
        logger.exception("COD correction failed for task %s", task_id)
        return JsonResponse({'error': str(e)}, status=500)

    return JsonResponse({
        'success': True,
        'task_id': task.id,
        'task_number': task.dl_task_number,
        'cod_collected': task.cod_collected,
        'cod_collected_amount': float(task.cod_collected_amount or 0),
        'payment_method': task.payment_method or '',
        'old': {
            'cod_collected': old_collected,
            'amount': float(old_amount),
            'payment_method': old_method,
        },
    })


@login_required(login_url='/accounts/login/')
@staff_required
def bulk_settle_transactions(request):
    """Bulk settle selected transactions for a driver"""
    from django.contrib import messages
    from decimal import Decimal
    import json

    if request.method != 'POST':
        return redirect('workforce:fleet_transactions')

    driver_id = request.POST.get('driver_id')
    transaction_ids_json = request.POST.get('transaction_ids', '[]')
    settlement_date_str = request.POST.get('settlement_date', '')

    # Parse settlement date or fall back to today
    from datetime import date as date_type, datetime as datetime_type
    try:
        settlement_date = date_type.fromisoformat(settlement_date_str) if settlement_date_str else timezone.now().date()
    except ValueError:
        settlement_date = timezone.now().date()

    try:
        transaction_ids = json.loads(transaction_ids_json)
    except json.JSONDecodeError:
        messages.error(request, 'Invalid transaction data')
        return redirect('workforce:fleet_transactions')

    if not driver_id or not transaction_ids:
        messages.error(request, 'Driver ID and transactions are required')
        return redirect('workforce:fleet_transactions')

    try:
        driver = fleet_models.Driver.objects.get(driver_id=driver_id)
    except fleet_models.Driver.DoesNotExist:
        messages.error(request, 'Driver not found')
        return redirect('workforce:fleet_transactions')

    # Get transactions that can be settled (pending earnings and COD collections)
    transactions = fleet_models.DriverTransaction.objects.filter(
        id__in=transaction_ids,
        driver=driver,
        settlement__isnull=True  # Not already settled
    ).exclude(
        transaction_type__in=['settlement', 'cod_deposit']  # These are already finalized
    )

    if not transactions.exists():
        messages.warning(request, 'No eligible transactions found for settlement')
        return redirect(f"{reverse('workforce:fleet_transactions')}?driver_id={driver_id}")

    # Calculate total settlement amount
    total_amount = sum(txn.amount for txn in transactions)

    # Wrap entire settlement operation in transaction.atomic for data consistency
    from django.db import transaction as db_transaction
    from django.db.models import F
    from django.db.models.functions import Greatest

    # Pre-calculate amounts before entering atomic block
    transaction_list = list(transactions.select_related('delivery_task'))
    earnings_settled = sum(
        (txn.amount for txn in transaction_list if txn.transaction_type == 'earning'),
        Decimal('0.00')
    )
    cod_txns = [txn for txn in transaction_list if txn.transaction_type == 'cod_collection']
    cod_settled = sum((abs(txn.amount) for txn in cod_txns), Decimal('0.00'))

    # Get delivery task IDs and dominant payment method from COD transactions
    cod_delivery_ids = [txn.delivery_task_id for txn in cod_txns if txn.delivery_task_id]
    cod_payment_method = 'cash'
    if cod_txns:
        method_totals = {}
        for txn in cod_txns:
            m = txn.payment_method or 'cash'
            method_totals[m] = method_totals.get(m, Decimal('0')) + abs(txn.amount)
        cod_payment_method = max(method_totals, key=method_totals.get)

    with db_transaction.atomic():
        first_txn = transactions.order_by('created_at').first()
        if not first_txn:
            messages.warning(request, 'Transactions were already settled by another request')
            return redirect(f"{reverse('workforce:fleet_transactions')}?driver_id={driver_id}")

        settlement_code = f"STL-{timezone.now().strftime('%Y%m%d%H%M%S')}-{driver_id}"

        settlement = fleet_models.DriverSettlement.objects.create(
            driver=driver,
            settlement_code=settlement_code,
            period_start=first_txn.created_at.date(),
            period_end=settlement_date,
            total_deliveries=len([t for t in transaction_list if t.transaction_type == 'earning']),
            gross_earnings=total_amount,
            net_amount=total_amount,
            created_by=request.user,
            status='paid',
            paid_at=timezone.make_aware(datetime_type(settlement_date.year, settlement_date.month, settlement_date.day)),
        )

        # Link original transactions to settlement record
        transactions.update(settlement=settlement)

        # Create a CODD transaction for the COD portion (visible in transactions list)
        if cod_settled > 0:
            from django.db.models import Max
            payment_method_display = {'cash': 'Cash', 'bank': 'Bank Transfer', 'atm': 'ATM', 'fawran': 'Fawran', 'pos': 'POS'}.get(cod_payment_method, 'Cash')

            # Generate transaction code using settlement_date (not today)
            date_str = settlement_date.strftime('%Y%m%d')
            code_pattern = f"CODD-{date_str}-"
            last_code = fleet_models.DriverTransaction.objects.filter(
                transaction_code__startswith=code_pattern
            ).aggregate(max_code=Max('transaction_code'))['max_code']
            seq = 1
            if last_code:
                try:
                    seq = int(last_code.split('-')[-1]) + 1
                except (ValueError, IndexError):
                    seq = 1
            codd_code = f"{code_pattern}{seq:04d}"

            codd_txn = fleet_models.DriverTransaction.objects.create(
                driver=driver,
                transaction_type='cod_deposit',
                transaction_code=codd_code,
                amount=cod_settled,
                description=f"COD deposit to admin - {cod_settled} QR via {payment_method_display}",
                payment_method=cod_payment_method,
                reference_number=settlement_code,
                created_by=request.user,
            )
            # Set created_at to the chosen settlement date (auto_now_add prevents direct assignment)
            settlement_datetime = timezone.make_aware(datetime_type(settlement_date.year, settlement_date.month, settlement_date.day))
            fleet_models.DriverTransaction.objects.filter(pk=codd_txn.pk).update(created_at=settlement_datetime)

            # Update driver wallet_balance (cod_deposit: wallet += amount)
            fleet_models.Driver.objects.filter(driver_id=driver_id).update(
                wallet_balance=F('wallet_balance') + cod_settled,
                cod_in_hand=Greatest(F('cod_in_hand') - cod_settled, Decimal('0.00'))
            )

            # Mark delivery tasks as cod_settled
            if cod_delivery_ids:
                from delivery.models import DeliveryTask
                DeliveryTask.objects.filter(id__in=cod_delivery_ids).update(
                    cod_settled=True,
                    cod_settled_at=settlement_datetime,
                    cod_submission_txn=codd_txn,
                )

        # Update earnings balance and last_settlement_date
        if earnings_settled > 0:
            fleet_models.Driver.objects.filter(driver_id=driver_id).update(
                pending_earnings=Greatest(
                    F('pending_earnings') - earnings_settled,
                    Decimal('0.00')
                )
            )
        fleet_models.Driver.objects.filter(driver_id=driver_id).update(
            last_settlement_date=timezone.now()
        )

        # Re-stamp the COD running balances so the new deposit row carries the
        # amount still in hand instead of a stale/blank balance.
        if cod_settled > 0:
            from fleet.wallet_service import WalletService
            WalletService.recalculate_cod_balances(driver)

    messages.success(
        request,
        f'Successfully settled {len(transaction_list)} transactions for QAR {total_amount:.2f}. '
        f'Settlement code: {settlement_code}'
    )
    return redirect(f"{reverse('workforce:fleet_transactions')}?driver_id={driver_id}")


@login_required(login_url='/accounts/login/')
@staff_required
@require_POST
def recalculate_cod_balances(request):
    from fleet.wallet_service import WalletService
    from django.core.cache import cache
    try:
        data = json.loads(request.body)
        driver_id = data.get('driver_id')
        driver = fleet_models.Driver.objects.get(driver_id=driver_id)
        updated = WalletService.recalculate_cod_balances(driver)
        # Clear cache so next page load doesn't skip recalc
        cache.delete(f"cod_bal_recalc_{driver_id}_{timezone.now().date()}")
        return JsonResponse({'success': True, 'updated': updated})
    except fleet_models.Driver.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Driver not found'})
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)})


