@login_required(login_url='/accounts/login/')
@staff_required
def seller_detail(request, business_id):
    """
    View for viewing comprehensive seller/business details including
    teams, API settings, pickup locations, and documents.
    """
    from django.db.models import Count, Sum, Q
    from django.utils import timezone
    from datetime import timedelta

    # Fetch business with all related data
    business = get_object_or_404(
        business_models.Business.objects.select_related(
            'user', 'profile'
        ).prefetch_related(
            'team_members__user',
            'business_settings_api',
            'pickup_location',
        ),
        business_id=business_id
    )

    # Get business profile (handle missing OneToOne relation)
    try:
        business_profile = business.business_profile
    except Exception:
        business_profile = None

    # Get team members
    team_members = business.team_members.select_related('user', 'profile').all()

    # Get API settings
    api_settings = business.business_settings_api.all()

    # Get pickup locations
    pickup_locations = business.pickup_location.all()

    # Get comprehensive order statistics
    order_stats = orders_models.Order.objects.filter(business=business).aggregate(
        total_orders=Count('id'),
        to_review_orders=Count('id', filter=Q(order_status='to_review')),
        ready_orders=Count('id', filter=Q(order_status='ready_to_pickup')),
        active_orders=Count('id', filter=Q(order_status='publish')),
        delivered_orders=Count('id', filter=Q(order_status='delivered')),
        cancelled_orders=Count('id', filter=Q(order_status='cancelled')),
    )

    # Get COD statistics
    cod_stats = orders_models.Order.objects.filter(
        business=business,
        cod_amount__gt=0
    ).aggregate(
        total_cod_orders=Count('id'),
        total_cod_amount=Sum('cod_amount'),
        collected_cod=Sum('cod_amount', filter=Q(order_status='delivered')),
        pending_cod=Sum('cod_amount', filter=~Q(order_status__in=['delivered', 'cancelled'])),
    )

    # Calculate delivery success rate
    total_completed = (order_stats.get('delivered_orders') or 0) + (order_stats.get('cancelled_orders') or 0)
    delivery_success_rate = 0
    if total_completed > 0:
        delivery_success_rate = round((order_stats.get('delivered_orders') or 0) / total_completed * 100, 1)

    # Get recent orders count (last 30 days)
    thirty_days_ago = timezone.now() - timedelta(days=30)
    recent_orders_count = orders_models.Order.objects.filter(
        business=business,
        created_at__gte=thirty_days_ago
    ).count()

    # Get last 7 days orders for trend
    seven_days_ago = timezone.now() - timedelta(days=7)
    last_7_days_orders = orders_models.Order.objects.filter(
        business=business,
        created_at__gte=seven_days_ago
    ).count()

    # Get recent orders for activity timeline (last 10)
    # Use .only() to avoid missing columns (delivered_at, fulfilled_at not migrated)
    recent_orders = orders_models.Order.objects.filter(
        business=business
    ).only(
        'id', 'order_number', 'client_order_code', 'order_status',
        'cod_amount', 'customer_name', 'customer_phone', 'created_at'
    ).order_by('-created_at')[:10]

    # Get delivery task statistics
    delivery_stats = delivery_models.DeliveryTask.objects.filter(
        business=business
    ).aggregate(
        total_tasks=Count('id'),
        in_transit=Count('id', filter=Q(dl_task_status='in_transit')),
        completed=Count('id', filter=Q(dl_task_status__in=['delivered', 'partial_delivery'])),
    )

    # Calculate average orders per month (if business_since exists)
    avg_orders_per_month = 0
    if business.business_since:
        months_active = max(1, (timezone.now().date() - business.business_since).days / 30)
        avg_orders_per_month = round((order_stats.get('total_orders') or 0) / months_active, 1)

    # Handle POST for status update
    if request.method == 'POST':
        try:
            # Basic Information
            business.business_code = request.POST.get('business_code', business.business_code) or None
            business.business_name = request.POST.get('business_name', business.business_name)
            business.business_qid = request.POST.get('business_qid', business.business_qid) or None
            business.business_product_category = request.POST.get('business_product_category', business.business_product_category) or None
            business.business_bio = request.POST.get('business_bio', business.business_bio) or None
            business.business_status = request.POST.get('business_status', business.business_status)

            # Handle business_since date
            business_since_str = request.POST.get('business_since', '')
            if business_since_str:
                from datetime import datetime
                try:
                    business.business_since = datetime.strptime(business_since_str, '%Y-%m-%d').date()
                except ValueError:
                    pass  # Keep existing value if parsing fails
            else:
                business.business_since = None

            # Contact Information
            business.business_phone = request.POST.get('business_phone', business.business_phone) or None
            business.business_whatsapp = request.POST.get('business_whatsapp', business.business_whatsapp) or None
            business.business_email = request.POST.get('business_email', business.business_email) or None

            # Social Media
            business.business_instagram = request.POST.get('business_instagram', business.business_instagram) or None
            business.business_facebook_page = request.POST.get('business_facebook_page', business.business_facebook_page) or None

            # Handle fulfillment service toggle
            fulfillment_enabled = request.POST.get('fulfillment_service_enabled') == 'on'
            if fulfillment_enabled and not business.fulfillment_service_enabled:
                business.fulfillment_service_enabled = True
                business.fulfillment_activated_at = timezone.now()
            elif not fulfillment_enabled:
                business.fulfillment_service_enabled = False
                from business.models import PickupLocation
                PickupLocation.objects.filter(
                    business=business, is_fulfilment_center=True
                ).update(pickup_status='inactive')

            business.save()

            # Update business profile if exists, create if not
            if not business_profile:
                business_profile = business_models.BusinessProfile.objects.create(business=business)

            business_profile.business_address = request.POST.get('business_address', business_profile.business_address) or None
            business_profile.business_city = request.POST.get('business_city', business_profile.business_city) or None
            business_profile.business_state = request.POST.get('business_state', business_profile.business_state) or None
            business_profile.business_zip_code = request.POST.get('business_zip_code', business_profile.business_zip_code) or None
            business_profile.business_country = request.POST.get('business_country', business_profile.business_country) or 'Qatar'
            business_profile.business_website = request.POST.get('business_website', business_profile.business_website) or None
            business_profile.save()

            return JsonResponse({
                'success': True,
                'message': 'Seller updated successfully'
            })
        except Exception as e:
            logger.exception("Error updating seller %s: %s", business_id, str(e))
            return JsonResponse({
                'success': False,
                'error': 'An error occurred while updating seller'
            }, status=400)

    # Build documents list from business profile fields (if available)
    documents = []
    # Always show QID row (editable even if empty)
    documents.append({
        'document_type': 'QID / CR',
        'document_no': business.business_qid or '—',
        'document_file': None,
        'document_expiry_date': None,
        'field_name': 'business_qid',
        'field_type': 'text',
    })
    # Add business logo row — logo is on BusinessLogo related model
    logo_obj = business.business_logo.first()
    logo_file = None
    has_real_file = False
    if logo_obj and logo_obj.business_logo:
        try:
            has_real_file = (
                bool(logo_obj.business_logo.name)
                and logo_obj.business_logo.name != 'business/avatar.png'
                and logo_obj.business_logo.size > 0
            )
        except Exception:
            has_real_file = False
        if has_real_file:
            logo_file = logo_obj.business_logo
    documents.append({
        'document_type': 'Business Logo',
        'document_no': 'Custom Logo' if has_real_file else 'Default Avatar',
        'document_file': logo_file,
        'document_expiry_date': None,
        'field_name': 'business_logo',
        'field_type': 'file',
        'current_logo': logo_obj.business_logo if logo_obj else None,
    })

    # Calculate business registration completion percentage
    required_fields = ['business_name', 'business_phone', 'business_whatsapp',
                       'business_email', 'business_product_category', 'business_qid']
    filled = sum(1 for f in required_fields if getattr(business, f, None))
    completion_percentage = round(filled / len(required_fields) * 100)

    # Get user profile
    try:
        user_profile = business.user.profile if business.user else None
    except Exception:
        user_profile = None

    # User profile completion
    user_required_fields = ['first_name', 'last_name', 'email', 'phone']
    user_filled = 0
    if user_profile:
        user_filled = sum(1 for f in user_required_fields if getattr(user_profile, f, None))
    user_completion = round(user_filled / len(user_required_fields) * 100) if user_required_fields else 0

    # Get products for this business
    products_list = product_models.Product.objects.filter(
        business=business
    ).select_related('color', 'unit', 'product_category').order_by('item_sku')

    # API products are loaded via HTMX endpoint (seller_api_products) to avoid blocking page load
    api_products = []
    api_products_error = ''
    api_products_platform = ''
    first_api = api_settings.first() if api_settings else None
    if first_api and first_api.api_type in ('shopify', 'woocommerce'):
        api_products_platform = first_api.api_type

    context = {
        'page_title': f'Seller: {business.business_name}',
        'business': business,
        'business_profile': business_profile,
        'team_members': team_members,
        'api_settings': api_settings,
        'pickup_locations': pickup_locations,
        'order_stats': order_stats,
        'cod_stats': cod_stats,
        'delivery_stats': delivery_stats,
        'delivery_success_rate': delivery_success_rate,
        'recent_orders_count': recent_orders_count,
        'last_7_days_orders': last_7_days_orders,
        'recent_orders': recent_orders,
        'avg_orders_per_month': avg_orders_per_month,
        'documents': documents,
        'products_list': products_list,
        'api_products': api_products,
        'api_products_error': api_products_error,
        'api_products_platform': api_products_platform,
        'team_status_choices': business_models.BusinessTeamProfile.STATUS_CHOICES,
        'now': timezone.now(),
        'completion_percentage': completion_percentage,
        'user_profile': user_profile,
        'user_completion': user_completion,
    }

    return render(request, 'workforce/seller_detail.html', context)


@login_required(login_url='/accounts/login/')
@staff_required
def seller_api_products(request, business_id):
    """HTMX endpoint: fetch API products from Shopify/WooCommerce without blocking main page."""
    import signal

    business = get_object_or_404(business_models.Business, business_id=business_id)
    api_settings = business_models.BusinessApiSettings.objects.filter(business=business)
    first_api = api_settings.first() if api_settings else None

    api_products = []
    api_products_error = ''
    api_products_platform = ''
    imported_skus = set(
        s for s in product_models.Product.objects
        .filter(business=business)
        .exclude(item_sku='')
        .values_list('item_sku', flat=True)
        if s
    )
    import_result = getattr(request, '_seller_api_import_result', None)

    if not first_api or first_api.api_type not in ('shopify', 'woocommerce'):
        return render(request, 'workforce/parts/seller_api_products_fragment.html', {
            'api_products': [], 'api_products_error': 'No API configured',
            'api_products_platform': '', 'business': business,
            'imported_skus': imported_skus, 'import_result': import_result,
        })

    api_products_platform = first_api.api_type

    # Timeout handler to prevent hanging workers
    class ApiTimeout(Exception):
        pass

    def timeout_handler(signum, frame):
        raise ApiTimeout("API request timed out after 10 seconds")

    old_handler = signal.signal(signal.SIGALRM, timeout_handler)
    signal.alarm(10)  # 10 second hard timeout

    resolved_handle = ''
    try:
        if first_api.api_type == 'shopify':
            import shopify
            shop_name, resolved_from_custom = resolve_shopify_shop_handle(first_api)
            if not shop_name:
                raise ValueError(
                    f'Could not resolve Shopify shop handle from "{first_api.site_api_url}".'
                )
            if resolved_from_custom:
                resolved_handle = f'{shop_name}.myshopify.com'
            session = shopify.Session(shop_name, first_api.api_version or '2023-10', first_api.api_access_token)
            shopify.ShopifyResource.activate_session(session)
            try:
                page_products = shopify.Product.find(limit=250)
                for p in page_products:
                    product_title = p.title or ''
                    product_image = ''
                    if hasattr(p, 'image') and p.image:
                        product_image = getattr(p.image, 'src', '') or ''
                    elif hasattr(p, 'images') and p.images:
                        product_image = getattr(p.images[0], 'src', '') or ''
                    vendor = getattr(p, 'vendor', '') or ''
                    product_type = getattr(p, 'product_type', '') or ''

                    variants = getattr(p, 'variants', []) or []
                    if variants:
                        for v in variants:
                            variant_image = ''
                            if getattr(v, 'image_id', None) and hasattr(p, 'images'):
                                for img in (p.images or []):
                                    if getattr(img, 'id', None) == v.image_id:
                                        variant_image = getattr(img, 'src', '') or ''
                                        break
                            api_products.append({
                                'platform_id': str(p.id),
                                'variant_id': str(v.id),
                                'title': product_title,
                                'variant_title': getattr(v, 'title', '') or '',
                                'sku': getattr(v, 'sku', '') or '',
                                'barcode': getattr(v, 'barcode', '') or '',
                                'price': getattr(v, 'price', '') or '',
                                'compare_at_price': getattr(v, 'compare_at_price', '') or '',
                                'inventory_qty': getattr(v, 'inventory_quantity', 0) or 0,
                                'option1': getattr(v, 'option1', '') or '',
                                'option2': getattr(v, 'option2', '') or '',
                                'option3': getattr(v, 'option3', '') or '',
                                'weight': getattr(v, 'weight', '') or '',
                                'weight_unit': getattr(v, 'weight_unit', '') or '',
                                'image': variant_image or product_image,
                                'vendor': vendor,
                                'product_type': product_type,
                            })
                    else:
                        api_products.append({
                            'platform_id': str(p.id),
                            'variant_id': '',
                            'title': product_title,
                            'variant_title': '',
                            'sku': '',
                            'barcode': '',
                            'price': '',
                            'compare_at_price': '',
                            'inventory_qty': 0,
                            'option1': '',
                            'option2': '',
                            'option3': '',
                            'weight': '',
                            'weight_unit': '',
                            'image': product_image,
                            'vendor': vendor,
                            'product_type': product_type,
                        })
            finally:
                shopify.ShopifyResource.clear_session()

        elif first_api.api_type == 'woocommerce':
            from woocommerce import API as WooAPI
            wcapi = WooAPI(
                url=first_api.site_api_url or '',
                consumer_key=first_api.api_key or '',
                consumer_secret=first_api.api_secret or '',
                version='wc/v3',
                timeout=10,
            )
            r = wcapi.get('products', params={'per_page': 100, 'orderby': 'date', 'order': 'desc'})
            if r.status_code != 200:
                api_products_error = f'WooCommerce API error {r.status_code}'
            else:
                for p in r.json():
                    product_title = p.get('name', '')
                    product_image = ''
                    images = p.get('images', [])
                    if images:
                        product_image = images[0].get('src', '')
                    product_type = p.get('type', '')

                    variations = p.get('variations', [])
                    if p.get('type') == 'variable' and variations:
                        for var_id in variations:
                            vr = wcapi.get(f'products/{p["id"]}/variations/{var_id}')
                            if vr.status_code == 200:
                                v = vr.json()
                                var_attrs = v.get('attributes', [])
                                option1 = var_attrs[0].get('option', '') if len(var_attrs) > 0 else ''
                                option2 = var_attrs[1].get('option', '') if len(var_attrs) > 1 else ''
                                option3 = var_attrs[2].get('option', '') if len(var_attrs) > 2 else ''
                                var_image = v.get('image', {}).get('src', '') if v.get('image') else ''
                                api_products.append({
                                    'platform_id': str(p['id']),
                                    'variant_id': str(v['id']),
                                    'title': product_title,
                                    'variant_title': ' / '.join(a.get('option', '') for a in var_attrs),
                                    'sku': v.get('sku', ''),
                                    'barcode': '',
                                    'price': v.get('price', ''),
                                    'compare_at_price': v.get('regular_price', ''),
                                    'inventory_qty': v.get('stock_quantity', 0) or 0,
                                    'option1': option1,
                                    'option2': option2,
                                    'option3': option3,
                                    'weight': v.get('weight', ''),
                                    'weight_unit': '',
                                    'image': var_image or product_image,
                                    'vendor': '',
                                    'product_type': product_type,
                                })
                    else:
                        api_products.append({
                            'platform_id': str(p['id']),
                            'variant_id': '',
                            'title': product_title,
                            'variant_title': '',
                            'sku': p.get('sku', ''),
                            'barcode': '',
                            'price': p.get('price', ''),
                            'compare_at_price': p.get('regular_price', ''),
                            'inventory_qty': p.get('stock_quantity', 0) or 0,
                            'option1': '',
                            'option2': '',
                            'option3': '',
                            'weight': p.get('weight', ''),
                            'weight_unit': '',
                            'image': product_image,
                            'vendor': '',
                            'product_type': product_type,
                        })
    except ApiTimeout:
        api_products_error = 'API request timed out. Please try again.'
    except Exception as e:
        api_products_error = str(e)
    finally:
        signal.alarm(0)  # Cancel alarm
        signal.signal(signal.SIGALRM, old_handler)

    return render(request, 'workforce/parts/seller_api_products_fragment.html', {
        'api_products': api_products,
        'api_products_error': api_products_error,
        'api_products_platform': api_products_platform,
        'business': business,
        'imported_skus': imported_skus,
        'import_result': import_result,
        'resolved_handle': resolved_handle,
    })


@login_required(login_url='/accounts/login/')
@staff_required
@require_http_methods(["POST"])
def seller_api_products_import(request, business_id):
    """
    Import selected API products into the local Product catalog for this seller.
    Reads `selected[]` indices and `p_<i>_<field>` hidden inputs from the POSTed
    fragment form, creates Product rows, then re-renders the fragment with a
    result banner.
    """
    business = get_object_or_404(business_models.Business, business_id=business_id)

    indices = request.POST.getlist('selected')
    imported = 0
    skipped_dup = 0
    skipped_invalid = 0

    existing_skus = set(
        s for s in product_models.Product.objects
        .filter(business=business)
        .exclude(item_sku='')
        .values_list('item_sku', flat=True)
        if s
    )

    for raw_idx in indices:
        try:
            i = int(raw_idx)
        except (TypeError, ValueError):
            continue
        title = (request.POST.get(f'p_{i}_title') or '').strip()
        variant_title = (request.POST.get(f'p_{i}_variant_title') or '').strip()
        sku = (request.POST.get(f'p_{i}_sku') or '').strip()
        barcode = (request.POST.get(f'p_{i}_barcode') or '').strip()
        price_raw = (request.POST.get(f'p_{i}_price') or '').strip()
        option1 = (request.POST.get(f'p_{i}_option1') or '').strip()
        vendor = (request.POST.get(f'p_{i}_vendor') or '').strip()
        product_type = (request.POST.get(f'p_{i}_product_type') or '').strip()
        platform_id = (request.POST.get(f'p_{i}_platform_id') or '').strip()
        variant_id = (request.POST.get(f'p_{i}_variant_id') or '').strip()

        if not title:
            skipped_invalid += 1
            continue
        # Auto-generate SKU when the merchant didn't set one. Prefer the platform's
        # variant id (stable across re-imports), fall back to product id, then to a
        # per-business counter as last resort.
        if not sku:
            ext_id = variant_id or platform_id
            if ext_id:
                sku = f'EZ-{ext_id}'
            else:
                n = product_models.Product.objects.filter(
                    business=business, item_sku__startswith=f'EZ-{business_id}-'
                ).count() + imported + 1
                sku = f'EZ-{business_id}-{n:05d}'
        if sku in existing_skus:
            skipped_dup += 1
            continue

        if variant_title and variant_title.lower() not in ('default title', 'default'):
            item_name = f'{title} - {variant_title}'
        else:
            item_name = title

        try:
            price_val = int(round(float(price_raw))) if price_raw else 0
            if price_val < 0:
                price_val = 0
        except (TypeError, ValueError):
            price_val = 0

        product_models.Product.objects.create(
            business=business,
            item_name=item_name[:100],
            brand_name=vendor[:100],
            item_sku=sku[:100],
            barcode=barcode[:100] if barcode else None,
            item_price=price_val,
            size=option1[:100] if option1 else None,
            item_discription=product_type[:100] if product_type else None,
        )
        if sku:
            existing_skus.add(sku)
        imported += 1

    request._seller_api_import_result = {
        'imported': imported,
        'skipped_duplicate': skipped_dup,
        'skipped_invalid': skipped_invalid,
    }
    return seller_api_products(request, business_id)


@login_required(login_url='/accounts/login/')
@staff_required
def seller_api_orders(request, business_id):
    """HTMX endpoint: fetch the most recent N orders from Shopify/WooCommerce."""
    import signal

    business = get_object_or_404(business_models.Business, business_id=business_id)
    api_settings = business_models.BusinessApiSettings.objects.filter(business=business)
    first_api = api_settings.first() if api_settings else None

    ALLOWED_LIMITS = (10, 25, 50)
    try:
        limit = int(request.GET.get('limit', '10'))
    except (TypeError, ValueError):
        limit = 10
    if limit not in ALLOWED_LIMITS:
        limit = 10

    api_orders = []
    api_orders_error = ''
    api_orders_platform = ''
    resolved_handle = ''

    ctx_base = {
        'business': business, 'limit': limit, 'allowed_limits': ALLOWED_LIMITS,
    }

    if not first_api or first_api.api_type not in ('shopify', 'woocommerce'):
        return render(request, 'workforce/parts/seller_api_orders_fragment.html', dict(ctx_base, **{
            'api_orders': [], 'api_orders_error': 'No Shopify or WooCommerce API configured',
            'api_orders_platform': '', 'resolved_handle': '',
        }))

    api_orders_platform = first_api.api_type

    class ApiTimeout(Exception):
        pass

    def timeout_handler(signum, frame):
        raise ApiTimeout(f'API request timed out after 15 seconds')

    old_handler = signal.signal(signal.SIGALRM, timeout_handler)
    signal.alarm(15)

    try:
        if first_api.api_type == 'shopify':
            import shopify
            shop_name, resolved_from_custom = resolve_shopify_shop_handle(first_api)
            if not shop_name:
                raise ValueError(
                    f'Could not resolve Shopify shop handle from "{first_api.site_api_url}".'
                )
            if resolved_from_custom:
                resolved_handle = f'{shop_name}.myshopify.com'

            session = shopify.Session(shop_name, first_api.api_version or '2023-10', first_api.api_access_token)
            shopify.ShopifyResource.activate_session(session)
            try:
                orders = shopify.Order.find(limit=limit, status='any', order='created_at desc')
                for o in orders:
                    customer_name = ''
                    customer_phone = ''
                    customer = getattr(o, 'customer', None)
                    if customer:
                        first = getattr(customer, 'first_name', '') or ''
                        last = getattr(customer, 'last_name', '') or ''
                        customer_name = (first + ' ' + last).strip()
                        customer_phone = getattr(customer, 'phone', '') or ''
                    shipping = getattr(o, 'shipping_address', None)
                    if shipping:
                        if not customer_name:
                            customer_name = getattr(shipping, 'name', '') or ''
                        if not customer_phone:
                            customer_phone = getattr(shipping, 'phone', '') or ''
                    if not customer_name:
                        customer_name = getattr(o, 'email', '') or ''

                    line_items = getattr(o, 'line_items', None) or []
                    api_orders.append({
                        'id': o.id,
                        'name': getattr(o, 'name', '') or '',
                        'created_at': getattr(o, 'created_at', '') or '',
                        'financial_status': getattr(o, 'financial_status', '') or '',
                        'fulfillment_status': getattr(o, 'fulfillment_status', '') or 'unfulfilled',
                        'total_price': getattr(o, 'total_price', '') or '',
                        'currency': getattr(o, 'currency', '') or '',
                        'customer_name': customer_name,
                        'customer_phone': customer_phone,
                        'item_count': len(line_items),
                    })
            finally:
                shopify.ShopifyResource.clear_session()

        elif first_api.api_type == 'woocommerce':
            from woocommerce import API as WooAPI
            wcapi = WooAPI(
                url=first_api.site_api_url or '',
                consumer_key=first_api.api_key or '',
                consumer_secret=first_api.api_secret or '',
                version='wc/v3', timeout=12,
            )
            r = wcapi.get('orders', params={'per_page': limit, 'orderby': 'date', 'order': 'desc'})
            if r.status_code != 200:
                api_orders_error = f'WooCommerce API error {r.status_code}'
            else:
                for o in r.json():
                    billing = o.get('billing') or {}
                    shipping = o.get('shipping') or {}
                    name = (
                        ((billing.get('first_name') or '') + ' ' + (billing.get('last_name') or '')).strip()
                        or ((shipping.get('first_name') or '') + ' ' + (shipping.get('last_name') or '')).strip()
                        or billing.get('email') or ''
                    )
                    api_orders.append({
                        'id': o.get('id'),
                        'name': f"#{o.get('number') or o.get('id')}",
                        'created_at': o.get('date_created') or '',
                        'financial_status': o.get('status') or '',
                        'fulfillment_status': '',
                        'total_price': o.get('total') or '',
                        'currency': o.get('currency') or '',
                        'customer_name': name,
                        'customer_phone': billing.get('phone') or '',
                        'item_count': len(o.get('line_items') or []),
                    })
    except ApiTimeout:
        api_orders_error = f'API request timed out (>{15}s). Try a smaller batch.'
    except Exception as e:
        api_orders_error = str(e)
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, old_handler)

    return render(request, 'workforce/parts/seller_api_orders_fragment.html', dict(ctx_base, **{
        'api_orders': api_orders,
        'api_orders_error': api_orders_error,
        'api_orders_platform': api_orders_platform,
        'resolved_handle': resolved_handle,
    }))


@login_required(login_url='/accounts/login/')
@staff_required
def seller_doc_field_update(request, business_id):
    """Update or clear a single document field (business_qid or business_logo) for a seller."""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)

    business = get_object_or_404(business_models.Business, business_id=business_id)
    field = request.POST.get('field', '')
    action = request.POST.get('action', 'update')

    ALLOWED_FIELDS = {'business_qid', 'business_logo'}
    if field not in ALLOWED_FIELDS:
        return JsonResponse({'success': False, 'error': 'Invalid field'}, status=400)

    try:
        if field == 'business_logo':
            # Logo lives on BusinessLogo related model; upload_path_handler needs instance.path
            # so we save the file manually to avoid that crash.
            import os
            from django.core.files.storage import default_storage
            from django.core.files.base import ContentFile

            logo_obj = business.business_logo.first()

            if action == 'clear':
                if logo_obj and logo_obj.business_logo and logo_obj.business_logo.name != 'business/avatar.png':
                    try:
                        default_storage.delete(logo_obj.business_logo.name)
                    except Exception:
                        pass
                    logo_obj.business_logo = 'business/avatar.png'
                    logo_obj.save(update_fields=['business_logo'])
                return JsonResponse({'success': True, 'message': 'Logo cleared'})

            # update — save file manually to a fixed upload path
            file = request.FILES.get('value')
            if not file:
                return JsonResponse({'success': False, 'error': 'No file provided'}, status=400)

            ext = os.path.splitext(file.name)[1].lower()
            upload_path = f'business/logos/{business_id}/logo{ext}'
            # Delete old file if it's not the default
            if logo_obj and logo_obj.business_logo and logo_obj.business_logo.name != 'business/avatar.png':
                try:
                    default_storage.delete(logo_obj.business_logo.name)
                except Exception:
                    pass
            file.seek(0)
            saved_path = default_storage.save(upload_path, ContentFile(file.read()))

            if logo_obj:
                logo_obj.business_logo = saved_path
                logo_obj.save(update_fields=['business_logo'])
            else:
                business_models.BusinessLogo.objects.create(business=business, business_logo=saved_path)
            return JsonResponse({'success': True, 'message': 'Logo updated successfully'})

        # Text fields on Business model directly
        if action == 'clear':
            setattr(business, field, None)
            business.save(update_fields=[field])
            return JsonResponse({'success': True, 'message': 'Field cleared'})

        value = request.POST.get('value', '').strip() or None
        setattr(business, field, value)
        business.save(update_fields=[field])
        return JsonResponse({'success': True, 'message': 'Updated successfully'})

    except Exception as e:
        logger.exception("Error updating doc field %s for business %s: %s", field, business_id, str(e))
        return JsonResponse({'success': False, 'error': 'Update failed'}, status=500)


@login_required(login_url='/accounts/login/')
@staff_required
@require_POST
def wf_pickup_location_add(request, business_id):
    """Staff: add a pickup location for any seller."""
    business = get_object_or_404(business_models.Business, business_id=business_id)

    title = request.POST.get('pickup_location_title', '').strip()
    locality = request.POST.get('locality', '').strip()
    if not title:
        return JsonResponse({'success': False, 'error': 'Location title is required'}, status=400)

    def _int_or_none(val):
        try:
            return int(val) if val and val.strip() else None
        except (ValueError, TypeError):
            return None

    def _dec_or_none(val):
        try:
            from decimal import Decimal
            return Decimal(val) if val and val.strip() else None
        except Exception:
            return None

    pickup_status = request.POST.get('pickup_status', 'active')
    if pickup_status not in ('active', 'inactive', 'pending', 'suspended'):
        pickup_status = 'active'

    is_default = request.POST.get('is_default') == 'on'
    if is_default:
        business_models.PickupLocation.objects.filter(
            business=business, is_default=True
        ).update(is_default=False)

    loc = business_models.PickupLocation.objects.create(
        business=business,
        pickup_location_title=title,
        locality=locality,
        pickup_zone_no=_int_or_none(request.POST.get('pickup_zone_no')),
        pickup_street_no=_int_or_none(request.POST.get('pickup_street_no')),
        pickup_building_no=_int_or_none(request.POST.get('pickup_building_no')),
        pickup_lat=_dec_or_none(request.POST.get('pickup_lat')),
        pickup_lon=_dec_or_none(request.POST.get('pickup_lon')),
        pickup_status=pickup_status,
        is_fulfilment_center=request.POST.get('is_fulfilment_center') == 'on',
        is_default=is_default,
    )
    logger.info("Staff %s added pickup location %s for business %s", request.user.id, loc.id, business_id)
    return JsonResponse({
        'success': True,
        'message': 'Pickup location added successfully',
        'location': {
            'id': loc.id,
            'title': loc.pickup_location_title,
            'locality': loc.locality,
            'zone': loc.pickup_zone_no,
            'street': loc.pickup_street_no,
            'building': loc.pickup_building_no,
            'status': loc.pickup_status,
            'lat': str(loc.pickup_lat) if loc.pickup_lat is not None else '',
            'lon': str(loc.pickup_lon) if loc.pickup_lon is not None else '',
        }
    })


@login_required(login_url='/accounts/login/')
@staff_required
@require_POST
def wf_pickup_location_update(request, business_id, location_id):
    """Staff: edit an existing pickup location for any seller (address, pin, status)."""
    business = get_object_or_404(business_models.Business, business_id=business_id)
    loc = get_object_or_404(business_models.PickupLocation, id=location_id, business=business)

    title = request.POST.get('pickup_location_title', '').strip()
    if not title:
        return JsonResponse({'success': False, 'error': 'Location title is required'}, status=400)

    def _int_or_none(val):
        try:
            return int(val) if val and val.strip() else None
        except (ValueError, TypeError):
            return None

    def _dec_or_none(val):
        try:
            from decimal import Decimal
            return Decimal(val) if val and val.strip() else None
        except Exception:
            return None

    pickup_status = request.POST.get('pickup_status', loc.pickup_status)
    if pickup_status not in ('active', 'inactive', 'pending', 'suspended'):
        pickup_status = loc.pickup_status

    is_default = request.POST.get('is_default') == 'on'
    if is_default and not loc.is_default:
        business_models.PickupLocation.objects.filter(
            business=business, is_default=True
        ).update(is_default=False)

    loc.pickup_location_title = title
    loc.locality = request.POST.get('locality', '').strip()
    loc.pickup_zone_no = _int_or_none(request.POST.get('pickup_zone_no'))
    loc.pickup_street_no = _int_or_none(request.POST.get('pickup_street_no'))
    loc.pickup_building_no = _int_or_none(request.POST.get('pickup_building_no'))
    loc.pickup_lat = _dec_or_none(request.POST.get('pickup_lat'))
    loc.pickup_lon = _dec_or_none(request.POST.get('pickup_lon'))
    loc.pickup_status = pickup_status
    loc.is_fulfilment_center = request.POST.get('is_fulfilment_center') == 'on'
    loc.is_default = is_default
    # Cleared/missing pin triggers the QNAS auto-geocode pre_save signal
    loc.save()

    logger.info("Staff %s updated pickup location %s for business %s", request.user.id, loc.id, business_id)
    return JsonResponse({
        'success': True,
        'message': 'Pickup location updated successfully',
        'location': {
            'id': loc.id,
            'title': loc.pickup_location_title,
            'locality': loc.locality,
            'zone': loc.pickup_zone_no,
            'street': loc.pickup_street_no,
            'building': loc.pickup_building_no,
            'status': loc.pickup_status,
            'lat': str(loc.pickup_lat) if loc.pickup_lat is not None else '',
            'lon': str(loc.pickup_lon) if loc.pickup_lon is not None else '',
        }
    })


@login_required(login_url='/accounts/login/')
@staff_required
@require_POST
def wf_pickup_location_delete(request, business_id, location_id):
    """Staff: delete a pickup location for any seller. Only inactive locations may be deleted."""
    from django.db import IntegrityError
    from delivery import models as delivery_models

    business = get_object_or_404(business_models.Business, business_id=business_id)
    loc = get_object_or_404(business_models.PickupLocation, id=location_id, business=business)

    if loc.pickup_status == 'active':
        return JsonResponse({'success': False, 'error': 'Cannot delete an active pickup location. Set it to inactive first.'}, status=400)

    task_count = delivery_models.DeliveryTask.objects.filter(pickup_location=loc).count()
    if task_count:
        return JsonResponse({'success': False, 'error': f'Cannot delete: {task_count} delivery task(s) reference this location.'}, status=400)

    try:
        loc.delete()
    except IntegrityError:
        return JsonResponse({'success': False, 'error': 'Cannot delete: this location is still referenced by other records.'}, status=400)

    logger.info("Staff %s deleted pickup location %s for business %s", request.user.id, location_id, business_id)
    return JsonResponse({'success': True, 'message': 'Location deleted'})


