@login_required(login_url='/accounts/login/')
@staff_required
def driver_detail(request, driver_id):
    """
    View for viewing comprehensive driver details including
    documents, vehicles, transactions, and delivery stats.
    """
    from django.db.models import Count, Sum, Q
    from django.utils import timezone
    from datetime import timedelta

    # Fetch driver with all related data
    driver = get_object_or_404(
        fleet_models.Driver.objects.select_related(
            'user', 'profile'
        ).prefetch_related(
            'driver_vehicle',
            'driver_document',
        ),
        driver_id=driver_id
    )

    # Get vehicles
    vehicles = driver.driver_vehicle.all()

    # Get documents and check if files actually exist
    raw_documents = driver.driver_document.all()
    documents = []
    for doc in raw_documents:
        doc_dict = {
            'id': doc.id,
            'document_type': doc.document_type,
            'document_no': doc.document_no,
            'document_issued_from': getattr(doc, 'document_issued_from', ''),
            'document_expiry_date': getattr(doc, 'document_expiry_date', None),
            'document_file': None,
            'document_file_back': None,
        }
        if doc.document_file and doc.document_file.name:
            try:
                if doc.document_file.storage.exists(doc.document_file.name):
                    doc_dict['document_file'] = doc.document_file
            except Exception:
                pass
        if hasattr(doc, 'document_file_back') and doc.document_file_back and doc.document_file_back.name:
            try:
                if doc.document_file_back.storage.exists(doc.document_file_back.name):
                    doc_dict['document_file_back'] = doc.document_file_back
            except Exception:
                pass
        # Inline thumbnails only work for browser-displayable images; PDFs open in a new tab
        _image_exts = ('.jpg', '.jpeg', '.png', '.webp', '.gif')
        doc_dict['file_is_image'] = bool(
            doc_dict['document_file'] and doc_dict['document_file'].name.lower().endswith(_image_exts)
        )
        doc_dict['back_is_image'] = bool(
            doc_dict['document_file_back'] and doc_dict['document_file_back'].name.lower().endswith(_image_exts)
        )
        documents.append(doc_dict)

    # Get delivery task statistics
    delivery_stats = delivery_models.DeliveryTask.objects.filter(
        driver=driver
    ).aggregate(
        total_tasks=Count('id'),
        completed_tasks=Count('id', filter=Q(dl_task_status__in=['delivered', 'partial_delivery'])),
        in_transit=Count('id', filter=Q(dl_task_status='in_transit')),
        failed_tasks=Count('id', filter=Q(dl_task_status__in=['failed', 'cancelled'])),
    )

    # Calculate success rate
    total_completed = (delivery_stats.get('completed_tasks') or 0) + (delivery_stats.get('failed_tasks') or 0)
    success_rate = 0
    if total_completed > 0:
        success_rate = round((delivery_stats.get('completed_tasks') or 0) / total_completed * 100, 1)

    # Get recent tasks count (last 30 days)
    thirty_days_ago = timezone.now() - timedelta(days=30)
    recent_tasks_count = delivery_models.DeliveryTask.objects.filter(
        driver=driver,
        created_at__gte=thirty_days_ago
    ).count()

    # Get last 7 days tasks for trend
    seven_days_ago = timezone.now() - timedelta(days=7)
    last_7_days_tasks = delivery_models.DeliveryTask.objects.filter(
        driver=driver,
        created_at__gte=seven_days_ago
    ).count()

    # Get recent tasks for activity timeline (last 10)
    recent_tasks = delivery_models.DeliveryTask.objects.filter(
        driver=driver
    ).select_related('business').order_by('-created_at')[:10]

    # Get COD statistics
    cod_stats = delivery_models.DeliveryTask.objects.filter(
        driver=driver,
        order__cod_amount__gt=0
    ).aggregate(
        total_cod_tasks=Count('id'),
        total_cod_amount=Sum('order__cod_amount'),
        collected_cod=Sum('order__cod_amount', filter=Q(dl_task_status='delivered')),
    )

    # Get recent transactions (last 10)
    recent_transactions = fleet_models.DriverTransaction.objects.filter(
        driver=driver
    ).order_by('-created_at')[:10]

    from core.decorators import is_superadmin as check_superadmin
    user_is_superadmin = check_superadmin(request.user)

    # Handle POST request for updates
    if request.method == 'POST':
        try:
            driver.driver_phone = request.POST.get('driver_phone', driver.driver_phone)
            driver.driver_whatsapp = request.POST.get('driver_whatsapp', driver.driver_whatsapp)
            driver.driver_bio = request.POST.get('driver_bio', driver.driver_bio)
            # Update wallet limit if provided
            credit_limit = request.POST.get('credit_limit')
            if credit_limit:
                from decimal import Decimal
                driver.credit_limit = Decimal(credit_limit)
            # Notify opt-in + preferred zones live on the "Zones & Notify" tab.
            # Only update when that form's marker is posted, otherwise the
            # Settings-tab save would clear them on every submit.
            if request.POST.get('zones_form'):
                driver.to_be_notified = bool(request.POST.get('to_be_notified'))

            # Status change — superadmin only
            new_status = request.POST.get('driver_status')
            old_driver_status = driver.driver_status
            if new_status and new_status != driver.driver_status:
                if user_is_superadmin:
                    driver.driver_status = new_status
                else:
                    return JsonResponse({
                        'success': False,
                        'error': 'Only super admins can change driver status.'
                    }, status=403)

            driver.save()

            # Apply preferred zone groups M2M if the zones form was submitted.
            if request.POST.get('zones_form'):
                zone_ids = request.POST.getlist('preferred_zone_groups')
                try:
                    int_ids = [int(z) for z in zone_ids if z]
                except (TypeError, ValueError):
                    int_ids = []
                driver.preferred_zone_groups.set(int_ids)

            # Fire auto flows for driver status changes
            if new_status and new_status != old_driver_status:
                try:
                    from core.auto_flow_executor import execute_flows_for_trigger
                    ctx = {'driver_name': driver.driver_name or '', 'driver_phone': driver.driver_phone or ''}
                    if new_status == 'approved':
                        execute_flows_for_trigger('staff_driver_approved', extra_context=ctx)
                    elif new_status == 'suspended':
                        execute_flows_for_trigger('staff_driver_suspended', extra_context=ctx)
                except Exception as e:
                    logger.warning(f"Auto flow failed for driver status change {driver.pk}: {e}")

            return JsonResponse({
                'success': True,
                'message': 'Driver updated successfully'
            })
        except Exception as e:
            logger.exception("Error updating driver %s: %s", driver_id, str(e))
            return JsonResponse({
                'success': False,
                'error': 'An error occurred while updating driver'
            }, status=400)

    from delivery.models import ZoneGroup
    all_zone_groups = ZoneGroup.objects.filter(is_active=True).order_by('display_order', 'name')
    preferred_zone_ids = set(driver.preferred_zone_groups.values_list('id', flat=True))

    context = {
        'page_title': f'Driver: {driver.user.first_name} {driver.user.last_name}',
        'driver': driver,
        'vehicles': vehicles,
        'documents': documents,
        'all_zone_groups': all_zone_groups,
        'preferred_zone_ids': preferred_zone_ids,
        'delivery_stats': delivery_stats,
        'success_rate': success_rate,
        'recent_tasks_count': recent_tasks_count,
        'last_7_days_tasks': last_7_days_tasks,
        'recent_tasks': recent_tasks,
        'cod_stats': cod_stats,
        'recent_transactions': recent_transactions,
        'now': timezone.now(),
        'user_is_superadmin': user_is_superadmin,
        'vehicle_type_choices': fleet_models.VEHICLE_CHOICES,
        'document_type_choices': fleet_models.DriverDocument.document_choices,
        'job_type_choices': fleet_models.DRIVER_JOB_TYPE_CHOICES,
        'work_time_slab_choices': fleet_models.WORK_TIME_SLAB_CHOICES,
        'driver_time_slabs': driver.work_time_slab_list,
    }

    return render(request, 'workforce/driver_detail.html', context)


@login_required(login_url='/accounts/login/')
@staff_required
@login_required(login_url='/accounts/login/')
@staff_required
def driver_set_status(request, driver_id):
    """Set driver account status (approved/blocked/suspended/rejected) via POST."""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)
    import json as _json
    try:
        body = _json.loads(request.body)
    except ValueError:
        return JsonResponse({'success': False, 'error': 'Invalid JSON'}, status=400)
    new_status = body.get('status')
    if new_status not in ('approved', 'blocked', 'suspended', 'rejected'):
        return JsonResponse({'success': False, 'error': 'Invalid status'}, status=400)
    driver = get_object_or_404(fleet_models.Driver, driver_id=driver_id)
    driver.driver_status = new_status
    driver.save(update_fields=['driver_status'])
    return JsonResponse({'success': True, 'status': new_status})


@login_required(login_url='/accounts/login/')
@api_staff_required
def driver_toggle_status(request, driver_id):
    """Toggle driver availability (available ↔ offline) without changing driver_status."""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'POST required'}, status=405)
    driver = get_object_or_404(fleet_models.Driver, driver_id=driver_id)
    if driver.driver_status != 'approved':
        return JsonResponse({'success': False, 'error': 'Only approved drivers can be toggled'}, status=400)
    driver.driver_availability = 'offline' if driver.driver_availability == 'available' else 'available'
    driver.save(update_fields=['driver_availability'])
    return JsonResponse({'success': True, 'availability': driver.driver_availability})


