@login_required(login_url='/accounts/login/')
@staff_required
def wf_driver_tasks(request):
    """Staff view: all tasks for a specific driver, filterable by status/date."""
    from django.db.models import Count, Q, Sum
    from decimal import Decimal

    # --- Driver selection ---
    driver_id = request.GET.get('driver_id', '')
    selected_driver = None
    drivers = fleet_models.Driver.objects.filter(
        driver_status='approved'
    ).select_related('user').order_by('user__first_name', 'user__last_name')

    if driver_id:
        try:
            selected_driver = fleet_models.Driver.objects.select_related('user').get(
                driver_id=driver_id, driver_status='approved'
            )
        except fleet_models.Driver.DoesNotExist:
            pass

    tasks = None
    stats = {}
    filter_params = ''
    chart_daily = {'labels': [], 'taken': [], 'delivered': [], 'failed': [], 'accepted': [], 'open': []}

    if selected_driver:
        # --- Filters ---
        status_filter = request.GET.get('status', '')
        date_from = request.GET.get('date_from', '')
        date_to = request.GET.get('date_to', '')
        date_preset = request.GET.get('date_preset', '')
        search = request.GET.get('q', '')

        from datetime import timedelta
        today = timezone.now().date()

        if date_preset == 'today':
            date_from = date_to = today.isoformat()
        elif date_preset == 'yesterday':
            y = today - timedelta(days=1)
            date_from = date_to = y.isoformat()
        elif date_preset == '7days':
            date_from = (today - timedelta(days=7)).isoformat()
            date_to = today.isoformat()
        elif date_preset == '30days':
            date_from = (today - timedelta(days=30)).isoformat()
            date_to = today.isoformat()

        tasks = delivery_models.DeliveryTask.objects.filter(
            driver=selected_driver
        ).select_related(
            'order', 'order__business'
        ).order_by('-dl_task_date', '-id')

        if status_filter:
            tasks = tasks.filter(dl_task_status=status_filter)
        if date_from:
            tasks = tasks.filter(dl_task_date__gte=date_from)
        if date_to:
            tasks = tasks.filter(dl_task_date__lte=date_to)
        if search:
            tasks = tasks.filter(
                Q(dl_task_number__icontains=search) |
                Q(order__customer_name__icontains=search) |
                Q(order__customer_phone__icontains=search) |
                Q(order__order_number__icontains=search)
            )

        # --- Stats from filtered set ---
        agg = tasks.aggregate(
            total=Count('id'),
            delivered=Count('id', filter=Q(dl_task_status__in=['delivered', 'partial_delivery'])),
            in_progress=Count('id', filter=Q(dl_task_status__in=[
                'accepted', 'picked_up', 'start_ride',
                'out_for_delivery', 'in_transit', 'contacted', 'non_reachable'
            ])),
            failed=Count('id', filter=Q(dl_task_status__in=['failed', 'cancelled', 'rejected'])),
            total_earnings=Sum('dl_price', filter=Q(dl_task_status__in=['delivered', 'partial_delivery'])),
            total_cod=Sum('order__cod_amount'),
            cod_in_hand=Sum('cod_collected_amount', filter=Q(cod_collected=True, cod_settled=False)),
            cod_settled=Sum('cod_collected_amount', filter=Q(cod_settled=True)),
        )
        stats = {
            'total': agg['total'] or 0,
            'delivered': agg['delivered'] or 0,
            'in_progress': agg['in_progress'] or 0,
            'failed': agg['failed'] or 0,
            'pending': max(0, (agg['total'] or 0) - (agg['delivered'] or 0) - (agg['in_progress'] or 0) - (agg['failed'] or 0)),
            'total_earnings': agg['total_earnings'] or Decimal('0.00'),
            'total_cod': agg['total_cod'] or Decimal('0.00'),
            'cod_in_hand': agg['cod_in_hand'] or Decimal('0.00'),
            'cod_settled': agg['cod_settled'] or Decimal('0.00'),
        }
        if stats['total'] > 0:
            stats['completion_rate'] = round((stats['delivered'] / stats['total']) * 100, 1)
        else:
            stats['completion_rate'] = 0

        # --- Daily series for the activity chart (delivered / failed / accepted / open) ---
        daily_rows = list(
            tasks.exclude(dl_task_date__isnull=True)
            .values('dl_task_date')
            .annotate(
                taken=Count('id'),
                day_delivered=Count('id', filter=Q(dl_task_status__in=['delivered', 'partial_delivery'])),
                day_failed=Count('id', filter=Q(dl_task_status__in=['failed', 'cancelled', 'rejected'])),
                day_accepted=Count('id', filter=Q(dl_task_status__in=[
                    'accepted', 'picked_up', 'start_ride',
                    'out_for_delivery', 'in_transit', 'contacted', 'non_reachable'
                ])),
            )
            .order_by('-dl_task_date')[:10]
        )
        daily_rows.reverse()
        chart_daily = {
            'labels': [r['dl_task_date'].strftime('%d %b') for r in daily_rows],
            'taken': [r['taken'] for r in daily_rows],
            'delivered': [r['day_delivered'] for r in daily_rows],
            'failed': [r['day_failed'] for r in daily_rows],
            'accepted': [r['day_accepted'] for r in daily_rows],
            'open': [
                r['taken'] - r['day_delivered'] - r['day_failed'] - r['day_accepted']
                for r in daily_rows
            ],
        }

        # --- Pagination (stats + chart above stay on the full filtered set) ---
        from urllib.parse import urlencode
        kept = {'driver_id': selected_driver.driver_id}
        for key in ('status', 'date_preset', 'date_from', 'date_to', 'q'):
            val = request.GET.get(key, '').strip()
            if val:
                kept[key] = val
        filter_params = urlencode(kept)

        page_obj = paginate_queryset(request, tasks, items_per_page=25)
        # Materialise so the zone/distance attributes attached below survive
        page_obj.object_list = list(page_obj.object_list)
        tasks = page_obj

    if tasks is not None:
        # Build zone name lookup for display
        zone_numbers = set(t.order.dl_zone for t in tasks if t.order and t.order.dl_zone)
        zone_map = {}
        if zone_numbers:
            zone_map = dict(
                delivery_models.ZoneName.objects.filter(
                    zone_number__in=zone_numbers
                ).values_list('zone_number', 'zone_name')
            )

        # Get last distance for each task from TaskStatusPoint
        task_ids = [t.id for t in tasks]
        distance_map = {}
        if task_ids:
            from django.db.models import Subquery, OuterRef
            latest_points = delivery_models.TaskStatusPoint.objects.filter(
                task_id__in=task_ids,
                distance_from_delivery__isnull=False,
            ).order_by('task_id', '-created_at').distinct('task_id')
            for pt in latest_points:
                distance_map[pt.task_id] = pt.distance_from_delivery

        # Attach zone_name_display and distance to each task
        for t in tasks:
            if t.order and t.order.dl_zone:
                t.zone_name_display = zone_map.get(t.order.dl_zone, '')
            else:
                t.zone_name_display = ''
            t.delivery_distance_km = distance_map.get(t.id)

    DL_TASK_STATUS_CHOICES = [
        ('for_review', 'For Review'),
        ('pending', 'Pending'),
        ('assigned', 'Assigned'),
        ('accepted', 'Accepted'),
        ('picked_up', 'Picked Up'),
        ('start_ride', 'Start Ride'),
        ('out_for_delivery', 'Out for Delivery'),
        ('in_transit', 'In Transit'),
        ('contacted', 'Contacted'),
        ('non_reachable', 'Non Reachable'),
        ('delivered', 'Delivered'),
        ('failed', 'Failed'),
        ('rejected', 'Rejected'),
        ('cancelled', 'Cancelled'),
    ]

    context = {
        'page_title': 'Driver Tasks',
        'drivers': drivers,
        'selected_driver': selected_driver,
        'tasks': tasks,
        'stats': stats,
        'chart_daily': chart_daily,
        'filter_params': filter_params,
        'per_page': get_per_page(request, default=25),
        'status_choices': DL_TASK_STATUS_CHOICES,
        'current_filters': {
            'status': request.GET.get('status', ''),
            'date_from': request.GET.get('date_from', ''),
            'date_to': request.GET.get('date_to', ''),
            'date_preset': request.GET.get('date_preset', ''),
            'q': request.GET.get('q', ''),
        },
    }
    return render(request, 'workforce/fleet_driver_tasks.html', context)


