@login_required(login_url='account_login')
@superuser_required
def wf_ai_config(request):
    from django.conf import settings as django_settings
    from pathlib import Path
    import subprocess

    ENV_PATH = Path(django_settings.BASE_DIR) / '.env'

    EDITABLE_KEYS = [
        # Provider API keys
        'ANTHROPIC_API_KEY',
        'OPENAI_API_KEY',
        'GOOGLE_AI_API_KEY',
        'XAI_API_KEY',
        'GROQ_API_KEY',
        'GLM_API_KEY',
        'AI_API_KEY',
        'AI_BASE_URL',
        # Business dashboard AI
        'AI_CHAT_PROVIDER',
        'AI_CHAT_MODEL',
        'AI_CHAT_FALLBACK_PROVIDER',
        'AI_CHAT_FALLBACK_MODEL',
        # WhatsApp reply AI
        'AI_WA_PROVIDER',
        'AI_WA_MODEL',
        'AI_WA_FALLBACK_PROVIDER',
        'AI_WA_FALLBACK_MODEL',
        # Shared agent settings
        'AI_AGENT_MAX_TOKENS',
        'AI_AGENT_DAILY_BUDGET',
        'AI_AGENT_MONTHLY_BUDGET',
        'AI_AGENT_RATE_LIMIT_USER',
        'AI_AGENT_RATE_LIMIT_BUSINESS',
        'AI_AGENT_RATE_LIMIT_GLOBAL',
        'AI_AGENT_ALERT_PHONES',
        'AI_AGENT_ENABLED',
        'AI_AGENT_WHATSAPP_ENABLED',
        # AI agent conversation API (n8n etc.)
        'AIAGENT_API_TOKEN',
        'AIAGENT_API_RATE_LIMIT',
    ]
    BLANK_SKIP_KEYS = {'ANTHROPIC_API_KEY', 'OPENAI_API_KEY', 'GOOGLE_AI_API_KEY', 'XAI_API_KEY', 'GROQ_API_KEY', 'GLM_API_KEY', 'AI_API_KEY', 'AIAGENT_API_TOKEN'}

    def read_env():
        env = {}
        try:
            for line in ENV_PATH.read_text().splitlines():
                line = line.strip()
                if '=' in line and not line.startswith('#'):
                    k, _, v = line.partition('=')
                    env[k.strip()] = v.strip()
        except FileNotFoundError:
            pass
        return env

    def write_env_key(key, value):
        try:
            text = ENV_PATH.read_text()
        except FileNotFoundError:
            text = ''
        lines = text.splitlines(keepends=True)
        replaced = False
        new_lines = []
        for line in lines:
            stripped = line.strip()
            if stripped.startswith(f'{key}=') or (not stripped.startswith('#') and stripped.startswith(key) and '=' in stripped and stripped.split('=', 1)[0].strip() == key):
                new_lines.append(f'{key}={value}\n')
                replaced = True
            else:
                new_lines.append(line)
        if not replaced:
            new_lines.append(f'{key}={value}\n')
        ENV_PATH.write_text(''.join(new_lines))

    save_msg = None
    save_error = None

    if request.method == 'POST':
        # Per-section save: a section form only submits its own fields, so we
        # write just the keys present in this POST. `section` is informational.
        is_ajax = request.headers.get('x-requested-with') == 'XMLHttpRequest'
        section = request.POST.get('section', '').strip()
        saved = []
        for key in EDITABLE_KEYS:
            if key in request.POST:
                val = request.POST[key].strip()
                if key in BLANK_SKIP_KEYS and not val:
                    continue
                write_env_key(key, val)
                saved.append(key)
        try:
            result = subprocess.run(
                ['bash', '-c', "kill -HUP $(pgrep -f 'gunicorn.*ezzydelivery' | head -1)"],
                capture_output=True, text=True, timeout=10
            )
            reloaded = result.returncode == 0
            save_msg = ('Saved and server reloaded.' if reloaded
                        else 'Saved. Server reload may be needed manually.')
        except Exception:
            reloaded = False
            save_msg = 'Saved. Please reload the server.'
        if is_ajax:
            return JsonResponse({
                'success': True, 'message': save_msg, 'section': section,
                'saved': saved, 'reloaded': reloaded,
            })
        from django.contrib import messages as django_messages
        django_messages.success(request, save_msg)
        return redirect('workforce:wf_ai_config')

    env = read_env()

    # Live status from the active chat service
    agent_status = {}
    budget_usage = {}
    today_usage = {}
    try:
        from ai_agent.services.unified_service import get_chat_service
        from ai_agent.services.claude_service import PRICING
        from ai_agent.models import UsageLog, Conversation
        from django.db.models import Sum, Count
        from datetime import timedelta

        svc = get_chat_service(purpose='chat')
        available, status_msg = svc.is_available()
        agent_status = {'available': available, 'message': status_msg, 'model': svc.model}
        _bt = getattr(svc, 'budget_tracker', None)
        budget_usage = _bt.get_usage() if _bt is not None else {}

        today = timezone.now().date()
        today_stats = UsageLog.objects.filter(created_at__date=today, success=True).aggregate(
            calls=Count('id'),
            tokens_in=Sum('tokens_input'),
            tokens_out=Sum('tokens_output'),
            cost=Sum('estimated_cost'),
        )
        month_start = today.replace(day=1)
        month_stats = UsageLog.objects.filter(created_at__date__gte=month_start, success=True).aggregate(
            calls=Count('id'),
            cost=Sum('estimated_cost'),
        )
        active_convs = Conversation.objects.filter(
            status='active',
            last_activity__gte=timezone.now() - timedelta(hours=24)
        ).count()
        today_usage = {
            'calls': today_stats['calls'] or 0,
            'tokens_in': today_stats['tokens_in'] or 0,
            'tokens_out': today_stats['tokens_out'] or 0,
            'cost': float(today_stats['cost'] or 0),
            'month_calls': month_stats['calls'] or 0,
            'month_cost': float(month_stats['cost'] or 0),
            'active_conversations': active_convs,
        }
        pricing_map = PRICING
    except Exception as e:
        agent_status = {'available': False, 'message': str(e), 'model': ''}
        pricing_map = {}

    import json as _json

    models_by_provider = {
        'anthropic': [
            {'id': 'claude-sonnet-4-6',        'label': 'Claude Sonnet 4.6 (Latest)'},
            {'id': 'claude-sonnet-4-20250514',  'label': 'Claude Sonnet 4 (May 2025)'},
            {'id': 'claude-3-5-sonnet-20241022','label': 'Claude 3.5 Sonnet'},
            {'id': 'claude-3-haiku-20240307',   'label': 'Claude 3 Haiku (Fast / Cheap)'},
            {'id': 'claude-3-opus-20240229',    'label': 'Claude 3 Opus (Powerful)'},
        ],
        'openai': [
            {'id': 'gpt-4o',          'label': 'GPT-4o (Latest)'},
            {'id': 'gpt-4o-mini',     'label': 'GPT-4o Mini (Fast)'},
            {'id': 'gpt-4-turbo',     'label': 'GPT-4 Turbo'},
            {'id': 'gpt-3.5-turbo',   'label': 'GPT-3.5 Turbo (Cheap)'},
        ],
        'gemini': [
            {'id': 'gemini-2.0-flash',  'label': 'Gemini 2.0 Flash (Latest)'},
            {'id': 'gemini-1.5-pro',    'label': 'Gemini 1.5 Pro'},
            {'id': 'gemini-1.5-flash',  'label': 'Gemini 1.5 Flash (Fast)'},
            {'id': 'gemini-pro',        'label': 'Gemini Pro'},
        ],
        'xai': [
            {'id': 'grok-3',            'label': 'Grok 3 (Latest)'},
            {'id': 'grok-3-mini',       'label': 'Grok 3 Mini (Fast)'},
            {'id': 'grok-2-1212',       'label': 'Grok 2'},
            {'id': 'grok-beta',         'label': 'Grok Beta'},
        ],
        'groq': [
            {'id': 'llama-3.1-8b-instant',    'label': 'Llama 3.1 8B Instant (Recommended — high rate limit)'},
            {'id': 'llama-3.3-70b-versatile', 'label': 'Llama 3.3 70B (Free tier: 12K TPM — may fail with tools)'},
            {'id': 'mixtral-8x7b-32768',      'label': 'Mixtral 8x7B (Long context)'},
            {'id': 'gemma2-9b-it',            'label': 'Gemma 2 9B'},
            {'id': 'qwen/qwen3-32b',          'label': 'Qwen 3 32B (Free tier: 6K TPM — too low for tools)'},
        ],
        'zhipu': [
            {'id': 'glm-4.7-flash', 'label': 'GLM-4.7 Flash (Free tier)'},
            {'id': 'glm-5',         'label': 'GLM-5'},
            {'id': 'glm-5-turbo',   'label': 'GLM-5 Turbo (Fast)'},
            {'id': 'glm-4.7',       'label': 'GLM-4.7'},
            {'id': 'glm-4.6',       'label': 'GLM-4.6'},
            {'id': 'glm-4.5',       'label': 'GLM-4.5'},
            {'id': 'glm-4.5-air',   'label': 'GLM-4.5 Air (Fast)'},
        ],
        # 9Router models are fetched live from {ROUTER_BASE_URL}/models.
        'router': [],
    }

    def _mask(key):
        return (key[:12] + '...' + key[-4:]) if len(key) > 16 else ('*' * len(key) if key else '')

    # A provider is "ready" only when its API key is configured — surface that
    # on each provider row instead of listing all six blindly.
    _provider_key_env = {
        'anthropic': 'ANTHROPIC_API_KEY', 'openai': 'OPENAI_API_KEY',
        'gemini': 'GOOGLE_AI_API_KEY', 'xai': 'XAI_API_KEY',
        'groq': 'GROQ_API_KEY', 'zhipu': 'GLM_API_KEY',
        'router': 'AI_API_KEY',
    }
    providers = [
        {'id': 'anthropic', 'abbr': 'A',   'name': 'Anthropic', 'sub': 'Claude Sonnet / Haiku / Opus'},
        {'id': 'openai',    'abbr': 'AI',  'name': 'OpenAI',    'sub': 'GPT-4o / GPT-4 Turbo'},
        {'id': 'gemini',    'abbr': 'G',   'name': 'Google',    'sub': 'Gemini 2.0 / 1.5 Pro'},
        {'id': 'xai',       'abbr': 'xAI', 'name': 'xAI',       'sub': 'Grok 3 / Grok 3 Mini'},
        {'id': 'groq',      'abbr': 'GQ',  'name': 'Groq',      'sub': 'Llama 3.3 / Mixtral (fast)'},
        {'id': 'zhipu',     'abbr': 'ZP',  'name': 'Zhipu AI',  'sub': 'GLM-4.7 Flash (free tier)'},
        {'id': 'router',    'abbr': '9R',  'name': '9Router',   'sub': 'Self-hosted gateway — any model'},
    ]
    for p in providers:
        if p['id'] == 'router':
            # 9Router needs a base URL (key optional depending on the gateway).
            p['configured'] = bool(env.get('AI_BASE_URL', '').strip())
        else:
            p['configured'] = bool(env.get(_provider_key_env[p['id']], '').strip())
    ready_count = sum(1 for p in providers if p['configured'])
    api_keys = [
        {'id': 'anthropic', 'name': 'Anthropic', 'env': 'ANTHROPIC_API_KEY', 'masked': _mask(env.get('ANTHROPIC_API_KEY', '')), 'placeholder': 'sk-ant-api03-...',           'help': 'console.anthropic.com → API Keys'},
        {'id': 'openai',    'name': 'OpenAI',    'env': 'OPENAI_API_KEY',    'masked': _mask(env.get('OPENAI_API_KEY', '')),    'placeholder': 'sk-...',                     'help': 'platform.openai.com → API Keys'},
        {'id': 'gemini',    'name': 'Google',    'env': 'GOOGLE_AI_API_KEY', 'masked': _mask(env.get('GOOGLE_AI_API_KEY', '')), 'placeholder': 'AIza...',                    'help': 'aistudio.google.com → API Keys'},
        {'id': 'groq',      'name': 'Groq',      'env': 'GROQ_API_KEY',      'masked': _mask(env.get('GROQ_API_KEY', '')),      'placeholder': 'gsk_...',                    'help': 'console.groq.com → API Keys'},
        {'id': 'xai',       'name': 'xAI',       'env': 'XAI_API_KEY',       'masked': _mask(env.get('XAI_API_KEY', '')),       'placeholder': 'xai-...',                    'help': 'console.x.ai → API Keys'},
        {'id': 'zhipu',     'name': 'Zhipu AI',  'env': 'GLM_API_KEY',       'masked': _mask(env.get('GLM_API_KEY', '')),       'placeholder': 'xxxxxxxx.xxxxxxxxxxxxxxxx', 'help': 'bigmodel.cn → API Keys (format: id.secret)'},
        {'id': 'router',    'name': '9Router',   'env': 'AI_API_KEY',        'masked': _mask(env.get('AI_API_KEY', '')),        'placeholder': 'sk-...',                     'help': 'Shared gateway API key.',
         'base_url_env': 'AI_BASE_URL', 'base_url': env.get('AI_BASE_URL', '')},
    ]

    # Flag each credential row: which providers are actually being called, and
    # which of those are selected but still missing their key.
    _primary = {
        env.get('AI_CHAT_PROVIDER', 'anthropic') or 'anthropic',
        env.get('AI_WA_PROVIDER', 'anthropic') or 'anthropic',
    }
    _in_use = _primary | {
        p for p in (env.get('AI_CHAT_FALLBACK_PROVIDER', ''),
                    env.get('AI_WA_FALLBACK_PROVIDER', '')) if p
    }
    for k in api_keys:
        k['in_use'] = k['id'] in _in_use
        _is_primary = k['id'] in _primary
        if k.get('base_url_env'):
            k['needs_key'] = _is_primary and not k.get('base_url')
        else:
            k['needs_key'] = _is_primary and not k['masked']

    return render(request, 'workforce/ai_config.html', {
        'env': env,
        'chat_provider':          env.get('AI_CHAT_PROVIDER', 'anthropic') or 'anthropic',
        'chat_fallback_provider': env.get('AI_CHAT_FALLBACK_PROVIDER', '') or '',
        'wa_provider':            env.get('AI_WA_PROVIDER',   'anthropic') or 'anthropic',
        'wa_fallback_provider':   env.get('AI_WA_FALLBACK_PROVIDER', '') or '',
        'providers': providers,
        'ready_count': ready_count,
        'api_keys': api_keys,
        'masked_aiagent_token': _mask(env.get('AIAGENT_API_TOKEN', '')),
        'models_by_provider_json': _json.dumps(models_by_provider),
        'agent_status': agent_status,
        'budget_usage': budget_usage,
        'today_usage': today_usage,
        'pricing_map': pricing_map,
    })


@login_required(login_url='account_login')
@superuser_required
@require_POST
def wf_ai_config_test(request):
    """AJAX live tests for the AI Config page.

    POST kind=chat|wa   → send a sample prompt through that purpose's chat
                          service, return the reply + latency + model.
    POST kind=aiagent_api → verify the conversation-API token is set and the
                          agent is enabled (no external call / no cost).
    """
    import time
    from django.conf import settings
    kind = request.POST.get('kind', '').strip()

    if kind == 'aiagent_api':
        token_set = bool(getattr(settings, 'AIAGENT_API_TOKEN', ''))
        enabled = bool(getattr(settings, 'AI_AGENT_ENABLED', False))
        if not token_set:
            return JsonResponse({'success': False, 'error': 'No service token set — the API is disabled.'})
        if not enabled:
            return JsonResponse({'success': False, 'error': 'Token is set, but the AI agent is disabled.'})
        return JsonResponse({
            'success': True,
            'message': f"Token configured · agent online · rate {getattr(settings, 'AIAGENT_API_RATE_LIMIT', '120/min')}",
        })

    if kind in ('chat', 'wa'):
        purpose = 'chat' if kind == 'chat' else 'whatsapp_reply'
        sample = request.POST.get('message', '').strip() or 'Hi, do you deliver to Lusail?'
        try:
            from ai_agent.services.unified_service import get_chat_service
            svc = get_chat_service(purpose=purpose)
            available, status_msg = svc.is_available()
            if not available:
                return JsonResponse({'success': False, 'error': status_msg or 'Provider unavailable'})
            t0 = time.time()
            result = svc.chat(messages=[{'role': 'user', 'content': sample}])
            elapsed = round((time.time() - t0) * 1000)
            if result.get('error'):
                return JsonResponse({'success': False, 'error': result.get('message', 'AI error')})
            return JsonResponse({
                'success': True,
                'reply': (result.get('content') or '').strip(),
                'model': getattr(svc, 'model', ''),
                'elapsed_ms': elapsed,
                'sample': sample,
            })
        except Exception as e:
            logger.exception('AI config test failed (%s)', kind)
            return JsonResponse({'success': False, 'error': f'{type(e).__name__}: {e}'})

    return JsonResponse({'success': False, 'error': 'Unknown test kind'}, status=400)


@login_required(login_url='account_login')
@superuser_required
def wf_ai_models_api(request):
    """
    AJAX endpoint: return model list for a given AI provider.
    Fetches live from provider API and caches for 1 hour.
    GET ?provider=groq
    """
    import requests as http
    from django.core.cache import cache
    from django.conf import settings as dj_settings

    provider = request.GET.get('provider', '').strip().lower()
    if not provider:
        return JsonResponse({'error': 'provider required'}, status=400)

    cache_key = f'ai_models_{provider}'
    cached = cache.get(cache_key)
    if cached is not None:
        return JsonResponse({'models': cached, 'cached': True})

    def _fetch():
        timeout = 10
        try:
            if provider == 'anthropic':
                key = getattr(dj_settings, 'ANTHROPIC_API_KEY', '')
                if not key:
                    return None, 'Anthropic API key not configured'
                r = http.get(
                    'https://api.anthropic.com/v1/models',
                    headers={'x-api-key': key, 'anthropic-version': '2023-06-01'},
                    timeout=timeout,
                )
                if r.status_code != 200:
                    return None, f'Anthropic API error {r.status_code}'
                data = r.json().get('data', [])
                # Only chat models (exclude image/embedding models)
                models = [
                    {'id': m['id'], 'label': m.get('display_name', m['id'])}
                    for m in data
                    if 'claude' in m['id']
                ]

            elif provider == 'zhipu':
                key = getattr(dj_settings, 'GLM_API_KEY', '')
                if not key:
                    return None, 'GLM API key not configured'
                # glm-4.7-flash is a free-tier model not listed in the /models API — always pin it first
                free_models = [{'id': 'glm-4.7-flash', 'label': 'GLM-4.7 Flash (Free tier)'}]
                skip_keywords = ('embedding', 'cogvideo', 'cogview', 'emohaa', 'charglm', 'codegeex')
                try:
                    r = http.get(
                        'https://open.bigmodel.cn/api/paas/v4/models',
                        headers={'Authorization': f'Bearer {key}'},
                        timeout=timeout,
                    )
                    if r.status_code == 200:
                        live = sorted(
                            [
                                {'id': m['id'], 'label': m['id']}
                                for m in r.json().get('data', [])
                                if not any(kw in m['id'] for kw in skip_keywords)
                            ],
                            key=lambda x: x['id'], reverse=True,
                        )
                        models = free_models + live
                    else:
                        models = free_models
                except Exception:
                    models = free_models

            elif provider in ('openai', 'xai', 'groq'):
                key_map = {
                    'openai': ('OPENAI_API_KEY',  'https://api.openai.com/v1/models'),
                    'xai':    ('XAI_API_KEY',     'https://api.x.ai/v1/models'),
                    'groq':   ('GROQ_API_KEY',    'https://api.groq.com/openai/v1/models'),
                }
                key_setting, url = key_map[provider]
                key = getattr(dj_settings, key_setting, '')
                if not key:
                    return None, f'{provider} API key not configured'
                r = http.get(
                    url,
                    headers={'Authorization': f'Bearer {key}'},
                    timeout=timeout,
                )
                if r.status_code != 200:
                    return None, f'{provider} API error {r.status_code}'
                data = r.json().get('data', [])
                def _is_chat(model_id):
                    skip = {'whisper', 'tts', 'dall-e', 'embedding', 'babbage', 'davinci', 'ada', 'curie'}
                    return not any(s in model_id for s in skip)
                live_ids = {m['id'] for m in data if _is_chat(m['id'])}
                # Build label map from our known list so curated labels show in the dropdown
                from ai_agent.services.unified_service import OpenAICompatService  # noqa
                known_labels = {
                    'openai': {
                        'gpt-4o':        'GPT-4o (Latest)',
                        'gpt-4o-mini':   'GPT-4o Mini (Fast)',
                        'gpt-4-turbo':   'GPT-4 Turbo',
                        'gpt-3.5-turbo': 'GPT-3.5 Turbo (Cheap)',
                    },
                    'xai': {
                        'grok-3':      'Grok 3 (Latest)',
                        'grok-3-mini': 'Grok 3 Mini (Fast)',
                        'grok-2-1212': 'Grok 2',
                        'grok-beta':   'Grok Beta',
                    },
                    'groq': {
                        'llama-3.1-8b-instant':    'Llama 3.1 8B Instant (Recommended — high rate limit)',
                        'llama-3.3-70b-versatile': 'Llama 3.3 70B (Free tier: 12K TPM — may fail with tools)',
                        'mixtral-8x7b-32768':      'Mixtral 8x7B (Long context)',
                        'gemma2-9b-it':            'Gemma 2 9B',
                        'qwen/qwen3-32b':          'Qwen 3 32B (Free tier: 6K TPM — too low for tools)',
                    },
                }.get(provider, {})
                # Pin known models first in our preferred order, then append unknown live models
                pinned_ids = list(known_labels.keys())
                pinned = [
                    {'id': mid, 'label': known_labels[mid]}
                    for mid in pinned_ids if mid in live_ids
                ]
                extras = sorted(
                    [{'id': mid, 'label': mid} for mid in live_ids if mid not in known_labels],
                    key=lambda x: x['id'], reverse=True,
                )
                models = pinned + extras

            elif provider == 'gemini':
                key = getattr(dj_settings, 'GOOGLE_AI_API_KEY', '')
                if not key:
                    return None, 'Google AI API key not configured'
                r = http.get(
                    f'https://generativelanguage.googleapis.com/v1beta/models?key={key}',
                    timeout=timeout,
                )
                if r.status_code != 200:
                    return None, f'Gemini API error {r.status_code}'
                data = r.json().get('models', [])
                models = [
                    {
                        'id': m['name'].replace('models/', ''),
                        'label': m.get('displayName', m['name'].replace('models/', '')),
                    }
                    for m in data
                    if 'generateContent' in m.get('supportedGenerationMethods', [])
                ]
            elif provider == 'router':
                base = (getattr(dj_settings, 'AI_BASE_URL', '') or '').rstrip('/')
                if not base:
                    return None, '9Router base URL (AI_BASE_URL) not set'
                key = getattr(dj_settings, 'AI_API_KEY', '') or ''
                headers = {'Authorization': f'Bearer {key}'} if key else {}
                # Routing "combos" the gateway exposes as pseudo-models (not in /models).
                # 'free' picks an available model automatically — pin it first.
                combos = [{'id': 'free', 'label': 'free — auto-routing combo (recommended)'}]
                live = []
                try:
                    r = http.get(f'{base}/models', headers=headers, timeout=timeout)
                    if r.status_code == 200:
                        payload_json = r.json()
                        rows = payload_json.get('data', payload_json) if isinstance(payload_json, dict) else payload_json
                        _skip = ('asr', 'ctc', 'tts', 'whisper', 'embedding', 'audio',
                                 'rerank', 'moderation', 'image', 'vision-only')
                        live = sorted(
                            [{'id': m['id'], 'label': m.get('name') or m['id']}
                             for m in rows
                             if isinstance(m, dict) and m.get('id')
                             and not any(s in m['id'].lower() for s in _skip)],
                            key=lambda x: x['id'],
                        )
                except Exception:
                    live = []
                # Combos first, then live models (dedupe by id)
                seen = {c['id'] for c in combos}
                models = combos + [m for m in live if m['id'] not in seen]

            else:
                return None, f'Unknown provider: {provider}'

            return models, None

        except Exception as e:
            return None, str(e)

    models, err = _fetch()
    if err:
        return JsonResponse({'error': err}, status=200)

    cache.set(cache_key, models, timeout=3600)
    return JsonResponse({'models': models, 'cached': False})


# FIRST-MILE PICKUP AUTOMATION CONFIG --------------------------------------------------------------------------------------------------

@login_required(login_url='/accounts/login/')
@staff_required
@ensure_csrf_cookie
def pickup_automation_list(request):
    """Staff page: per-business first-mile pickup config (enabled, mode, disposition)."""
    from django.db.models import Count, Q as _Q, Prefetch

    search = request.GET.get('search', '').strip()

    businesses = business_models.Business.objects.filter(
        business_status='active'
    ).annotate(
        active_fleet_count=Count(
            'driver_directory',
            filter=_Q(driver_directory__is_active=True,
                      driver_directory__driver__driver_status='approved'),
            distinct=True,
        ),
    ).prefetch_related(
        Prefetch(
            'driver_directory',
            queryset=business_models.DriverDirectory.objects.filter(
                is_active=True, driver__driver_status='approved',
            ).select_related('driver__profile__user'),
            to_attr='active_fleet',
        ),
    ).order_by('business_name')
    if search:
        businesses = businesses.filter(business_name__icontains=search)

    context = {
        'businesses': businesses,
        'search': search,
        'enabled_count': business_models.Business.objects.filter(
            business_status='active', pickup_task_enabled=True).count(),
    }
    return render(request, 'workforce/pickup_automation_list.html', context)


@login_required(login_url='/accounts/login/')
@staff_required
def pickup_automation_save(request):
    """Save one business row's pickup config (per-row save — no bulk untick footgun)."""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Invalid request'})

    business = business_models.Business.objects.filter(
        business_id=request.POST.get('business_id')).first()
    if not business:
        return JsonResponse({'success': False, 'error': 'Business not found'})

    enabled = request.POST.get('enabled') == '1'
    mode = request.POST.get('mode')
    disposition = request.POST.get('disposition')
    if mode not in dict(business_models.Business.PICKUP_MODE_CHOICES):
        return JsonResponse({'success': False, 'error': 'Invalid pickup mode'})
    if disposition not in dict(business_models.Business.PICKUP_DISPOSITION_CHOICES):
        return JsonResponse({'success': False, 'error': 'Invalid disposition'})

    old = (business.pickup_task_enabled, business.pickup_mode_default,
           business.pickup_disposition_default)
    business.pickup_task_enabled = enabled
    business.pickup_mode_default = mode
    business.pickup_disposition_default = disposition
    business.save(update_fields=[
        'pickup_task_enabled', 'pickup_mode_default', 'pickup_disposition_default'])

    if old != (enabled, mode, disposition):
        logger.info(
            f"[pickup-automation] {request.user.username} set "
            f"{business.business_name} ({business.business_id}): "
            f"enabled={enabled}, mode={mode}, disposition={disposition} (was {old})"
        )
    return JsonResponse({'success': True})


@login_required(login_url='/accounts/login/')
@staff_required
def pickup_fleet_list(request, business_id):
    """JSON: a business's pickup-allowed drivers (DriverDirectory rows)."""
    business = business_models.Business.objects.filter(business_id=business_id).first()
    if not business:
        return JsonResponse({'success': False, 'error': 'Business not found'})

    rows = business_models.DriverDirectory.objects.filter(
        business=business
    ).select_related('driver__profile__user').order_by('-is_active', 'driver__driver_code')
    return JsonResponse({
        'success': True,
        'drivers': [
            {
                'id': row.id,
                'driver_id': row.driver_id,
                'name': str(row.driver),
                'code': row.driver.driver_code or '',
                'status': row.driver.driver_status,
                'is_active': row.is_active,
            }
            for row in rows
        ],
    })


@login_required(login_url='/accounts/login/')
@staff_required
def pickup_fleet_driver_search(request):
    """JSON: approved drivers matching ?q= (to add to a business fleet)."""
    from django.db.models import Q as _Q

    q = request.GET.get('q', '').strip()
    drivers = fleet_models.Driver.objects.filter(
        driver_status='approved').select_related('profile__user')
    if q:
        drivers = drivers.filter(
            _Q(driver_code__icontains=q)
            | _Q(profile__first_name__icontains=q)
            | _Q(profile__last_name__icontains=q)
            | _Q(profile__user__username__icontains=q)
        )
    return JsonResponse({
        'success': True,
        'drivers': [
            {'id': d.pk, 'name': str(d), 'code': d.driver_code or ''}
            for d in drivers.order_by('driver_code')[:20]
        ],
    })


@login_required(login_url='/accounts/login/')
@staff_required
def pickup_fleet_update(request):
    """
    Mutate a business's pickup fleet. POST action:
      add    (business_id, driver_id)  — link a driver
      toggle (row_id)                  — flip is_active
      remove (row_id)                  — delete the link
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Invalid request'})

    action = request.POST.get('action')

    if action == 'add':
        business = business_models.Business.objects.filter(
            business_id=request.POST.get('business_id')).first()
        driver = fleet_models.Driver.objects.filter(
            pk=request.POST.get('driver_id'), driver_status='approved').first()
        if not business or not driver:
            return JsonResponse({'success': False, 'error': 'Business or driver not found'})
        row, created = business_models.DriverDirectory.objects.get_or_create(
            business=business, driver=driver)
        if not created and not row.is_active:
            row.is_active = True
            row.save(update_fields=['is_active'])
        logger.info(
            f"[pickup-fleet] {request.user.username} added driver {driver.driver_code} "
            f"to {business.business_name} ({business.business_id})"
        )
        return JsonResponse({'success': True, 'created': created})

    row = business_models.DriverDirectory.objects.filter(
        pk=request.POST.get('row_id')).select_related('business', 'driver').first()
    if not row:
        return JsonResponse({'success': False, 'error': 'Fleet entry not found'})

    if action == 'toggle':
        row.is_active = not row.is_active
        row.save(update_fields=['is_active'])
        logger.info(
            f"[pickup-fleet] {request.user.username} set driver {row.driver.driver_code} "
            f"{'active' if row.is_active else 'inactive'} for {row.business.business_name}"
        )
        return JsonResponse({'success': True, 'is_active': row.is_active})

    if action == 'remove':
        logger.info(
            f"[pickup-fleet] {request.user.username} removed driver {row.driver.driver_code} "
            f"from {row.business.business_name} ({row.business.business_id})"
        )
        row.delete()
        return JsonResponse({'success': True})

    return JsonResponse({'success': False, 'error': 'Unknown action'})


@login_required(login_url='/accounts/login/')
@staff_required
@ensure_csrf_cookie
def pickup_pool_status(request):
    """Staff pickup pool — all first-mile pickup tasks with filters and assign actions."""
    from delivery.models import PickupTask
    from django.core.paginator import Paginator
    from django.db.models import Count

    status_filter = request.GET.get('status', 'all')
    mode_filter = request.GET.get('mode', 'all')
    search = request.GET.get('search', '').strip()

    qs = PickupTask.objects.select_related(
        'order', 'business', 'pickup_location', 'driver',
        'transfer_to_driver', 'drop_warehouse__warehouse',
    ).order_by('-id')

    status_counts = dict(
        PickupTask.objects.values_list('status').annotate(cnt=Count('id')))
    active_statuses = ['pending', 'accepted', 'in_progress', 'arrived', 'collected']

    if status_filter == 'active':
        qs = qs.filter(status__in=active_statuses)
    elif status_filter != 'all':
        qs = qs.filter(status=status_filter)
    if mode_filter != 'all':
        qs = qs.filter(pickup_mode=mode_filter)
    if search:
        qs = qs.filter(
            Q(order__order_number__icontains=search)
            | Q(business__business_name__icontains=search)
            | Q(driver__driver_code__icontains=search)
        )

    try:
        per_page = int(request.GET.get('per_page', 25))
    except (TypeError, ValueError):
        per_page = 25
    per_page = per_page if per_page in (10, 25, 50, 100) else 25
    paginator = Paginator(qs, per_page)
    page_obj = paginator.get_page(request.GET.get('page', 1))

    context = {
        'page_obj': page_obj,
        'pickups': page_obj.object_list,
        'status_filter': status_filter,
        'mode_filter': mode_filter,
        'search': search,
        'per_page': per_page,
        'status_counts': status_counts,
        'pending_count': status_counts.get('pending', 0),
        'active_count': sum(status_counts.get(s, 0) for s in active_statuses),
        'status_choices': PickupTask.PICKUP_STATUS_CHOICES,
    }
    return render(request, 'workforce/pickup_pool_status.html', context)


@login_required(login_url='/accounts/login/')
@staff_required
def pickup_staff_assign(request):
    """Staff assigns/reassigns a driver on a pickup task. POST: pickup_id, driver_id."""
    from delivery.models import PickupTask

    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Invalid request'})

    pickup = PickupTask.objects.select_related('order', 'driver').filter(
        pk=request.POST.get('pickup_id')).first()
    if not pickup:
        return JsonResponse({'success': False, 'error': 'Pickup not found'})
    if pickup.status not in ('pending', 'accepted', 'in_progress', 'arrived'):
        return JsonResponse({'success': False, 'error': f'Cannot assign in status {pickup.status}'})

    driver = fleet_models.Driver.objects.filter(
        pk=request.POST.get('driver_id'), driver_status='approved').first()
    if not driver:
        return JsonResponse({'success': False, 'error': 'Approved driver not found'})
    if pickup.driver_id == driver.pk:
        return JsonResponse({'success': False, 'error': 'Already assigned to this driver'})

    previous = pickup.driver
    old_status = pickup.status
    pickup.driver = driver
    pickup.status = 'accepted'
    pickup.accepted_at = timezone.now()
    pickup.save(update_fields=['driver', 'status', 'accepted_at', 'updated_at'])

    from delivery.services.pickup import log_pickup_history
    log_pickup_history(
        pickup, old_status, 'accepted', actor=request.user,
        notes=f"Staff assigned {driver}" + (f" (was {previous})" if previous else ""))

    fleet_models.DriverNotification.objects.create(
        driver=driver,
        title='Pickup assigned to you',
        message=(
            f"Staff assigned you pickup {pickup.order.order_number} — collect from "
            f"{pickup.pickup_location.pickup_location_title if pickup.pickup_location else pickup.business.business_name}."
        ),
        notification_type='pickup_available',
    )
    if previous:
        fleet_models.DriverNotification.objects.create(
            driver=previous,
            title='Pickup reassigned',
            message=f"Pickup {pickup.order.order_number} was reassigned to another driver by staff.",
            notification_type='alert',
        )
    logger.info(
        f"[pickup-assign] {request.user.username} assigned pickup {pickup.pk} "
        f"({pickup.order.order_number}) to {driver.driver_code}"
        + (f" (was {previous.driver_code})" if previous else "")
    )
    return JsonResponse({'success': True})
